// Scripted demo sequencer. Ported from the Claude Design bundle
// (launstack/project/hero-demo.js). Types a question into the composer,
// checks source nodes, streams a cited answer into the thread, loops.

import type { HeroGraphApi } from './heroGraph';

type Beat = {
  q: string;
  checked: string[];
  cited: Array<{ id: string; label: string }>;
  stream: Array<{ text?: string; strong?: boolean; cite?: number }>;
};

const SCRIPT: Beat[] = [
  {
    q: 'What did our interviewees actually say about privacy?',
    checked: ['maya', 'jordan', 'priya', 'ravi', 'synth'],
    cited: [
      { id: 'maya',   label: 'Maya K. · 12:04' },
      { id: 'jordan', label: 'Jordan R. · 08:31' },
      { id: 'priya',  label: 'Priya S. · 04:12' },
    ],
    stream: [
      { text: 'Across ' },
      { text: '4 recordings', strong: true },
      { text: ', privacy was the ' },
      { text: '#1 repeated objection', strong: true },
      { text: '. Specifically:\n\n' },
      { text: '· "I don\u2019t trust AI with my notes." ' },
      { cite: 0 },
      { text: '\n· Wants on-device processing. ' },
      { cite: 1 },
      { text: '\n· Left Notion after data-training news. ' },
      { cite: 2 },
      { text: '\n\n' },
      { text: 'Next step:', strong: true },
      { text: ' make privacy the headline of pricing — not a footnote.' },
    ],
  },
  {
    q: 'Which competitors already address this?',
    checked: ['linear', 'granola', 'mem', 'notion-ai'],
    cited: [
      { id: 'linear',    label: 'Linear teardown · p.4' },
      { id: 'granola',   label: 'Granola notes' },
      { id: 'notion-ai', label: 'Notion AI changelog' },
    ],
    stream: [
      { text: 'Three direct comparables:\n\n' },
      { text: '· Linear', strong: true },
      { text: ' ships per-workspace opt-out and SOC 2 badges on every export. ' },
      { cite: 0 },
      { text: '\n· Granola', strong: true },
      { text: ' processes audio fully on-device. ' },
      { cite: 1 },
      { text: '\n· Notion AI', strong: true },
      { text: ' added a data-training toggle after backlash. ' },
      { cite: 2 },
      { text: '\n\nYou\u2019re the only one combining ' },
      { text: 'all three', strong: true },
      { text: '.' },
    ],
  },
  {
    q: 'Draft two privacy headlines I can A/B test.',
    checked: ['synth', 'linear', 'privacy'],
    cited: [
      { id: 'synth',  label: 'Synthesis notes' },
      { id: 'linear', label: 'Linear teardown' },
    ],
    stream: [
      { text: 'Based on ' },
      { text: '"trust" ', strong: true },
      { text: 'appearing ' },
      { text: '11 times ', strong: true },
      { text: 'in your interviews ' },
      { cite: 0 },
      { text: ':\n\n' },
      { text: 'A. ', strong: true },
      { text: '"Your notes never train a model. Not ours. Not anyone\u2019s."\n\n' },
      { text: 'B. ', strong: true },
      { text: '"Private by default. On-device when you ask."\n\n' },
      { text: 'B borrows Granola\u2019s language; A is more directly differentiated.' },
    ],
  },
];

const sleep = (ms: number) => new Promise<void>(r => setTimeout(r, ms));

function ce<K extends keyof HTMLElementTagNameMap>(tag: K, cls?: string, txt?: string): HTMLElementTagNameMap[K] {
  const el = document.createElement(tag);
  if (cls) el.className = cls;
  if (txt != null) el.textContent = txt;
  return el;
}

export type HeroDemoHandle = { stop(): void };

export function runHeroDemo(
  hero: HeroGraphApi,
  composer: HTMLElement,
  thread: HTMLElement,
  classes: {
    msg: string; msgUser: string; msgAi: string;
    sources: string; chip: string; body: string; inlineChip: string;
    typing: string;
  },
): HeroDemoHandle {
  let cancelled = false;

  async function typeInto(el: HTMLElement, text: string, perChar = 22) {
    for (let i = 0; i < text.length; i++) {
      if (cancelled) return;
      el.textContent = text.slice(0, i + 1);
      el.parentElement?.scrollTo({ top: 99999 });
      await sleep(perChar + (text[i] === ' ' ? 10 : 0));
    }
  }

  async function runBeat(beat: Beat) {
    while (thread.children.length > 6) thread.removeChild(thread.firstChild!);

    composer.textContent = '';
    composer.classList.add(classes.typing);
    await typeInto(composer, beat.q, 26);
    composer.classList.remove(classes.typing);
    await sleep(250);

    const userBubble = ce('div', `${classes.msg} ${classes.msgUser}`, beat.q);
    thread.appendChild(userBubble);
    composer.textContent = '';
    if (cancelled) return;

    hero.checkNodes(
      Object.keys(hero.graph.nodeById).filter(id => !beat.checked.includes(id)),
      false,
    );
    hero.checkNodes(beat.checked, true);
    hero.magnetizeTo(beat.checked, 140, -10, 0.04);
    await sleep(400);

    const aiBubble = ce('div', `${classes.msg} ${classes.msgAi}`);
    const chipsRow = ce('div', classes.sources);
    beat.cited.forEach((c, i) => {
      const chip = ce('span', classes.chip);
      chip.dataset.idx = String(i);
      chip.textContent = c.label;
      chipsRow.appendChild(chip);
    });
    aiBubble.appendChild(chipsRow);
    const body = ce('div', classes.body);
    aiBubble.appendChild(body);
    thread.appendChild(aiBubble);

    for (const tok of beat.stream) {
      if (cancelled) return;
      if (tok.cite != null) {
        const cited = beat.cited[tok.cite]!;
        const inline = ce('span', classes.inlineChip, cited.label);
        body.appendChild(inline);
        hero.pulseNodes([cited.id], 1);
        await sleep(280);
      } else if (tok.strong) {
        const s = ce('strong');
        body.appendChild(s);
        await typeInto(s, tok.text ?? '', 14);
      } else {
        const span = ce('span');
        body.appendChild(span);
        await typeInto(span, tok.text ?? '', 14);
      }
    }

    await sleep(3800);
  }

  (async function loop() {
    let i = 0;
    while (!cancelled) {
      await runBeat(SCRIPT[i % SCRIPT.length]!);
      i++;
    }
  })();

  return { stop() { cancelled = true; } };
}

import { OpenAIEmbeddings } from "@langchain/openai";
import { LRUCache } from "lru-cache";
import { sanitizeErrorMessage } from "~/app/api/agents/predictive-document-analysis/utils/logging";

const EMBEDDING_MODEL = "text-embedding-3-large";
const MAX_CACHE_ENTRIES = 500;

const embeddingCache = new LRUCache<string, number[]>({
    max: MAX_CACHE_ENTRIES,
});

export async function getEmbeddings(text: string): Promise<number[]> {
    const cached = embeddingCache.get(text);
    if (cached) {
        return cached;
    }

    try {
        const apiKey = process.env.EMBEDDING_API_KEY || process.env.AI_API_KEY || process.env.OPENAI_API_KEY;
        const baseURL = process.env.EMBEDDING_API_BASE_URL || process.env.AI_BASE_URL;
        const embeddings = new OpenAIEmbeddings({
            openAIApiKey: apiKey,
            modelName: EMBEDDING_MODEL,
            dimensions: 1536,
            ...(baseURL ? { configuration: { baseURL } } : {}),
        });

        const [embedding] = await embeddings.embedDocuments([text]);
        const result = embedding ?? [];

        embeddingCache.set(text, result);
        return result;
    } catch (error) {
        console.error("Error getting embeddings:", sanitizeErrorMessage(error));
        return [];
    }
}

export async function batchGetEmbeddings(texts: string[]): Promise<number[][]> {
    const uniqueTexts = [...new Set(texts)];

    try {
        const apiKey = process.env.EMBEDDING_API_KEY || process.env.AI_API_KEY || process.env.OPENAI_API_KEY;
        const baseURL = process.env.EMBEDDING_API_BASE_URL || process.env.AI_BASE_URL;
        const embeddings = new OpenAIEmbeddings({
            openAIApiKey: apiKey,
            modelName: EMBEDDING_MODEL,
            dimensions: 1536,
            ...(baseURL ? { configuration: { baseURL } } : {}),
        });

        const results = await embeddings.embedDocuments(uniqueTexts);
        const embeddingMap = new Map(uniqueTexts.map((text, i) => [text, results[i]]));

        embeddingMap.forEach((embedding, text) => {
            embeddingCache.set(text, embedding ?? []);
        });

        return texts.map(text => embeddingMap.get(text) ?? []);
    } catch (error) {
        console.error("Error getting batch embeddings:", sanitizeErrorMessage(error));
        return texts.map(() => []);
    }
}

export function clearEmbeddingCache(): void {
    embeddingCache.clear();
}

export function getEmbeddingCacheStats() {
    return {
        size: embeddingCache.size,
        maxSize: MAX_CACHE_ENTRIES,
    };
}

/**
 * Document Versions API
 *
 * POST /api/documents/[id]/versions
 *   Upload a new version of an existing document. The caller is responsible
 *   for uploading the replacement file to blob storage first (same as the
 *   initial upload flow) and then handing this endpoint the resulting URL.
 *
 *   Enforces:
 *     - Auth (employer/owner of the document's company)
 *     - Exact MIME match against the document's `file_type` (locked in on v1)
 *     - Sequential version numbering (max + 1, atomically)
 *
 *   Side effects:
 *     - Inserts a new row in `document_versions`
 *     - Updates `document.current_version_id` to point at it
 *     - Triggers the OCR-to-Vector pipeline with the new versionId so fresh
 *       embeddings get tagged with this version. Old version embeddings are
 *       intentionally retained (per-version storage) to make revert O(1).
 *     - Inserts an `ocr_jobs` row for tracking
 *
 * GET /api/documents/[id]/versions
 *   List all versions of a document, newest first, with an `isCurrent` flag.
 *   Used by the frontend version-history panel.
 */

import { NextResponse } from "next/server";
import type { ObjectRef } from "@launchstack/core/storage";
import { auth } from "@clerk/nextjs/server";
import { and, desc, eq, sql } from "drizzle-orm";
import { z } from "zod";

import { db } from "~/server/db";
import {
  document,
  documentVersions,
  ocrJobs,
  users,
} from "@launchstack/core/db/schema";
import { registerObject } from "~/server/services/storage-manifest";
import { promoteLegacyUrlToRef } from "~/server/storage/legacy-promote";
import { parseProvider, triggerDocumentProcessing } from "@launchstack/core/ocr/trigger";
import { getEngine } from "~/server/engine";
import { validateRequestBody } from "~/lib/validation";
import { withRateLimit } from "~/lib/rate-limit-middleware";
import { RateLimitPresets } from "~/lib/rate-limiter";
import { resolveActiveCompanyForUser } from "~/lib/active-workspace";

const AUTHORIZED_ROLES = new Set(["employer", "owner"]);

const ObjectRefSchema = z.object({
  adapter: z.enum(["s3", "vercel-blob", "database", "uploadthing"]),
  storageLocationId: z.string().min(1),
  key: z.string().min(1),
});

const CreateVersionSchema = z.object({
  /** URL of the already-uploaded replacement file in blob storage */
  documentUrl: z.string().min(1, "documentUrl is required"),
  /** Exact MIME type — must match document.fileType */
  mimeType: z.string().min(1, "mimeType is required"),
  /** Original filename for adapter routing (used by OCR pipeline) */
  originalFilename: z.string().optional(),
  /** Optional user-supplied note describing what changed in this version */
  changelog: z.string().max(2000).optional(),
  /** Optional preferred OCR provider */
  preferredProvider: z.string().optional(),
  /** File size in bytes, for display in version history UI */
  fileSize: z.number().int().nonnegative().optional(),
  storageRef: ObjectRefSchema.optional(),
});

function resolveVersionRef(documentUrl: string, supplied?: ObjectRef): ObjectRef {
  if (supplied) return supplied;
  const promoted = promoteLegacyUrlToRef({ value: documentUrl });
  if (!promoted.ok) {
    throw new Error(`Version upload requires an adapter ObjectRef (${promoted.reason})`);
  }
  return promoted.ref;
}

/**
 * Parse and validate the `[id]` route parameter.
 * Returns the numeric document id or an error response.
 */
function parseDocumentId(rawId: string):
  | { ok: true; documentId: number }
  | { ok: false; response: NextResponse } {
  const documentId = Number(rawId);
  if (!Number.isInteger(documentId) || documentId <= 0) {
    return {
      ok: false,
      response: NextResponse.json(
        { error: "Invalid document id" },
        { status: 400 }
      ),
    };
  }
  return { ok: true, documentId };
}

/**
 * Load the authenticated user and verify they have employer/owner access
 * to the target document's company. Returns the user + document on success,
 * or a NextResponse error on any failure.
 */
async function authorizeDocumentAccess(documentId: number): Promise<
  | {
      ok: true;
      userId: string;
      companyId: bigint;
      doc: typeof document.$inferSelect;
    }
  | { ok: false; response: NextResponse }
> {
  const { userId } = await auth();
  if (!userId) {
    return {
      ok: false,
      response: NextResponse.json({ error: "Unauthorized" }, { status: 401 }),
    };
  }

  const [userInfo] = await db
    .select()
    .from(users)
    .where(eq(users.userId, userId));

  if (!userInfo) {
    return {
      ok: false,
      response: NextResponse.json({ error: "Unknown user" }, { status: 401 }),
    };
  }

  if (!AUTHORIZED_ROLES.has(userInfo.role)) {
    return {
      ok: false,
      response: NextResponse.json(
        { error: "Forbidden: employer or owner role required" },
        { status: 403 }
      ),
    };
  }

  const [doc] = await db
    .select()
    .from(document)
    .where(eq(document.id, documentId));

  if (!doc) {
    return {
      ok: false,
      response: NextResponse.json(
        { error: "Document not found" },
        { status: 404 }
      ),
    };
  }

  if (doc.companyId !== (await resolveActiveCompanyForUser(userInfo.id, userInfo.companyId))) {
    // Don't leak existence to cross-company requests.
    return {
      ok: false,
      response: NextResponse.json(
        { error: "Document not found" },
        { status: 404 }
      ),
    };
  }

  return { ok: true, userId, companyId: (await resolveActiveCompanyForUser(userInfo.id, userInfo.companyId)), doc };
}

export async function POST(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  return withRateLimit(request, RateLimitPresets.strict, async () => {
    try {
      const { id: rawId } = await context.params;
      const parsed = parseDocumentId(rawId);
      if (!parsed.ok) return parsed.response;

      const authResult = await authorizeDocumentAccess(parsed.documentId);
      if (!authResult.ok) return authResult.response;

      const { userId, doc } = authResult;

      const validation = await validateRequestBody(request, CreateVersionSchema);
      if (!validation.success) {
        return validation.response;
      }

      const {
        documentUrl,
        mimeType,
        originalFilename,
        changelog,
        preferredProvider,
        fileSize,
        storageRef,
      } = validation.data;

      // File type enforcement: exact MIME match against the canonical file_type
      // locked in when the document was first created. Case-insensitive to
      // tolerate header casing differences ("Image/PNG" vs "image/png").
      const expectedFileType = doc.fileType;
      if (!expectedFileType) {
        // A document created before Step 2 rolled out may not have its
        // file_type populated yet. The backfill script fixes this; if it
        // hasn't run, refuse to create a new version rather than locking in
        // the wrong type here.
        return NextResponse.json(
          {
            error:
              "Document file type not yet initialized. Run the versioning backfill before uploading new versions.",
          },
          { status: 409 }
        );
      }

      if (mimeType.toLowerCase() !== expectedFileType.toLowerCase()) {
        return NextResponse.json(
          {
            error: "File type mismatch",
            details: `Document is locked to ${expectedFileType}; received ${mimeType}. New versions must be the same file type as the original.`,
            expected: expectedFileType,
            received: mimeType,
          },
          { status: 400 }
        );
      }

      // Insert the new version + flip currentVersionId atomically. Any concurrent
      // new-version uploads on the same document would race on version_number,
      // but the unique index (document_id, version_number) in the schema
      // guarantees one of them rejects at the DB level — we retry once on that
      // specific violation below.
      const createdVersion = await db.transaction(async (tx) => {
        const [maxRow] = await tx
          .select({
            maxVersion: sql<number>`COALESCE(MAX(${documentVersions.versionNumber}), 0)`,
          })
          .from(documentVersions)
          .where(eq(documentVersions.documentId, BigInt(parsed.documentId)));

        const nextVersionNumber = (maxRow?.maxVersion ?? 0) + 1;

        const [inserted] = await tx
          .insert(documentVersions)
          .values({
            documentId: BigInt(parsed.documentId),
            versionNumber: nextVersionNumber,
            url: documentUrl,
            mimeType,
            fileSize:
              typeof fileSize === "number" ? BigInt(fileSize) : null,
            uploadedBy: userId,
            changelog: changelog ?? null,
            ocrProcessed: false,
          })
          .returning({
            id: documentVersions.id,
            versionNumber: documentVersions.versionNumber,
          });

        if (!inserted) {
          throw new Error("Failed to insert document_versions row");
        }

        await registerObject(tx, {
          ref: resolveVersionRef(documentUrl, storageRef),
          companyId: doc.companyId,
          documentVersionId: inserted.id,
          contentType: mimeType,
          sizeBytes: fileSize,
          sourceOperation: "document-version-upload",
        });

        // Flip currentVersionId to the new row so RAG starts returning the
        // new version's chunks as soon as embeddings land. The brief window
        // between flip and embedding completion is acceptable — search will
        // return zero results for this document during that window, which
        // matches the behavior of a brand new upload.
        //
        // We ALSO update `document.url` and `document.mimeType` to match the
        // new current version. These two columns predate versioning and are
        // treated by every legacy read path (fetchDocument, DocumentViewer,
        // etc.) as "the document's blob." Leaving them frozen on v1 means
        // the main viewer keeps showing v1's content even after v2 becomes
        // current — which is exactly the bug we hit in production. Keep
        // them denormalized in lockstep with `currentVersionId`.
        await tx
          .update(document)
          .set({
            currentVersionId: BigInt(inserted.id),
            url: documentUrl,
            mimeType,
          })
          .where(eq(document.id, parsed.documentId));

        return inserted;
      });

      const companyIdString = doc.companyId.toString();

      // Dispatch the OCR-to-Vector pipeline with the new versionId so every
      // chunk/structure/metadata row gets tagged with this specific version.
      // Old version chunks stay indexed under their own versionId and are
      // hidden from RAG results by the version filter in the retrievers.
      getEngine();
      const { jobId, eventIds } = await triggerDocumentProcessing(
        documentUrl,
        doc.title,
        companyIdString,
        userId,
        parsed.documentId,
        doc.category,
        {
          preferredProvider: parseProvider(preferredProvider),
          mimeType,
          originalFilename,
          versionId: createdVersion.id,
          storageRef: resolveVersionRef(documentUrl, storageRef),
          artifactGroupId: `version:${createdVersion.id}`,
        }
      );

      await db.insert(ocrJobs).values({
        id: jobId,
        companyId: doc.companyId,
        userId,
        status: "queued",
        documentUrl,
        documentName: doc.title,
      });

      console.log(
        `[Versions] Created v${createdVersion.versionNumber} for doc=${parsed.documentId} ` +
          `versionId=${createdVersion.id} jobId=${jobId}`
      );

      return NextResponse.json(
        {
          success: true,
          versionId: createdVersion.id,
          versionNumber: createdVersion.versionNumber,
          documentId: parsed.documentId,
          jobId,
          eventIds,
          message: "New version uploaded, processing started",
        },
        { status: 202 }
      );
    } catch (error) {
      console.error("[Versions] POST failed:", error);

      // The unique (document_id, version_number) constraint violation maps
      // cleanly to a 409 Conflict: another concurrent request won the race.
      // The client should retry; the next attempt will see the bumped max.
      const message =
        error instanceof Error ? error.message : String(error);
      if (message.includes("doc_versions_document_version_unique")) {
        return NextResponse.json(
          {
            error: "Version number conflict",
            details:
              "Another version upload completed first. Please retry this request.",
          },
          { status: 409 }
        );
      }

      return NextResponse.json(
        {
          error: "Failed to create new document version",
          details: message,
        },
        { status: 500 }
      );
    }
  });
}

export async function GET(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { id: rawId } = await context.params;
    const parsed = parseDocumentId(rawId);
    if (!parsed.ok) return parsed.response;

    const authResult = await authorizeDocumentAccess(parsed.documentId);
    if (!authResult.ok) return authResult.response;

    const { doc } = authResult;

    const versions = await db
      .select({
        id: documentVersions.id,
        versionNumber: documentVersions.versionNumber,
        url: documentVersions.url,
        mimeType: documentVersions.mimeType,
        fileSize: documentVersions.fileSize,
        uploadedBy: documentVersions.uploadedBy,
        changelog: documentVersions.changelog,
        ocrProcessed: documentVersions.ocrProcessed,
        ocrProvider: documentVersions.ocrProvider,
        createdAt: documentVersions.createdAt,
      })
      .from(documentVersions)
      .where(eq(documentVersions.documentId, BigInt(parsed.documentId)))
      .orderBy(desc(documentVersions.versionNumber));

    const currentVersionId =
      doc.currentVersionId !== null ? Number(doc.currentVersionId) : null;

    const serialized = versions.map((v) => ({
      id: v.id,
      versionNumber: v.versionNumber,
      url: v.url,
      mimeType: v.mimeType,
      fileSize: v.fileSize !== null ? Number(v.fileSize) : null,
      uploadedBy: v.uploadedBy,
      changelog: v.changelog,
      ocrProcessed: v.ocrProcessed,
      ocrProvider: v.ocrProvider,
      createdAt: v.createdAt,
      isCurrent: v.id === currentVersionId,
    }));

    return NextResponse.json(
      {
        documentId: parsed.documentId,
        fileType: doc.fileType,
        currentVersionId,
        versions: serialized,
      },
      { status: 200 }
    );
  } catch (error) {
    console.error("[Versions] GET failed:", error);
    return NextResponse.json(
      {
        error: "Failed to list document versions",
        details: error instanceof Error ? error.message : String(error),
      },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { auth } from "@clerk/nextjs/server";
import { and, eq } from "drizzle-orm";
import { db } from "~/server/db";
import { category, company, users } from "@launchstack/core/db/schema";
import { resolveStorageBackend } from "~/lib/storage";
import { resolveActiveCompanyForUser } from "~/lib/active-workspace";

type BootstrapCategory = {
  id: string;
  name: string;
};

type BootstrapCompany = {
  id: number;
  name: string;
  useUploadThing: boolean;
} | null;

type UploadBootstrapResponse = {
  categories: BootstrapCategory[];
  company: BootstrapCompany;
  isUploadThingConfigured: boolean;
  availableProviders: {
    azure: boolean;
    datalab: boolean;
    landingAI: boolean;
    docling: boolean;
  };
  storageProvider: "s3" | "database";
  s3Endpoint?: string;
};

export async function GET() {
  try {
    const { userId } = await auth();
    if (!userId) {
      return NextResponse.json(
        { error: "Authentication required." },
        { status: 401 }
      );
    }

    const [userInfo] = await db
      .select({ id: users.id,
        role: users.role,
        companyId: users.companyId,
      })
      .from(users)
      .where(eq(users.userId, userId));

    if (!userInfo) {
      return NextResponse.json({ error: "Invalid user." }, { status: 400 });
    }

    if (userInfo.role !== "employer" && userInfo.role !== "owner") {
      return NextResponse.json(
        { error: "Employer access required." },
        { status: 403 }
      );
    }

    const [categoriesRaw, companyRaw] = await Promise.all([
      db
        .select({
          id: category.id,
          name: category.name,
        })
        .from(category)
        .where(eq(category.companyId, (await resolveActiveCompanyForUser(userInfo.id, userInfo.companyId)))),
      db
        .select({
          id: company.id,
          name: company.name,
          useUploadThing: company.useUploadThing,
        })
        .from(company)
        .where(and(eq(company.id, Number((await resolveActiveCompanyForUser(userInfo.id, userInfo.companyId))))))
        .limit(1),
    ]);

    const response: UploadBootstrapResponse = {
      categories: categoriesRaw.map((item) => ({
        id: String(item.id),
        name: item.name,
      })),
      company: companyRaw[0]
        ? {
            id: Number(companyRaw[0].id),
            name: companyRaw[0].name,
            useUploadThing: companyRaw[0].useUploadThing,
          }
        : null,
      isUploadThingConfigured: Boolean(process.env.UPLOADTHING_TOKEN),
      availableProviders: {
        azure:
          Boolean(process.env.AZURE_DOC_INTELLIGENCE_KEY) &&
          Boolean(process.env.AZURE_DOC_INTELLIGENCE_ENDPOINT),
        datalab: Boolean(process.env.DATALAB_API_KEY),
        landingAI: Boolean(process.env.LANDING_AI_API_KEY),
        docling: Boolean(process.env.OCR_WORKER_URL),
      },
      storageProvider: resolveStorageBackend(),
      ...(resolveStorageBackend() === "s3" && process.env.NEXT_PUBLIC_S3_ENDPOINT
        ? { s3Endpoint: process.env.S3_PUBLIC_ENDPOINT || process.env.NEXT_PUBLIC_S3_ENDPOINT }
        : {}),
    };

    return NextResponse.json(response);
  } catch (error: unknown) {
    console.error("Error fetching upload bootstrap data:", error);
    return NextResponse.json(
      { error: "Unable to fetch upload bootstrap data" },
      { status: 500 }
    );
  }
}

