/**
 * Legal Document Apply Edits API
 * Applies edits as Track Changes in DOCX documents via the Adeu service.
 * Uses paragraph-scoped context disambiguation, then a direct XML cleanup
 * pass to guarantee all placeholder tokens are replaced.
 */

import { NextResponse } from "next/server";
import { auth } from "@clerk/nextjs/server";
import { z } from "zod";
import PizZip from "pizzip";
import {
  processDocumentBatch,
  readDocx,
  AdeuConfigError,
  AdeuServiceError,
  type DocumentEdit,
} from "@launchstack/features/adeu";

export const runtime = "nodejs";

const CONTEXT_CHARS = 40;

const ApplyEditsSchema = z.object({
  documentBase64: z.string(),
  authorName: z.string().default("Legal Review Assistant"),
  edits: z
    .array(
      z.object({
        target_text: z.string(),
        new_text: z.string(),
        comment: z.string().optional(),
      }),
    )
    .optional(),
});

/**
 * Try to make target_text unique by expanding with surrounding context,
 * staying within the same paragraph (single-newline-delimited block).
 * Returns null if the target doesn't exist in the text.
 */
function tryDisambiguate(
  targetText: string,
  newText: string,
  comment: string | undefined,
  docText: string,
): DocumentEdit | null {
  const firstIdx = docText.indexOf(targetText);
  if (firstIdx === -1) return null;

  const secondIdx = docText.indexOf(targetText, firstIdx + 1);
  if (secondIdx === -1) {
    return { target_text: targetText, new_text: newText, comment };
  }

  // Find paragraph boundaries (single newline blocks)
  const paraStart = (() => {
    const idx = docText.lastIndexOf("\n", firstIdx);
    return idx === -1 ? 0 : idx + 1;
  })();
  const paraEnd = (() => {
    const idx = docText.indexOf("\n", firstIdx + targetText.length);
    return idx === -1 ? docText.length : idx;
  })();

  let start = firstIdx;
  let end = firstIdx + targetText.length;
  let expanded = targetText;

  for (let step = 0; step < 10; step++) {
    const newStart = Math.max(paraStart, start - CONTEXT_CHARS);
    const newEnd = Math.min(paraEnd, end + CONTEXT_CHARS);
    if (newStart === start && newEnd === end) break;
    expanded = docText.slice(newStart, newEnd);
    start = newStart;
    end = newEnd;

    const check = docText.indexOf(expanded, 0);
    const check2 = docText.indexOf(expanded, check + 1);
    if (check2 === -1) {
      const expandedNew = expanded.replace(targetText, newText);
      return { target_text: expanded, new_text: expandedNew, comment };
    }
  }

  // Still ambiguous — return the original (will be handled by XML cleanup)
  return null;
}

/**
 * Final cleanup: open the DOCX XML, find any remaining __FLD_*__ tokens,
 * and replace them directly. These won't show as track changes but
 * guarantee no placeholder tokens leak into the final document.
 */
function cleanupRemainingTokens(
  docBuffer: Buffer,
  edits: Array<{ target_text: string; new_text: string }>,
): Buffer<ArrayBuffer> {
  const zip = new PizZip(docBuffer);
  const tokenMap = new Map<string, string>();
  for (const e of edits) {
    tokenMap.set(e.target_text, e.new_text);
  }

  // Process all XML parts in the DOCX
  for (const [filename, entry] of Object.entries(zip.files)) {
    if (!filename.endsWith(".xml") && !filename.endsWith(".rels")) continue;
    if (entry.dir) continue;

    let content = entry.asText();
    let changed = false;
    for (const [token, replacement] of tokenMap) {
      if (content.includes(token)) {
        content = content.split(token).join(replacement);
        changed = true;
      }
    }
    if (changed) {
      zip.file(filename, content);
    }
  }

  return zip.generate({ type: "nodebuffer", compression: "DEFLATE" }) as Buffer<ArrayBuffer>;
}

export async function POST(request: Request) {
  try {
    const { userId } = await auth();
    if (!userId) {
      return NextResponse.json(
        { success: false, message: "Unauthorized" },
        { status: 401 },
      );
    }

    const body = await request.json();
    const parsed = ApplyEditsSchema.safeParse(body);

    if (!parsed.success) {
      return NextResponse.json(
        {
          success: false,
          error: "Invalid request",
          details: parsed.error.errors,
        },
        { status: 400 },
      );
    }

    const { documentBase64, authorName, edits } = parsed.data;
    const docBuffer = Buffer.from(documentBase64, "base64");

    if (!edits || edits.length === 0) {
      return NextResponse.json({
        success: true,
        modifiedDocxBase64: documentBase64,
        summary: {
          applied_edits: 0,
          skipped_edits: 0,
          applied_actions: 0,
          skipped_actions: 0,
        },
      });
    }

    let currentDoc = docBuffer;
    let totalApplied = 0;
    let totalSkipped = 0;
    const rawEdits = edits as DocumentEdit[];
    const failedEdits: Array<{ target_text: string; new_text: string }> = [];

    // Phase 1: Apply each edit via Adeu (with track changes)
    for (const edit of rawEdits) {
      try {
        const { text: currentText } = await readDocx(currentDoc);
        const normalised = currentText.replace(/\r\n/g, "\n");
        const resolved = tryDisambiguate(
          edit.target_text,
          edit.new_text,
          edit.comment,
          normalised,
        );

        if (!resolved) {
          failedEdits.push(edit);
          continue;
        }

        const result = await processDocumentBatch(currentDoc, {
          author_name: authorName,
          edits: [resolved],
        });
        currentDoc = Buffer.from(await result.file.arrayBuffer());
        totalApplied += result.summary.applied_edits;
        totalSkipped += result.summary.skipped_edits;
      } catch (err) {
        console.warn(
          "[apply-edits] Adeu failed, deferring to cleanup:",
          edit.target_text.slice(0, 50),
        );
        failedEdits.push(edit);
      }
    }

    // Phase 2: Direct XML cleanup for any tokens Adeu couldn't handle.
    // These replacements won't appear as track changes but ensure no
    // __FLD_*__ tokens remain in the final document.
    if (failedEdits.length > 0) {
      currentDoc = cleanupRemainingTokens(currentDoc, failedEdits);
      totalApplied += failedEdits.length;
    }

    const modifiedDocxBase64 = currentDoc.toString("base64");

    return NextResponse.json({
      success: true,
      modifiedDocxBase64,
      summary: {
        applied_edits: totalApplied,
        skipped_edits: totalSkipped,
        applied_actions: 0,
        skipped_actions: 0,
      },
    });
  } catch (error) {
    console.error("Legal apply edits error:", error);

    if (error instanceof AdeuConfigError) {
      return NextResponse.json(
        {
          success: false,
          error: "Track Changes service not configured",
          message:
            "The Adeu redlining service is not set up. Add ADEU_SERVICE_URL to your .env file (e.g. http://localhost:8000) and ensure the service is running.",
        },
        { status: 503 },
      );
    }

    if (error instanceof AdeuServiceError) {
      console.error("[apply-edits] Adeu error detail:", error.detail);
      return NextResponse.json(
        {
          success: false,
          error: "Track Changes service error",
          message: error.detail,
        },
        { status: 502 },
      );
    }

    return NextResponse.json(
      {
        success: false,
        error: "Internal server error",
        message: error instanceof Error ? error.message : "Unknown error",
      },
      { status: 500 },
    );
  }
}

import { auth } from "@clerk/nextjs/server";
import { eq } from "drizzle-orm";
import { z } from "zod";
import { db } from "~/server/db/index";
import { users } from "@launchstack/core/db/schema";
import { env } from "~/env";
import {
  parseGitHubUrl,
  getRepoContext,
  explainRepoWithLlm,
  extractMermaidCode,
  extractSummary,
  type RepoInfo,
  type RepoExplanationRequest,
} from "@launchstack/features/repo-explainer";
import { validateRequestBody } from "~/lib/validation";
import {
  createSuccessResponse,
  createUnauthorizedError,
  createForbiddenError,
  createValidationError,
  handleApiError,
} from "~/lib/api-utils";

export const runtime = "nodejs";
export const maxDuration = 120;

const DIAGRAM_TYPES = ["architecture", "sequence", "class", "er", "component"] as const;

const RepoExplainerRequestSchema = z.object({
  url: z.string().min(1, "GitHub URL is required"),
  instructions: z.string().optional(),
  diagramType: z.enum(DIAGRAM_TYPES).optional(),
});

async function validateRepoAccess(
  owner: string,
  repo: string,
  githubToken?: string | null,
): Promise<string | null> {
  try {
    const res = await fetch(`https://api.github.com/repos/${owner}/${repo}`, {
      method: "GET",
      headers: {
        Accept: "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
        ...(githubToken ? { Authorization: `Bearer ${githubToken}` } : {}),
      },
      cache: "no-store",
    });
    if (res.status === 404) {
      return githubToken
        ? `Repository '${owner}/${repo}' not found or token does not have access.`
        : `Repository '${owner}/${repo}' not found or is private. Add a GitHub token with access for private repos.`;
    }
    if (res.status === 403) {
      return githubToken
        ? `Access forbidden for '${owner}/${repo}'. Check token permissions and repo access.`
        : `Repository '${owner}/${repo}' is private or access is forbidden. Add a GitHub token.`;
    }
    if (res.status === 401) {
      return "Invalid GitHub token.";
    }
    if (res.status === 429) {
      return "Too many requests to GitHub. Please try again later.";
    }
    if (!res.ok) {
      return `Error accessing repository '${owner}/${repo}' (HTTP ${res.status}).`;
    }
    return null;
  } catch (error) {
    console.error("[repo-explainer] validateRepoAccess error:", error);
    return "Could not validate repository on GitHub. Please try again.";
  }
}

export async function POST(request: Request) {
  try {
    const { userId } = await auth();
    if (!userId) {
      return createUnauthorizedError("Authentication required. Please sign in to continue.");
    }

    const [userInfo] = await db
      .select()
      .from(users)
      .where(eq(users.userId, userId));

    if (!userInfo) {
      return createUnauthorizedError("User account not found.");
    }

    if (userInfo.role !== "employer" && userInfo.role !== "owner") {
      return createForbiddenError("Insufficient permissions. Only employers and owners can use the repo explainer.");
    }

    const validation = await validateRequestBody(request, RepoExplainerRequestSchema);
    if (!validation.success) {
      return validation.response;
    }

    const { url, instructions, diagramType } = validation.data as RepoExplanationRequest;

    const parsedUrl = parseGitHubUrl(url);
    if (!parsedUrl) {
      return createValidationError(
        "Invalid GitHub URL format. Please use: https://github.com/owner/repo or owner/repo",
      );
    }

    const { owner, repo } = parsedUrl;
    const githubToken =
      request.headers.get("X-GitHub-Token") ||
      env.server.GITHUB_TOKEN ||
      null;

    const validationError = await validateRepoAccess(owner, repo, githubToken);
    if (validationError) {
      return createValidationError(validationError);
    }

    const repoInfo: RepoInfo = { owner, repoName: repo };

    const contextResult = await getRepoContext(repoInfo, null, githubToken, undefined, diagramType);
    if (!contextResult.success) {
      return handleApiError(
        new Error(contextResult.error ?? "Failed to fetch repository context"),
      );
    }

    const explanationResult = await explainRepoWithLlm(
      repoInfo,
      contextResult.context,
      instructions,
      diagramType,
    );

    if (!explanationResult.success) {
      return handleApiError(
        new Error(explanationResult.error ?? "Failed to generate explanation"),
      );
    }

    const timestamp = new Date().toISOString();
    const repoFullName = `${owner}/${repo}`;
    const summary = extractSummary(explanationResult.explanation);
    const mermaidCode = extractMermaidCode(explanationResult.explanation);

    return createSuccessResponse({
      explanation: explanationResult.explanation,
      repo: repoFullName,
      summary,
      mermaidCode,
      umlJson: {
        format: "mermaid",
        repo: repoFullName,
        summary,
        diagram: mermaidCode,
        generatedAt: timestamp,
      },
      timestamp,
    });
  } catch (error) {
    console.error("[repo-explainer] POST error:", error);
    return handleApiError(error);
  }
}

import {db} from "~/server/db";
import {company, users, userCompanyMemberships} from "@launchstack/core/db/schema";
import {eq} from "drizzle-orm";
import {handleApiError, createSuccessResponse, createValidationError} from "~/lib/api-utils";
import { initTokenAccount, TOKEN_SIGNUP_BONUS } from "~/lib/credits";
import { validateRequestBody, EmployerCompanySignupSchema } from "~/lib/validation";
import { upsertCompanyCredentials } from "@launchstack/core/embeddings";
import { generateUniqueSlug } from "~/lib/workspace-slug";

export async function POST(request: Request) {
    try {
        const validation = await validateRequestBody(request, EmployerCompanySignupSchema);
        if (!validation.success) return validation.response;
        const {
            userId,
            name,
            email,
            companyName,
            numberOfEmployees,
            embeddingIndexKey,
            embeddingOpenAIApiKey,
            embeddingHuggingFaceApiKey,
            embeddingOllamaBaseUrl,
            embeddingOllamaModel,
        } = validation.data;

        // Check if company already exists
        const [existingCompany] = await db
            .select()
            .from(company)
            .where(eq(company.name, companyName));

        if (existingCompany) {
            return createValidationError(
                "Company already exists. Please use a different company name."
            );
        }

        const slug = await generateUniqueSlug(companyName);

        const [newCompany] = await db
            .insert(company)
            .values({
                name: companyName,
                slug,
                numberOfEmployees: numberOfEmployees || "0",
                embeddingIndexKey: embeddingIndexKey?.trim() || null,
            })
            .returning({ id: company.id });

        if(!newCompany) {
            console.error("Company creation returned no data. Database insert failed.");
            return createValidationError(
                "Could not create company. Please try again later."
            );
        }

        const companyId = BigInt(newCompany.id);

        // Persist embedding provider credentials into the encrypted table.
        // Empty/null values are skipped so we never write empty ciphertext.
        const credentialsInput: {
            openAIApiKey?: string | null;
            huggingFaceApiKey?: string | null;
            ollamaBaseUrl?: string | null;
            ollamaModel?: string | null;
        } = {};
        if (embeddingOpenAIApiKey?.trim()) {
            credentialsInput.openAIApiKey = embeddingOpenAIApiKey.trim();
        }
        if (embeddingHuggingFaceApiKey?.trim()) {
            credentialsInput.huggingFaceApiKey = embeddingHuggingFaceApiKey.trim();
        }
        if (embeddingOllamaBaseUrl?.trim()) {
            credentialsInput.ollamaBaseUrl = embeddingOllamaBaseUrl.trim();
        }
        if (embeddingOllamaModel?.trim()) {
            credentialsInput.ollamaModel = embeddingOllamaModel.trim();
        }

        if (Object.keys(credentialsInput).length > 0) {
            try {
                await upsertCompanyCredentials(newCompany.id, credentialsInput);
            } catch (credErr) {
                console.error("Failed to persist embedding credentials during signup:", credErr);
                // Fatal — the company row is already created; bubble up so
                // the caller sees the failure and can retry with valid input.
                return handleApiError(credErr);
            }
        }

        const [insertedUser] = await db
            .insert(users)
            .values({
                userId,
                companyId,
                name,
                email,
                status: "verified",
                role: "owner",
            })
            .returning({ id: users.id });

        if (insertedUser) {
            await db.insert(userCompanyMemberships).values({
                userId: BigInt(insertedUser.id),
                companyId,
                role: "owner",
            });
        }

        // Initialize credit account with signup bonus
        await initTokenAccount(companyId, TOKEN_SIGNUP_BONUS);

        return createSuccessResponse(
            { userId, role: "owner" },
            "Company and owner account created successfully."
        );
    }
    catch (error: unknown) {
        console.error("Error during employer company signup:", error);
        if (error instanceof Error) {
            console.error("Error message:", error.message);
            console.error("Error stack:", error.stack);
        }
        return handleApiError(error);
    }
}

import { NextResponse } from "next/server";
import { auth } from "@clerk/nextjs/server";
import { randomUUID } from "node:crypto";
import type { ObjectRef } from "@launchstack/core/storage";

import { putObject, getS3BucketName, ensureBucketExists, getObjectUrl } from "~/server/storage/s3-client";
import { isS3Storage } from "~/lib/storage";
import { resolveStorageLocationId } from "~/lib/storage-location-id";

function sanitizeFilename(filename: string): string {
    return filename.replace(/\s+/g, "-").replace(/[^a-zA-Z0-9.\-_]/g, "");
}

export async function POST(request: Request) {
    try {
        const { userId } = await auth();
        if (!userId) {
            return NextResponse.json(
                { error: "Authentication required" },
                { status: 401 },
            );
        }

        if (!isS3Storage()) {
            return NextResponse.json(
                { error: "S3 upload is not applicable: no S3 endpoint configured" },
                { status: 400 },
            );
        }

        const formData = await request.formData();
        const file = formData.get("file") as File | null;

        if (!file) {
            return NextResponse.json(
                { error: "file is required" },
                { status: 400 },
            );
        }

        const safeName = sanitizeFilename(file.name);
        const objectKey = `documents/${randomUUID()}-${safeName || "upload"}`;
        const bucket = getS3BucketName();

        await ensureBucketExists();

        const buffer = Buffer.from(await file.arrayBuffer());
        await putObject(objectKey, buffer, file.type || "application/octet-stream");

        const url = getObjectUrl(objectKey);
        const ref: ObjectRef = {
            adapter: "s3",
            storageLocationId: resolveStorageLocationId("s3"),
            key: objectKey,
        };

        return NextResponse.json({
            objectKey,
            bucket,
            url,
            ref: {
                adapter: "s3",
                storageLocationId: resolveStorageLocationId("s3"),
                key: objectKey,
            },
        });
    } catch (error) {
        console.error("[StorageUpload] Failed to upload file:", error);
        return NextResponse.json(
            {
                error: "Failed to upload file to storage",
                details: error instanceof Error ? error.message : "Unknown error",
            },
            { status: 500 },
        );
    }
}

import { NextResponse } from "next/server";
import type { ObjectRef } from "@launchstack/core/storage";
import { and, eq } from "drizzle-orm";
import pLimit from "p-limit";
import { z } from "zod";

import { db } from "~/server/db";
import { uploadBatchFiles } from "@launchstack/core/db/schema";
import { withRateLimit } from "~/lib/rate-limit-middleware";
import { RateLimitPresets } from "~/lib/rate-limiter";
import { validateRequestBody } from "~/lib/validation";
import {
  findBatchOwnedByUser,
  refreshBatchAggregates,
  serializeBatch,
  updateBatchStatus,
  type UploadBatchFileRecord,
} from "~/server/services/upload-batches";
import { processDocumentUpload } from "~/server/services/document-upload";

const CommitSchema = z.object({
  userId: z.string().min(1, "User ID is required"),
  preferredProvider: z.string().optional(),
  category: z.string().optional(),
  embeddingIndexKey: z.string().min(1).optional(),
});

const MAX_CONCURRENCY = 3;

export async function POST(
  request: Request,
  { params }: { params: Promise<{ batchId: string }> }
) {
  return withRateLimit(request, RateLimitPresets.strict, async () => {
    const { batchId } = await params;
    if (!batchId) {
      return NextResponse.json({ error: "Batch ID is required" }, { status: 400 });
    }

    const validation = await validateRequestBody(request, CommitSchema);
    if (!validation.success) {
      return validation.response;
    }

    const { userId, preferredProvider, category, embeddingIndexKey } = validation.data;

    const batch = await findBatchOwnedByUser(batchId, userId, true);
    if (!batch) {
      return NextResponse.json({ error: "Batch not found" }, { status: 404 });
    }

    if (["processing"].includes(batch.status)) {
      return NextResponse.json({ error: "Batch is already processing" }, { status: 409 });
    }
    if (["complete"].includes(batch.status)) {
      return NextResponse.json({ error: "Batch has already completed" }, { status: 409 });
    }

    const pendingFiles = batch.files.filter((file) => file.status === "queued");
    if (pendingFiles.length > 0) {
      return NextResponse.json(
        {
          error: "Batch still has files that have not finished uploading",
          files: pendingFiles.map((file) => ({ id: file.id, filename: file.filename, relativePath: file.relativePath })),
        },
        { status: 400 }
      );
    }

    const filesToProcess = batch.files.filter((file) => file.status === "uploaded");
    if (filesToProcess.length === 0) {
      return NextResponse.json({ error: "No uploaded files are ready to commit" }, { status: 400 });
    }

    const startedAt = new Date();
    await updateBatchStatus(batchId, "processing", {
      committedAt: batch.committedAt ?? startedAt,
      processingStartedAt: startedAt,
      errorMessage: null,
    });

    const limit = pLimit(MAX_CONCURRENCY);
    type FileProcessResult =
      | { fileId: number; status: "complete"; documentId: number; jobId: string }
      | { fileId: number; status: "failed"; error: string };

    const processFile = (file: UploadBatchFileRecord): Promise<FileProcessResult> =>
      limit(async () => {
          if (!file.storageUrl) {
            await markFileFailed(batchId, file.id, "Missing storage URL");
            return { fileId: file.id, status: "failed" as const, error: "Missing storage URL" };
          }

          await markFileStatus(batchId, file.id);

          try {
            const uploadResult = await processDocumentUpload({
              user: { userId, companyId: batch.companyId },
              documentName: file.filename,
              rawDocumentUrl: file.storageUrl,
              requestUrl: request.url,
              category: resolveCategory(file.metadata, batch.metadata, category),
              preferredProvider,
              explicitStorageType: inferStorageType(file.storageType),
              mimeType: file.mimeType ?? undefined,
              embeddingIndexKey,
            });

            await db
              .update(uploadBatchFiles)
              .set({
                status: "complete",
                documentId: BigInt(uploadResult.document.id),
                jobId: uploadResult.jobId,
                processedAt: new Date(),
                errorMessage: null,
              })
              .where(and(eq(uploadBatchFiles.id, file.id), eq(uploadBatchFiles.batchId, batchId)));

            return {
              fileId: file.id,
              status: "complete" as const,
              documentId: uploadResult.document.id,
              jobId: uploadResult.jobId,
            };
          } catch (error) {
            const errorMessage = error instanceof Error ? error.message : "Unknown error";
            await markFileFailed(batchId, file.id, errorMessage);

            return { fileId: file.id, status: "failed" as const, error: errorMessage };
          }
        });

    const results = await Promise.all(filesToProcess.map((file) => processFile(file)));

    await refreshBatchAggregates(batchId);

    const failures = results.filter((result): result is Extract<FileProcessResult, { status: "failed" }> => result.status === "failed");
    const now = new Date();
    if (failures.length > 0) {
      await updateBatchStatus(batchId, "failed", {
        failedAt: now,
        errorMessage: failures[0]?.error ?? "One or more files failed",
      });
    } else {
      await updateBatchStatus(batchId, "complete", {
        completedAt: now,
        errorMessage: null,
      });
    }

    const refreshedBatch = await findBatchOwnedByUser(batchId, userId, true);
    if (!refreshedBatch) {
      return NextResponse.json({ error: "Batch not found after commit" }, { status: 404 });
    }

    return NextResponse.json(
      {
        success: failures.length === 0,
        batch: serializeBatch(refreshedBatch),
        results,
      },
      { status: 202 }
    );
  });
}

async function markFileStatus(batchId: string, fileId: number) {
  await db
    .update(uploadBatchFiles)
    .set({ status: "processing", errorMessage: null })
    .where(and(eq(uploadBatchFiles.id, fileId), eq(uploadBatchFiles.batchId, batchId)));
}

async function markFileFailed(batchId: string, fileId: number, message: string) {
  await db
    .update(uploadBatchFiles)
    .set({ status: "failed", errorMessage: message, processedAt: new Date() })
    .where(and(eq(uploadBatchFiles.id, fileId), eq(uploadBatchFiles.batchId, batchId)));
}

function extractStorageRef(value: unknown): ObjectRef | undefined {
  if (!value || typeof value !== "object") return undefined;
  const candidate = (value as { storageRef?: unknown }).storageRef;
  if (!candidate || typeof candidate !== "object") return undefined;
  const ref = candidate as Partial<ObjectRef>;
  if (
    (ref.adapter === "s3" ||
      ref.adapter === "vercel-blob" ||
      ref.adapter === "database" ||
      ref.adapter === "uploadthing") &&
    typeof ref.storageLocationId === "string" &&
    typeof ref.key === "string"
  ) {
    return ref as ObjectRef;
  }
  return undefined;
}

function inferStorageType(value: string | null): "s3" | "database" | undefined {
  if (value === "s3" || value === "database") {
    return value;
  }
  // Legacy rows stored "cloud" (Vercel Blob) — treat as S3 for routing purposes
  if (value === "cloud") {
    return "s3";
  }
  return undefined;
}

function resolveCategory(
  fileMetadata: unknown,
  batchMetadata: unknown,
  fallback?: string
): string | undefined {
  const fileCategory = extractCategory(fileMetadata);
  if (fileCategory) return fileCategory;
  const batchCategory = extractCategory(batchMetadata);
  if (batchCategory) return batchCategory;
  return fallback ?? undefined;
}

function extractCategory(metadata: unknown): string | undefined {
  if (!metadata || typeof metadata !== "object") {
    return undefined;
  }
  const maybeCategory = (metadata as Record<string, unknown>).category;
  return typeof maybeCategory === "string" && maybeCategory.trim().length > 0
    ? maybeCategory
    : undefined;
}

/**
 * Website Upload API Route
 *
 * Accepts a URL, fetches the page HTML, stores it via the unified storage
 * layer, and triggers the existing document processing pipeline.
 *
 * Modes:
 * - Single page (default): fetch one URL, store HTML, trigger pipeline
 * - Crawl mode (crawl=true): dispatches an Inngest crawl job that handles
 *   BFS link discovery and fans out each page through the standard pipeline
 */

import { NextResponse } from "next/server";
import { eq } from "drizzle-orm";
import { z } from "zod";

import { db } from "~/server/db";
import { users } from "@launchstack/core/db/schema";
import { processDocumentUpload } from "~/server/services/document-upload";
import { uploadFile } from "~/lib/storage";
import { validateRequestBody } from "~/lib/validation";
import { withRateLimit } from "~/lib/rate-limit-middleware";
import { RateLimitPresets } from "~/lib/rate-limiter";
import { inngest } from "~/server/inngest/client";
import { resolveActiveCompanyForUser } from "~/lib/active-workspace";

const WebsiteUploadSchema = z.object({
  userId: z.string().min(1, "User ID is required"),
  url: z.string().url("A valid URL is required"),
  title: z.string().optional(),
  category: z.string().optional(),
  crawl: z.boolean().optional(),
  maxDepth: z.number().min(1).max(3).optional(),
  maxPages: z.number().min(1).max(50).optional(),
  jsRender: z.boolean().optional(),
});

const MAX_HTML_BYTES = 10 * 1024 * 1024; // 10 MB cap
const FETCH_TIMEOUT_MS = 30_000;
const DEFAULT_MAX_DEPTH = 2;
const DEFAULT_MAX_PAGES = 20;

function sanitizeForFilename(value: string): string {
  return value.replace(/[^a-zA-Z0-9._-]/g, "-").replace(/-+/g, "-").slice(0, 80);
}

function deriveTitle(html: string, url: string): string {
  const match = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(html);
  const raw = match?.[1]?.trim();
  if (raw && raw.length > 0) {
    return raw.replace(/\s+/g, " ").slice(0, 200);
  }
  try {
    const parsed = new URL(url);
    return `${parsed.hostname}${parsed.pathname}`.replace(/\/+$/, "") || parsed.hostname;
  } catch {
    return url;
  }
}

/**
 * Fetch a page with timeout and validation. Returns null on failure.
 */
async function fetchPage(
  url: string,
): Promise<{ html: string; finalUrl: string } | null> {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), FETCH_TIMEOUT_MS);
  try {
    const response = await fetch(url, {
      redirect: "follow",
      signal: controller.signal,
      headers: {
        "User-Agent":
          "Mozilla/5.0 (compatible; PDR-AI-WebIndexer/1.0; +https://pdr.ai)",
        Accept:
          "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
      },
    });
    clearTimeout(timeout);

    if (!response.ok) return null;

    const contentType = response.headers.get("content-type") ?? "";
    if (!contentType.toLowerCase().includes("html")) return null;

    const arrayBuf = await response.arrayBuffer();
    if (arrayBuf.byteLength > MAX_HTML_BYTES) return null;

    return {
      html: Buffer.from(arrayBuf).toString("utf-8"),
      finalUrl: response.url,
    };
  } catch {
    clearTimeout(timeout);
    return null;
  }
}

/**
 * Fetch a page using the sidecar's Crawl4AI endpoint for JS rendering.
 * Returns null if the sidecar is not configured or fails.
 */
async function fetchPageWithJsRender(
  url: string,
): Promise<{ html: string; finalUrl: string } | null> {
  const sidecarUrl = process.env.SIDECAR_URL;
  if (!sidecarUrl) {
    console.log("[WebsiteUpload] No SIDECAR_URL configured, skipping JS render");
    return null;
  }

  try {
    const response = await fetch(`${sidecarUrl}/crawl`, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ url, max_pages: 1, js_render: true }),
      signal: AbortSignal.timeout(60_000),
    });
    if (response.ok) {
      const data = (await response.json()) as {
        pages?: { url: string; markdown: string }[];
      };
      const page = data.pages?.[0];
      if (page?.markdown) {
        return { html: page.markdown, finalUrl: page.url };
      }
    }
  } catch (error) {
    console.warn("[WebsiteUpload] Sidecar /crawl failed:", error);
  }

  return null;
}

export async function POST(request: Request) {
  return withRateLimit(request, RateLimitPresets.strict, async () => {
    try {
      const validation = await validateRequestBody(request, WebsiteUploadSchema);
      if (!validation.success) {
        return validation.response;
      }

      const { userId, url, title, category, crawl, maxDepth, maxPages, jsRender } =
        validation.data;

      let parsedUrl: URL;
      try {
        parsedUrl = new URL(url);
      } catch {
        return NextResponse.json({ error: "Invalid URL" }, { status: 400 });
      }

      if (parsedUrl.protocol !== "http:" && parsedUrl.protocol !== "https:") {
        return NextResponse.json(
          { error: "Only http(s) URLs are supported" },
          { status: 400 },
        );
      }

      const [userInfo] = await db
        .select()
        .from(users)
        .where(eq(users.userId, userId));

      if (!userInfo) {
        return NextResponse.json({ error: "Invalid user" }, { status: 400 });
      }

      // ------------------------------------------------------------------
      // Crawl mode: dispatch to Inngest and return immediately
      // ------------------------------------------------------------------
      if (crawl) {
        const crawlGroupId = `crawl-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 8)}`;

        console.log(
          `[WebsiteUpload] Dispatching crawl: url=${url}, maxDepth=${maxDepth ?? DEFAULT_MAX_DEPTH}, ` +
            `maxPages=${maxPages ?? DEFAULT_MAX_PAGES}, group=${crawlGroupId}`,
        );

        const { ids } = await inngest.send({
          name: "website/crawl.requested",
          data: {
            url,
            userId,
            companyId: (await resolveActiveCompanyForUser(userInfo.id, userInfo.companyId)).toString(),
            category,
            maxDepth: maxDepth ?? DEFAULT_MAX_DEPTH,
            maxPages: maxPages ?? DEFAULT_MAX_PAGES,
            crawlGroupId,
            requestUrl: request.url,
          },
        });

        return NextResponse.json(
          {
            success: true,
            crawlGroupId,
            eventIds: ids,
            message: `Crawl started for ${parsedUrl.hostname} (up to ${maxPages ?? DEFAULT_MAX_PAGES} pages, depth ${maxDepth ?? DEFAULT_MAX_DEPTH})`,
            sourceUrl: url,
          },
          { status: 202 },
        );
      }

      // ------------------------------------------------------------------
      // Single-page mode
      // ------------------------------------------------------------------
      console.log(
        `[WebsiteUpload] Fetching: ${url}, user=${userId}, jsRender=${jsRender ?? false}`,
      );

      let page: { html: string; finalUrl: string } | null = null;
      let usedJsRender = false;

      if (jsRender) {
        page = await fetchPageWithJsRender(url);
        if (page) usedJsRender = true;
      }

      if (!page) {
        page = await fetchPage(url);
      }

      if (!page) {
        return NextResponse.json(
          { error: "Failed to fetch URL or URL did not return valid HTML" },
          { status: 502 },
        );
      }

      const resolvedTitle = title?.trim() || deriveTitle(page.html, url);
      const filename = `${sanitizeForFilename(resolvedTitle) || "webpage"}.html`;

      // Inject <base> tag for relative URL resolution
      const baseTag = `<base href="${parsedUrl.origin}/">`;
      const enrichedHtml = /<head[^>]*>/i.test(page.html)
        ? page.html.replace(/(<head[^>]*>)/i, `$1${baseTag}`)
        : `${baseTag}${page.html}`;
      const htmlBuffer = Buffer.from(enrichedHtml, "utf-8");

      const uploaded = await uploadFile({
        filename,
        data: htmlBuffer,
        contentType: "text/html",
        userId,
      });

      console.log(
        `[WebsiteUpload] Stored ${htmlBuffer.byteLength} bytes as ${filename} via ${uploaded.provider}`,
      );

      const uploadResult = await processDocumentUpload({
        user: {
          userId,
          companyId: (await resolveActiveCompanyForUser(userInfo.id, userInfo.companyId)),
        },
        documentName: resolvedTitle,
        rawDocumentUrl: uploaded.url,
        requestUrl: request.url,
        category,
        explicitStorageType: uploaded.provider,
        storageRef: uploaded.ref,
        mimeType: "text/html",
        originalFilename: filename,
        isWebsite: true,
      });

      console.log(
        `[WebsiteUpload] Pipeline triggered: jobId=${uploadResult.jobId}, docId=${uploadResult.document.id}`,
      );

      return NextResponse.json(
        {
          success: true,
          jobId: uploadResult.jobId,
          eventIds: uploadResult.eventIds,
          message: `"${resolvedTitle}" is being indexed`,
          document: uploadResult.document,
          sourceUrl: url,
          jsRendered: usedJsRender,
        },
        { status: 202 },
      );
    } catch (error) {
      console.error("[WebsiteUpload] Error:", error);
      return NextResponse.json(
        {
          error: "Failed to index website",
          details: error instanceof Error ? error.message : "Unknown error",
        },
        { status: 500 },
      );
    }
  });
}

/**
 * Process Document API Route
 * Triggers the OCR-to-Vector pipeline via Inngest.
 * Supports both cloud storage (UploadThing) and database storage.
 * Accepts any file type: known types use dedicated adapters; unknown types use best-effort text extraction.
 */

import { NextResponse } from "next/server";
import type { ObjectRef } from "@launchstack/core/storage";
import { eq } from "drizzle-orm";
import { z } from "zod";

import { db } from "~/server/db";
import { users, ocrJobs } from "@launchstack/core/db/schema";
import { processDocumentUpload } from "~/server/services/document-upload";
import { validateRequestBody } from "~/lib/validation";
import { withRateLimit } from "~/lib/rate-limit-middleware";
import { RateLimitPresets } from "~/lib/rate-limiter";
import { resolveActiveCompanyForUser } from "~/lib/active-workspace";
import { resolveStorageLocationId } from "~/lib/storage-location-id";
import { promoteLegacyUrlToRef } from "~/server/storage/legacy-promote";

/**
 * Request validation schema
 * Accepts either a full URL (cloud) or a relative path (database)
 */
const ObjectRefSchema = z.object({
  adapter: z.enum(["s3", "vercel-blob", "database", "uploadthing"]),
  storageLocationId: z.string().min(1),
  key: z.string().min(1),
});

const UploadDocumentSchema = z.object({
  userId: z.string().min(1, "User ID is required"),
  documentUrl: z.string().min(1, "Document URL or path is required"),
  documentName: z.string().min(1, "Document name is required"),
  category: z.string().optional(),
  preferredProvider: z.string().optional(),
  storageType: z.enum(["s3", "database"]).optional(),
  /** MIME type of the uploaded file — used to route non-PDF files to the correct adapter */
  mimeType: z.string().optional(),
  /** Original filename with extension — used for adapter routing when documentName has been cleaned */
  originalFilename: z.string().optional(),
  /** Storage provider identifier for local S3 uploads (e.g. "seaweedfs") */
  storageProvider: z.string().optional(),
  /** S3 object key for local uploads */
  storagePathname: z.string().optional(),
  storageRef: ObjectRefSchema.optional(),
  embeddingIndexKey: z.string().min(1).optional(),
});

function resolveUploadRef(input: {
  documentUrl: string;
  storageProvider?: string;
  storagePathname?: string;
  storageRef?: ObjectRef;
}): ObjectRef | undefined {
  if (input.storageRef) return input.storageRef;

  if (
    (input.storageProvider === "s3" || input.storageProvider === "database") &&
    input.storagePathname
  ) {
    return {
      adapter: input.storageProvider,
      storageLocationId: resolveStorageLocationId(input.storageProvider),
      key: input.storagePathname,
    };
  }

  const promoted = promoteLegacyUrlToRef({ value: input.documentUrl });
  return promoted.ok ? promoted.ref : undefined;
}

export async function POST(request: Request) {
  return withRateLimit(request, RateLimitPresets.strict, async () => {
    try {
      const validation = await validateRequestBody(request, UploadDocumentSchema);
      if (!validation.success) {
        return validation.response;
      }

      const {
        userId,
        documentUrl: rawDocumentUrl,
        documentName,
        category,
        preferredProvider,
        storageType: explicitStorageType,
        mimeType,
        originalFilename,
        storageProvider,
        storagePathname,
        storageRef,
        embeddingIndexKey,
      } = validation.data;

      const requiresCanonicalRef = Boolean(storageProvider || storagePathname);

      if (requiresCanonicalRef) {
        if (!storageRef) {
          return NextResponse.json(
            {
              error:
                "Uploads with storage adapter/path metadata must include a canonical object ref minted at upload time.",
            },
            { status: 400 },
          );
        }

        if (storageProvider && storageRef.adapter !== storageProvider) {
          return NextResponse.json(
            {
              error:
                "storageRef.adapter must match storageProvider for adapter-based uploads.",
            },
            { status: 400 },
          );
        }

        if (storagePathname && storageRef.key !== storagePathname) {
          return NextResponse.json(
            {
              error:
                "storageRef.key must match storagePathname for key-based uploads.",
            },
            { status: 400 },
          );
        }
      }

      const [userInfo] = await db
        .select()
        .from(users)
        .where(eq(users.userId, userId));

      if (!userInfo) {
        console.warn(`[UploadDocument] Rejected: user not found userId=${userId}`);
        return NextResponse.json(
          { error: "Invalid user" },
          { status: 400 }
        );
      }

      const uploadResult = await processDocumentUpload({
        user: {
          userId,
          companyId: (await resolveActiveCompanyForUser(userInfo.id, userInfo.companyId)),
        },
        documentName,
        rawDocumentUrl,
        category,
        preferredProvider,
        explicitStorageType,
        mimeType,
        originalFilename,
        embeddingIndexKey,
        storageRef: resolveUploadRef({
          documentUrl: rawDocumentUrl,
          storageProvider,
          storagePathname,
          storageRef,
        }),
        requestUrl: request.url,
      });

      return NextResponse.json(
        {
          success: true,
          jobId: uploadResult.jobId,
          eventIds: uploadResult.eventIds,
          message: "Document processing started",
          storageType: uploadResult.storageType,
          document: uploadResult.document,
        },
        { status: 202 }
      );
    } catch (error) {
      console.error("[UploadDocument] Error triggering document processing:", error);
      return NextResponse.json(
        {
          error: "Failed to start document processing",
        },
        { status: 500 }
      );
    }
  });
}

export async function GET(request: Request) {
  try {
    const { searchParams } = new URL(request.url);
    const jobId = searchParams.get("jobId");

    if (!jobId) {
      return NextResponse.json(
        { error: "Job ID is required" },
        { status: 400 }
