    return NextResponse.json({
      jobId: job.id,
      status: job.status,
      documentName: job.documentName,
      provider: job.actualProvider ?? job.primaryProvider,
      pageCount: job.pageCount,
      confidenceScore: job.confidenceScore,
      startedAt: job.startedAt,
      completedAt: job.completedAt,
      processingDurationMs: job.processingDurationMs,
      error: job.errorMessage,
    });
  } catch (error) {
    console.error("Error fetching job status:", error);
    return NextResponse.json(
      { error: "Failed to fetch job status" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { auth } from "@clerk/nextjs/server";
import { validateRequestBody, TextToSpeechSchema } from "~/lib/validation";

interface TextToSpeechRequest {
  text: string;
  voiceId?: string;
  modelId?: string;
  stability?: number;
  similarityBoost?: number;
  style?: number;
  useSpeakerBoost?: boolean;
}

const ELEVENLABS_API_KEY = process.env.ELEVENLABS_API_KEY;
const DEFAULT_VOICE_ID = process.env.ELEVENLABS_VOICE_ID ?? "qyFhaJEAwHR0eYLCmlUT";

async function streamElevenLabs(body: TextToSpeechRequest): Promise<NextResponse> {
  const { ElevenLabsClient } = await import("@elevenlabs/elevenlabs-js");
  const client = new ElevenLabsClient({ apiKey: ELEVENLABS_API_KEY });

  const emotionTagMatch = /^\[(\w+)\]\s*(.+)$/.exec(body.text);
  const cleanText = emotionTagMatch?.[2] ?? body.text;

  const voiceId = body.voiceId ?? DEFAULT_VOICE_ID;
  const modelId = body.modelId ?? "eleven_v3";

  console.log("🔊 [TTS/ElevenLabs] Streaming:", cleanText.length, "chars, voice:", voiceId);

  const audioStream = await client.textToSpeech.stream(voiceId, {
    text: body.text,
    modelId,
    voiceSettings: {
      stability: body.stability ?? 0.5,
      similarityBoost: body.similarityBoost ?? 0.75,
      style: body.style ?? 0.0,
      useSpeakerBoost: body.useSpeakerBoost ?? true,
    },
  });

  const stream = new ReadableStream({
    async start(controller) {
      try {
        for await (const chunk of audioStream as unknown as AsyncIterable<Uint8Array | Buffer | ArrayBuffer>) {
          let data: Uint8Array;
          if (chunk instanceof Uint8Array) data = chunk;
          else if (Buffer.isBuffer(chunk)) data = new Uint8Array(chunk);
          else data = new Uint8Array(chunk);
          controller.enqueue(data);
        }
        controller.close();
      } catch (error) {
        console.error("❌ [TTS/ElevenLabs] Streaming error:", error);
        controller.error(error);
      }
    },
  });

  return new NextResponse(stream, {
    status: 200,
    headers: {
      "Content-Type": "audio/mpeg",
      "Cache-Control": "no-cache",
      "Transfer-Encoding": "chunked",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

async function streamOpenAI(body: TextToSpeechRequest): Promise<NextResponse> {
  const OpenAI = (await import("openai")).default;
  const client = new OpenAI({
    apiKey: process.env.OPENAI_API_KEY || process.env.AI_API_KEY,
    ...(process.env.AI_BASE_URL ? { baseURL: process.env.AI_BASE_URL } : {}),
  });

  const voice = (body.voiceId as "alloy" | "echo" | "fable" | "onyx" | "nova" | "shimmer") ?? "nova";

  console.log("🔊 [TTS/OpenAI] Streaming:", body.text.length, "chars, voice:", voice);

  const response = await client.audio.speech.create({
    model: "tts-1",
    voice,
    input: body.text,
    response_format: "mp3",
  });

  const arrayBuffer = await response.arrayBuffer();

  return new NextResponse(arrayBuffer, {
    status: 200,
    headers: {
      "Content-Type": "audio/mpeg",
      "Cache-Control": "no-cache",
      "X-Content-Type-Options": "nosniff",
    },
  });
}

export async function POST(request: Request) {
  try {
    const { userId } = await auth();
    if (!userId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const validation = await validateRequestBody(request, TextToSpeechSchema);
    if (!validation.success) return validation.response;
    const body = validation.data as TextToSpeechRequest;

    if (ELEVENLABS_API_KEY) {
      return await streamElevenLabs(body);
    }

    if (process.env.OPENAI_API_KEY) {
      return await streamOpenAI(body);
    }

    return NextResponse.json(
      { error: "No TTS provider configured. Set ELEVENLABS_API_KEY or OPENAI_API_KEY." },
      { status: 500 }
    );
  } catch (error) {
    console.error("Error in text-to-speech:", error);
    return NextResponse.json(
      { error: "Failed to generate speech" },
      { status: 500 }
    );
  }
}

import { NextResponse } from "next/server";
import { auth } from "@clerk/nextjs/server";
import { eq, desc, count } from "drizzle-orm";
import { z } from "zod";

import { db } from "~/server/db";
import {
    users,
    company,
    userCompanyMemberships,
} from "@launchstack/core/db/schema";
import { initTokenAccount, TOKEN_SIGNUP_BONUS } from "~/lib/credits";
import {
    setActiveWorkspaceCookie,
    getActiveCompanyId,
} from "~/lib/active-workspace";

const SLUG_RE = /^[a-z0-9](?:[a-z0-9-]{0,62}[a-z0-9])?$/;

const CreateWorkspaceSchema = z.object({
    name: z.string().trim().min(1).max(120),
    slug: z
        .string()
        .trim()
        .toLowerCase()
        .min(2)
        .max(64)
        .regex(SLUG_RE, "Slug must be lowercase letters, numbers, or dashes."),
    swatch: z.number().int().min(1).max(6).default(1),
    teamSize: z.string().max(64).optional(),
    description: z.string().max(2000).optional(),
});

export async function GET() {
    try {
        const { userId } = await auth();
        if (!userId) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const [user] = await db
            .select({ id: users.id, defaultCompanyId: users.companyId })
            .from(users)
            .where(eq(users.userId, userId));

        if (!user) {
            return NextResponse.json({ error: "User not found" }, { status: 404 });
        }

        const memberCountSubquery = db
            .select({
                companyId: userCompanyMemberships.companyId,
                memberCount: count(userCompanyMemberships.id).as("member_count"),
            })
            .from(userCompanyMemberships)
            .groupBy(userCompanyMemberships.companyId)
            .as("mc");

        const rows = await db
            .select({
                id: company.id,
                name: company.name,
                slug: company.slug,
                description: company.description,
                swatch: company.swatch,
                role: userCompanyMemberships.role,
                lastOpenedAt: userCompanyMemberships.lastOpenedAt,
                memberCount: memberCountSubquery.memberCount,
            })
            .from(userCompanyMemberships)
            .innerJoin(company, eq(company.id, userCompanyMemberships.companyId))
            .leftJoin(
                memberCountSubquery,
                eq(memberCountSubquery.companyId, userCompanyMemberships.companyId)
            )
            .where(eq(userCompanyMemberships.userId, BigInt(user.id)))
            .orderBy(desc(userCompanyMemberships.lastOpenedAt));

        const activeCompanyId = await getActiveCompanyId(userId);

        return NextResponse.json({
            activeCompanyId: activeCompanyId.toString(),
            workspaces: rows.map((r) => ({
                id: r.id,
                name: r.name,
                slug: r.slug,
                description: r.description,
                swatch: r.swatch ?? 1,
                role: r.role,
                memberCount: Number(r.memberCount ?? 1),
                lastOpenedAt: r.lastOpenedAt,
                isActive: BigInt(r.id) === activeCompanyId,
            })),
        });
    } catch (err) {
        console.error("[workspaces] GET error:", err);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

export async function POST(request: Request) {
    try {
        const { userId } = await auth();
        if (!userId) {
            return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
        }

        const json = await request.json().catch(() => ({}));
        const parsed = CreateWorkspaceSchema.safeParse(json);
        if (!parsed.success) {
            return NextResponse.json(
                { error: "Invalid input", issues: parsed.error.flatten() },
                { status: 400 }
            );
        }
        const { name, slug, swatch, teamSize, description } = parsed.data;

        const [existingSlug] = await db
            .select({ id: company.id })
            .from(company)
            .where(eq(company.slug, slug));
        if (existingSlug) {
            return NextResponse.json(
                { error: "Slug already taken" },
                { status: 409 }
            );
        }

        const [user] = await db
            .select({ id: users.id, name: users.name, email: users.email })
            .from(users)
            .where(eq(users.userId, userId));
        if (!user) {
            return NextResponse.json({ error: "User not found" }, { status: 404 });
        }

        const teamSizeForCompany = teamSize?.trim() || "1";

        const [newCompany] = await db
            .insert(company)
            .values({
                name,
                slug,
                swatch,
                description: description ?? null,
                numberOfEmployees: teamSizeForCompany,
            })
            .returning({ id: company.id });

        if (!newCompany) {
            return NextResponse.json(
                { error: "Could not create workspace" },
                { status: 500 }
            );
        }

        const newCompanyId = BigInt(newCompany.id);

        await db.insert(userCompanyMemberships).values({
            userId: BigInt(user.id),
            companyId: newCompanyId,
            role: "owner",
        });

        try {
            await initTokenAccount(newCompanyId, TOKEN_SIGNUP_BONUS);
        } catch (creditErr) {
            console.error("[workspaces] initTokenAccount failed:", creditErr);
            // Non-fatal: workspace exists, credits can be initialized later.
        }

        const response = NextResponse.json({
            success: true,
            workspace: {
                id: newCompany.id,
                name,
                slug,
                swatch,
                role: "owner",
            },
        });
        setActiveWorkspaceCookie(response, newCompanyId);
        return response;
    } catch (err) {
        console.error("[workspaces] POST error:", err);
        return NextResponse.json({ error: "Internal server error" }, { status: 500 });
    }
}

"use client";

import { useEffect, useState } from "react";
import { Coins } from "lucide-react";

function formatTokens(n: number): string {
    if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
    if (n >= 1_000) return `${(n / 1_000).toFixed(0)}K`;
    return n.toLocaleString();
}

export function TokenBalance() {
    const [balance, setBalance] = useState<number | null>(null);

    useEffect(() => {
        fetch("/api/credits")
            .then((r) => (r.ok ? r.json() : null))
            .then((data) => {
                if (data?.balanceTokens != null) setBalance(data.balanceTokens);
            })
            .catch(() => {});
    }, []);

    if (balance === null) return null;

    const isLow = balance < 500_000;

    return (
        <div
            className={`flex items-center gap-1.5 px-3 py-1.5 rounded-full text-xs font-medium border transition-colors ${
                isLow
                    ? "bg-red-50 dark:bg-red-950/40 border-red-200 dark:border-red-800/50 text-red-600 dark:text-red-400"
                    : "bg-purple-50 dark:bg-purple-950/40 border-purple-200 dark:border-purple-800/50 text-purple-600 dark:text-purple-400"
            }`}
            title={`${balance.toLocaleString()} tokens remaining`}
        >
            <Coins className="w-3.5 h-3.5" />
            {formatTokens(balance)}
        </div>
    );
}

