export function AddSourceModal({
  open,
  onClose,
  userId,
  defaultCategory,
  folders,
  onUploaded,
  onCreateFolder,
  initialTab,
}: AddSourceModalProps) {
  const [tab, setTab] = useState<string>(initialTab ?? "files");
  const [folder, setFolder] = useState<string>(defaultCategory || "Unfiled");

  useEffect(() => {
    if (!open) return;
    setFolder(defaultCategory || "Unfiled");
    setTab(initialTab ?? "files");
  }, [open, defaultCategory, initialTab]);

  useEffect(() => {
    if (!open) return;
    const onEsc = (e: KeyboardEvent) => {
      if (e.key === "Escape") onClose();
    };
    window.addEventListener("keydown", onEsc);
    return () => window.removeEventListener("keydown", onEsc);
  }, [open, onClose]);

  if (!open) return null;

  const allTabs: AddSourceTab[] = ADD_TABS.flatMap((g) => g.items);
  const active = allTabs.find((t) => t.id === tab) ?? allTabs[0]!;

  const handleUploaded = () => {
    onUploaded();
    onClose();
  };

  let panel: React.ReactNode = null;
  if (tab === "files") {
    panel = (
      <FilesPanel
        kind="files"
        userId={userId}
        category={folder}
        onUploaded={handleUploaded}
      />
    );
  } else if (tab === "folder") {
    panel = (
      <FolderPanel
        userId={userId}
        category={folder}
        onFolderRename={setFolder}
        onUploaded={handleUploaded}
      />
    );
  } else if (tab === "audio" || tab === "video") {
    panel = (
      <FilesPanel
        kind={tab}
        userId={userId}
        category={folder}
        onUploaded={handleUploaded}
      />
    );
  } else if (tab === "paste") {
    panel = <PastePanel userId={userId} category={folder} onUploaded={handleUploaded} />;
  } else if (tab === "url") {
    panel = <UrlPanel userId={userId} category={folder} onUploaded={handleUploaded} />;
  } else if (tab === "youtube") {
    panel = (
      <YouTubePanel userId={userId} category={folder} onUploaded={handleUploaded} />
    );
  } else {
    panel = <ConnectPanel tab={active} />;
  }

  return (
    <div
      onClick={onClose}
      style={{
        position: "fixed",
        inset: 0,
        zIndex: 100,
        background: "var(--scrim)",
        backdropFilter: "blur(6px)",
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: 24,
        animation: "lsw-fadeIn 160ms ease-out",
      }}
    >
      <div
        onClick={(e) => e.stopPropagation()}
        style={{
          width: 780,
          maxWidth: "92vw",
          maxHeight: "86vh",
          background: "var(--panel)",
          borderRadius: 16,
          boxShadow: "0 30px 80px var(--scrim-shadow), 0 0 0 1px var(--line)",
          display: "flex",
          overflow: "hidden",
          animation: "lsw-modalIn 180ms ease-out",
        }}
      >
        {/* Sidebar */}
        <div
          style={{
            width: 220,
            background: "var(--line-2)",
            borderRight: "1px solid var(--line)",
            padding: "18px 12px",
            display: "flex",
            flexDirection: "column",
            gap: 16,
            overflowY: "auto",
          }}
        >
          <div
            style={{
              padding: "0 8px",
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
            }}
          >
            <div style={{ fontSize: 15, fontWeight: 700 }}>Add a source</div>
          </div>
          {ADD_TABS.map((g) => (
            <div key={g.group}>
              <div
                className="mono"
                style={{
                  fontSize: 10,
                  fontWeight: 600,
                  letterSpacing: "0.08em",
                  color: "var(--ink-3)",
                  textTransform: "uppercase",
                  padding: "0 8px 6px",
                }}
              >
                {g.group}
              </div>
              <div style={{ display: "flex", flexDirection: "column", gap: 1 }}>
                {g.items.map((item) => {
                  const isActive = tab === item.id;
                  const Icon = item.Icon;
                  return (
                    <button
                      key={item.id}
                      onClick={() => setTab(item.id)}
                      style={{
                        display: "flex",
                        alignItems: "center",
                        gap: 10,
                        padding: "7px 8px",
                        borderRadius: 7,
                        textAlign: "left",
                        fontSize: 13,
                        fontWeight: isActive ? 600 : 500,
                        color: isActive ? "var(--accent-ink)" : "var(--ink-2)",
                        background: isActive ? "var(--accent-soft)" : "transparent",
                      }}
                    >
                      <Icon size={14} />
                      {item.label}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>
        {/* Panel */}
        <div
          style={{
            flex: 1,
            padding: "22px 26px",
            display: "flex",
            flexDirection: "column",
            overflow: "hidden",
          }}
        >
          <div
            style={{
              display: "flex",
              alignItems: "center",
              justifyContent: "space-between",
              marginBottom: 18,
            }}
          >
            <div>
              <div style={{ fontSize: 18, fontWeight: 700 }}>{active.label}</div>
              <div style={{ fontSize: 13, color: "var(--ink-3)", marginTop: 2 }}>
                {active.desc}
              </div>
            </div>
            <button
              onClick={onClose}
              style={{
                width: 32,
                height: 32,
                borderRadius: 8,
                color: "var(--ink-3)",
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
              }}
              title="Close"
            >
              <IconX size={16} />
            </button>
          </div>
          <div style={{ flex: 1, overflowY: "auto" }}>{panel}</div>

          {/* Save-to strip. Tags picker omitted for now — tags aren't yet
              persisted on ingest, and the design is purely informational. */}
          <div
            style={{
              marginTop: 14,
              paddingTop: 14,
              borderTop: "1px solid var(--line)",
              display: "flex",
              gap: 10,
              alignItems: "center",
              flexWrap: "wrap",
            }}
          >
            <div
              className="mono"
              style={{
                fontSize: 10,
                fontWeight: 600,
                letterSpacing: "0.08em",
                color: "var(--ink-3)",
                textTransform: "uppercase",
              }}
            >
              Save to
            </div>
            <FolderPicker
              value={folder}
              onChange={setFolder}
              folders={folders}
              onCreate={onCreateFolder}
            />
          </div>
        </div>
      </div>
    </div>
  );
}

