interface FolderPickerProps {
  value: string;
  onChange: (next: string) => void;
  folders: string[];
  onCreate?: (name: string) => void;
}

function FolderPicker({ value, onChange, folders, onCreate }: FolderPickerProps) {
  const [open, setOpen] = useState(false);
  const [q, setQ] = useState("");
  const ref = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const onClick = (e: globalThis.MouseEvent) => {
      if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false);
    };
    if (open) {
      document.addEventListener("mousedown", onClick);
      return () => document.removeEventListener("mousedown", onClick);
    }
  }, [open]);

  const filtered = folders.filter((f) => f.toLowerCase().includes(q.toLowerCase()));
  const canCreate =
    q.trim().length > 0 &&
    !folders.some((f) => f.toLowerCase() === q.trim().toLowerCase());

  return (
    <div ref={ref} style={{ position: "relative" }}>
      <button
        onClick={() => setOpen((v) => !v)}
        style={{
          fontSize: 12,
          padding: "5px 9px",
          borderRadius: 6,
          color: "var(--ink-2)",
          border: "1px solid var(--line)",
          background: "var(--line-2)",
          display: "flex",
          alignItems: "center",
          gap: 5,
        }}
      >
        <IconFolder size={11} />
        {value}
        <IconChevronDown size={10} />
      </button>
      {open && (
        <div
          style={{
            position: "absolute",
            bottom: "calc(100% + 6px)",
            left: 0,
            width: 220,
            background: "var(--panel)",
            border: "1px solid var(--line)",
            borderRadius: 10,
            boxShadow: "0 -10px 30px var(--scrim-shadow)",
            zIndex: 10,
            overflow: "hidden",
          }}
        >
          <input
            value={q}
            onChange={(e) => setQ(e.target.value)}
            autoFocus
            placeholder="Find or create folder…"
            style={{
              width: "100%",
              padding: "9px 12px",
              border: "none",
              outline: "none",
              background: "transparent",
              fontSize: 12,
              borderBottom: "1px solid var(--line)",
              color: "var(--ink)",
            }}
          />
          <div style={{ maxHeight: 200, overflowY: "auto", padding: "4px 0" }}>
            {filtered.map((f) => (
              <button
                key={f}
                onClick={() => {
                  onChange(f);
                  setOpen(false);
                }}
                style={{
                  width: "100%",
                  textAlign: "left",
                  padding: "6px 12px",
                  fontSize: 12,
                  color: "var(--ink)",
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                }}
                onMouseEnter={(e) => (e.currentTarget.style.background = "var(--line-2)")}
                onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
              >
                <IconFolder size={12} /> {f}
                {value === f && (
                  <span style={{ marginLeft: "auto", color: "var(--accent)" }}>
                    <IconCheck size={12} />
                  </span>
                )}
              </button>
            ))}
            {canCreate && (
              <button
                onClick={() => {
                  onCreate?.(q.trim());
                  onChange(q.trim());
                  setOpen(false);
                  setQ("");
                }}
                style={{
                  width: "100%",
                  textAlign: "left",
                  padding: "6px 12px",
                  fontSize: 12,
                  color: "var(--accent)",
                  fontWeight: 600,
                  display: "flex",
                  alignItems: "center",
                  gap: 8,
                  borderTop: filtered.length > 0 ? "1px solid var(--line)" : "none",
                }}
              >
                <IconPlus size={12} /> Create folder &quot;{q.trim()}&quot;
              </button>
            )}
          </div>
        </div>
      )}
    </div>
  );
}

