            })}
            {viewingOld && currentVersion && (
              <div
                style={{
                  marginTop: 10,
                  padding: "10px 12px",
                  background: "var(--line-2)",
                  borderRadius: 8,
                  border: "1px dashed var(--line)",
                }}
