"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import type { DocumentType } from "../types/document";
import { getDocumentDisplayType } from "../types/document";
import type { SourceTypeId, WorkspaceFolder, WorkspaceSource } from "./types";

/** Stable color picker — hashes a category name into the existing design palette. */
const FOLDER_PALETTE = [
  "oklch(0.6 0.17 285)",
  "oklch(0.6 0.14 30)",
  "oklch(0.55 0.14 225)",
  "oklch(0.6 0.15 160)",
  "oklch(0.55 0.14 330)",
  "oklch(0.5 0.02 280)",
];

function hashName(name: string): number {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = (h * 31 + name.charCodeAt(i)) | 0;
  return Math.abs(h);
}

function folderColor(name: string): string {
  const palette = FOLDER_PALETTE;
  return palette[hashName(name) % palette.length]!;
}

function mapDocType(doc: DocumentType): SourceTypeId {
  const t = getDocumentDisplayType(doc);
  if (t === "audio") return "audio";
  return "doc";
}

function humanDate(raw: unknown): string {
  if (!raw) return "";
  const d = new Date(String(raw));
  if (Number.isNaN(d.getTime())) return "";
  const diffMs = Date.now() - d.getTime();
  const diffHr = Math.floor(diffMs / 3_600_000);
  if (diffHr < 1) return "just now";
  if (diffHr < 24) return `${diffHr}h ago`;
  const diffDay = Math.floor(diffHr / 24);
  if (diffDay === 1) return "Yesterday";
  if (diffDay < 7) return `${diffDay} days ago`;
  const diffWk = Math.floor(diffDay / 7);
  if (diffWk === 1) return "Last week";
  if (diffWk < 5) return `${diffWk} weeks ago`;
  return d.toLocaleDateString();
}

function mapDocument(doc: DocumentType & { createdAt?: string }): WorkspaceSource {
  return {
    id: `d${doc.id}`,
    documentId: doc.id,
    title: doc.title,
    type: mapDocType(doc),
    size: doc.aiSummary ? "" : "",
    added: humanDate(doc.createdAt) || "",
    folder: doc.category ?? "Unfiled",
    tags: [],
    domain: "General",
  };
}

export interface UseWorkspaceDataResult {
  sources: WorkspaceSource[];
  folders: WorkspaceFolder[];
  loading: boolean;
  error: string | null;
  companyId: number | null;
  /** DB role of the current user (`employer`, `owner`, `employee`, or null while loading). */
  role: string | null;
  refresh: () => Promise<void>;
  /** Optimistically insert a row before the backend confirms it. */
  addOptimistic: (source: WorkspaceSource) => void;
}

interface CategoryRow {
  id: number;
  name: string;
  companyId: number;
}

export function useWorkspaceData(userId: string | null | undefined): UseWorkspaceDataResult {
  const [documents, setDocuments] = useState<(DocumentType & { createdAt?: string })[]>([]);
  const [categories, setCategories] = useState<CategoryRow[]>([]);
  const [optimistic, setOptimistic] = useState<WorkspaceSource[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [companyId, setCompanyId] = useState<number | null>(null);
  const [role, setRole] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    if (!userId) return;
    setError(null);
    try {
      const [docsRes, catsRes] = await Promise.all([
        fetch("/api/fetchDocument", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ userId }),
        }),
        fetch("/api/Categories/GetCategories"),
      ]);
      if (!docsRes.ok) throw new Error(`Failed to fetch documents (${docsRes.status})`);
      const docs = (await docsRes.json()) as (DocumentType & { createdAt?: string })[];
      setDocuments(docs);

      if (catsRes.ok) {
        const cats = (await catsRes.json()) as CategoryRow[];
        setCategories(cats);
      }

      // Prune optimistic rows that now exist in the server response (by title).
      setOptimistic((prev) =>
        prev.filter((o) => !docs.some((d) => d.title === o.title)),
      );
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to fetch documents");
    } finally {
      setLoading(false);
    }
  }, [userId]);

  // Fetch company context so AskPanel can scope queries correctly.
  const resolveCompany = useCallback(async () => {
    if (!userId) return;
    try {
      const response = await fetch("/api/fetchUserInfo", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ userId }),
      });
      if (!response.ok) return;
      const data = (await response.json()) as {
        companyId?: number | string;
        role?: string;
      };
      if (data?.companyId != null) setCompanyId(Number(data.companyId));
      if (typeof data?.role === "string") setRole(data.role);
    } catch {
      // non-fatal — AskPanel falls back to document-scoped queries
    }
  }, [userId]);

  useEffect(() => {
    if (!userId) return;
    void refresh();
    void resolveCompany();
  }, [userId, refresh, resolveCompany]);

  const sources = useMemo<WorkspaceSource[]>(
    () => [...optimistic, ...documents.map(mapDocument)],
    [documents, optimistic],
  );

  const folders = useMemo<WorkspaceFolder[]>(() => {
    const seen = new Map<string, WorkspaceFolder>();
    // Seed with every category so empty folders render in the rail.
    for (const c of categories) {
      seen.set(c.name, { id: `cat-${c.id}`, name: c.name, color: folderColor(c.name) });
    }
    for (const src of sources) {
      const name = src.folder || "Unfiled";
      if (!seen.has(name)) {
        seen.set(name, { id: `f-${name}`, name, color: folderColor(name) });
      }
    }
    return [...seen.values()];
  }, [sources, categories]);

  const addOptimistic = useCallback((source: WorkspaceSource) => {
    setOptimistic((prev) => [source, ...prev]);
  }, []);

  return {
    sources,
    folders,
    loading,
    error,
    companyId,
    role,
    refresh,
    addOptimistic,
  };
}

"use client";

import React, { useRef, useState, useEffect, useCallback } from "react";
import { Music, FileText, Clock, Loader2 } from "lucide-react";
import type { DocumentType } from "../types";

interface AudioViewerProps {
  document: DocumentType;
}

interface TranscriptSegment {
  start: number;
  end: number;
  text: string;
}

function formatTime(seconds: number): string {
  const m = Math.floor(seconds / 60);
  const s = Math.floor(seconds % 60);
  return `${m}:${s.toString().padStart(2, "0")}`;
}

export function AudioViewer({ document }: AudioViewerProps) {
  const audioRef = useRef<HTMLAudioElement>(null);
  const activeIndexRef = useRef(-1);
  const [transcript, setTranscript] = useState<string | null>(null);
  const [segments, setSegments] = useState<TranscriptSegment[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeSegmentIndex, setActiveSegmentIndex] = useState(-1);
  const [audioBlobUrl, setAudioBlobUrl] = useState<string | null>(null);

  const isTranscription = document.title.toLowerCase().includes("(transcription)");
  const metadata = document.ocrMetadata;
  const audioDocId = metadata?.audioDocumentId;
  const audioProxyUrl = audioDocId ? `/api/documents/${audioDocId}/content` : null;

  // Download audio as blob so seeking works without Range header support
  useEffect(() => {
    const url = isTranscription ? audioProxyUrl : document.url;
    if (!url) return;

    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch(url);
        if (res.ok && !cancelled) {
          const blob = await res.blob();
          const blobUrl = URL.createObjectURL(blob);
          setAudioBlobUrl(blobUrl);
        }
      } catch {
        // ignore
      }
    })();

    return () => {
      cancelled = true;
      setAudioBlobUrl((prev) => {
        if (prev) URL.revokeObjectURL(prev);
        return null;
      });
    };
  }, [audioProxyUrl, document.url, isTranscription]);

  // Load segments from metadata, fetch transcript text
  useEffect(() => {
    if (!isTranscription) {
      setLoading(false);
      return;
    }

    if (metadata?.segments && Array.isArray(metadata.segments)) {
      setSegments(metadata.segments as TranscriptSegment[]);
    }

    let cancelled = false;
    void (async () => {
      try {
        const res = await fetch(`/api/documents/${document.id}/content`);
        if (res.ok && !cancelled) {
          const text = await res.text();
          setTranscript(text);
        }
      } catch {
        // ignore
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, [document.id, isTranscription, metadata]);

  // Track current time for segment highlighting
  useEffect(() => {
    const audio = audioRef.current;
    if (!audio || segments.length === 0) return;

    const handleTimeUpdate = () => {
      const t = audio.currentTime;
      const idx = segments.findIndex((s) => t >= s.start && t < s.end);
      if (idx !== activeIndexRef.current) {
        activeIndexRef.current = idx;
        setActiveSegmentIndex(idx);
      }
    };

    audio.addEventListener("timeupdate", handleTimeUpdate);
    return () => audio.removeEventListener("timeupdate", handleTimeUpdate);
  }, [segments, audioBlobUrl]);

  const seekTo = useCallback((time: number) => {
    const audio = audioRef.current;
    if (!audio) return;
    audio.currentTime = time;
    void audio.play().catch(() => {});
  }, []);

  // For a raw audio file (not a transcription), just show the player
  if (!isTranscription) {
    return (
      <div className="flex flex-col items-center justify-center h-full gap-6 p-8">
        <div className="w-20 h-20 bg-violet-100 dark:bg-violet-900/30 rounded-3xl flex items-center justify-center">
          <Music className="w-10 h-10 text-violet-600 dark:text-violet-400" />
        </div>
        <h3 className="text-lg font-semibold text-foreground">{document.title}</h3>
        {audioBlobUrl ? (
          <audio ref={audioRef} controls className="w-full max-w-lg" src={audioBlobUrl} />
        ) : (
          <div className="flex items-center gap-2 text-sm text-muted-foreground">
            <Loader2 className="w-4 h-4 animate-spin" /> Loading audio...
          </div>
        )}
        <p className="text-sm text-muted-foreground">
          Check the matching transcript document to view the transcribed text.
        </p>
      </div>
    );
  }

  // Transcription document view
  return (
    <div className="flex flex-col h-full overflow-hidden">
      {/* Audio player bar */}
      {audioProxyUrl && (
        <div className="flex-shrink-0 bg-violet-50 dark:bg-violet-950/30 border-b border-violet-200 dark:border-violet-800 px-6 py-4">
          <div className="flex items-center gap-3 mb-2">
            <Music className="w-4 h-4 text-violet-600 dark:text-violet-400" />
            <span className="text-sm font-medium text-violet-700 dark:text-violet-300">Audio Player</span>
          </div>
          {audioBlobUrl ? (
            <audio ref={audioRef} controls className="w-full" src={audioBlobUrl} />
          ) : (
            <div className="flex items-center gap-2 text-sm text-muted-foreground py-2">
              <Loader2 className="w-4 h-4 animate-spin" /> Loading audio...
            </div>
          )}
        </div>
      )}

      {/* Transcript content */}
      <div className="flex-1 overflow-y-auto p-6">
        <div className="flex items-center gap-2 mb-4">
          <FileText className="w-4 h-4 text-violet-600 dark:text-violet-400" />
          <h3 className="text-sm font-semibold text-foreground">Transcript</h3>
          {metadata?.language && (
            <span className="px-2 py-0.5 bg-violet-100 dark:bg-violet-900/30 text-violet-700 dark:text-violet-300 text-[10px] rounded font-medium uppercase">
              {metadata.language}
            </span>
          )}
        </div>

        {loading ? (
          <div className="flex items-center justify-center py-12">
            <Loader2 className="w-6 h-6 text-violet-500 animate-spin" />
          </div>
        ) : segments.length > 0 ? (
          <div className="space-y-1">
            {segments.map((segment, i) => (
              <div
                key={i}
                role="button"
                tabIndex={0}
                onMouseDown={(e) => {
                  e.preventDefault();
                  seekTo(segment.start);
                }}
                className={`w-full text-left px-3 py-2 rounded-lg transition-colors cursor-pointer group hover:bg-violet-50 dark:hover:bg-violet-950/30 ${
                  i === activeSegmentIndex
                    ? "bg-violet-100 dark:bg-violet-900/40 border-l-2 border-violet-500"
                    : ""
                }`}
              >
                <div className="flex items-start gap-3">
                  <span className="flex-shrink-0 flex items-center gap-1 text-[11px] font-mono text-violet-500 dark:text-violet-400 pt-0.5 opacity-60 group-hover:opacity-100">
                    <Clock className="w-3 h-3" />
                    {formatTime(segment.start)}
                  </span>
                  <span className="text-sm text-foreground leading-relaxed">
                    {segment.text}
                  </span>
                </div>
              </div>
            ))}
          </div>
        ) : transcript ? (
          <div className="prose dark:prose-invert prose-sm max-w-none">
            <p className="whitespace-pre-wrap leading-relaxed text-foreground/90">
              {transcript}
            </p>
          </div>
        ) : (
          <p className="text-sm text-muted-foreground">No transcript available.</p>
        )}
      </div>
    </div>
  );
}

