                                className={`${styles.btn} ${styles.btnAccent}`}
                                onClick={createWorkspace}
                                disabled={
                                    submitting ||
                                    !name.trim() ||
                                    !slugValue.trim() ||
                                    slugAvailable === false
                                }
                            >
                                {submitting ? "Creating…" : "Create & continue"}
                                <svg
                                    width="13"
                                    height="13"
                                    viewBox="0 0 24 24"
                                    fill="none"
                                    stroke="currentColor"
                                    strokeWidth="2.5"
                                    strokeLinecap="round"
                                    strokeLinejoin="round"
                                >
                                    <line x1="5" y1="12" x2="19" y2="12" />
                                    <polyline points="12 5 19 12 12 19" />
                                </svg>
                            </button>
                        </div>
                    </div>
                ) : null}

                {error ? (
                    <div className={styles.error} role="alert">
                        {error}
                    </div>
                ) : null}

                <p className={styles.foot}>
                    Looking for a workspace that&apos;s not here? Ask its owner to
                    invite{" "}
                    <b style={{ color: "var(--ink-2)", fontWeight: 500 }}>
                        {account.email || "you"}
                    </b>
                    .
                    <br />
                    <a href="/signin">Use a different account</a>
                    <span className={styles.sepDot}>·</span>
                    <a href="/contact">Help</a>
                    <span className={styles.sepDot}>·</span>
                    <a href="/privacy">Privacy</a>
                </p>
            </div>
        </div>
    );
}

import { redirect } from "next/navigation";
import { auth, currentUser } from "@clerk/nextjs/server";
import { eq, desc, count } from "drizzle-orm";

import { db } from "~/server/db";
import {
    users,
    company,
    userCompanyMemberships,
} from "@launchstack/core/db/schema";
import { getActiveCompanyId } from "~/lib/active-workspace";

import { WorkspaceSelectClient } from "./WorkspaceSelectClient";

export const dynamic = "force-dynamic";

export default async function WorkspacesPage({
    searchParams,
}: {
    searchParams: Promise<{ from?: string }>;
}) {
    const { userId } = await auth();
    if (!userId) redirect("/signin");

    const [user] = await db
        .select({ id: users.id })
        .from(users)
        .where(eq(users.userId, userId));
    if (!user) redirect("/signup");

    const memberCountSubquery = db
        .select({
            companyId: userCompanyMemberships.companyId,
            memberCount: count(userCompanyMemberships.id).as("member_count"),
        })
        .from(userCompanyMemberships)
        .groupBy(userCompanyMemberships.companyId)
        .as("mc");

    const rows = await db
        .select({
            id: company.id,
            name: company.name,
            slug: company.slug,
            description: company.description,
            swatch: company.swatch,
            role: userCompanyMemberships.role,
            lastOpenedAt: userCompanyMemberships.lastOpenedAt,
            memberCount: memberCountSubquery.memberCount,
        })
        .from(userCompanyMemberships)
        .innerJoin(company, eq(company.id, userCompanyMemberships.companyId))
        .leftJoin(
            memberCountSubquery,
            eq(memberCountSubquery.companyId, userCompanyMemberships.companyId)
        )
        .where(eq(userCompanyMemberships.userId, BigInt(user.id)))
        .orderBy(desc(userCompanyMemberships.lastOpenedAt));

    const activeCompanyId = await getActiveCompanyId(userId);
    const clerkUser = await currentUser();
    const params = await searchParams;
    const fromSignup = params.from === "signup";

    const workspaces = rows.map((r) => ({
        id: r.id.toString(),
        name: r.name,
        slug: r.slug ?? "",
        description: r.description ?? null,
        swatch: r.swatch ?? 1,
        role: r.role,
        memberCount: Number(r.memberCount ?? 1),
        lastOpenedAt: r.lastOpenedAt.toISOString(),
        isActive: BigInt(r.id) === activeCompanyId,
    }));

    const accountName =
        clerkUser?.fullName ||
        [clerkUser?.firstName, clerkUser?.lastName].filter(Boolean).join(" ") ||
        clerkUser?.username ||
        "You";
    const accountEmail =
        clerkUser?.primaryEmailAddress?.emailAddress ?? "";

    return (
        <WorkspaceSelectClient
            workspaces={workspaces}
            account={{ name: accountName, email: accountEmail }}
            fromSignup={fromSignup}
        />
    );
}

"use client";

import { useEffect, useState } from "react";
import { Link2 } from "lucide-react";

interface BacklinkRow {
  sourceNoteId: number;
  title: string | null;
  snippet: string;
  linkedAs: string;
  sourceDocumentId?: string | null;
}

interface BacklinksPanelProps {
  /** Either a note id (loads `/api/notes/:id/backlinks`) or a document id
   *  (loads `/api/documents/:id/backlinks`). Provide one — not both. */
  noteId?: number;
  documentId?: string;
  /** Called when the user clicks an incoming row. */
  onOpenNote?: (noteId: number) => void;
}

/**
 * Compact incoming-references list. Shown alongside a note or document so
 * users can see what else in their notebook references this thing.
 */
export function BacklinksPanel({
  noteId,
  documentId,
  onOpenNote,
}: BacklinksPanelProps) {
  const [rows, setRows] = useState<BacklinkRow[] | null>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    const url = noteId
      ? `/api/notes/${noteId}/backlinks`
      : documentId
      ? `/api/documents/${encodeURIComponent(documentId)}/backlinks`
      : null;
    if (!url) {
      setRows([]);
      return;
    }

    setRows(null);
    setError(null);
    void fetch(url)
      .then(async (res) => {
        if (!res.ok) throw new Error(`Failed (${res.status})`);
        const data = (await res.json()) as { incoming: BacklinkRow[] };
        if (!cancelled) setRows(data.incoming ?? []);
      })
      .catch((err) => {
        if (!cancelled) setError(err instanceof Error ? err.message : "Failed");
      });
    return () => {
      cancelled = true;
    };
  }, [noteId, documentId]);

  if (rows === null && !error) {
    return (
      <div
        style={{
          padding: "10px 12px",
          fontSize: 11,
          color: "var(--ink-3)",
        }}
      >
        Loading backlinks…
      </div>
    );
  }

  if (error) {
    return (
      <div
        style={{
          padding: "10px 12px",
          fontSize: 11,
          color: "oklch(0.45 0.18 30)",
        }}
      >
        Backlinks: {error}
      </div>
    );
  }

  if (!rows || rows.length === 0) {
    return null;
  }

  return (
    <div
      style={{
        margin: "10px 6px 0",
        padding: "8px 10px",
        borderRadius: 8,
        border: "1px dashed var(--line-2)",
        background: "var(--panel-2)",
      }}
    >
      <div
        className="mono"
        style={{
          display: "flex",
          alignItems: "center",
          gap: 4,
          fontSize: 10,
          fontWeight: 600,
          letterSpacing: "0.08em",
          color: "var(--ink-3)",
          textTransform: "uppercase",
          marginBottom: 6,
        }}
      >
        <Link2 size={11} /> Backlinks · {rows.length}
      </div>
      <div style={{ display: "flex", flexDirection: "column", gap: 4 }}>
        {rows.map((r) => (
          <button
            key={r.sourceNoteId}
            type="button"
            onClick={() => onOpenNote?.(r.sourceNoteId)}
            style={{
              textAlign: "left",
              padding: "6px 8px",
              borderRadius: 6,
              border: "1px solid var(--line-2)",
              background: "var(--panel)",
              color: "var(--ink)",
              cursor: onOpenNote ? "pointer" : "default",
              fontSize: 11,
              lineHeight: 1.4,
            }}
          >
            <div style={{ fontWeight: 600 }}>
              {r.title || "Untitled note"}
            </div>
            {r.snippet && (
              <div
                style={{
                  fontSize: 10,
                  color: "var(--ink-2)",
                  marginTop: 2,
                  whiteSpace: "pre-wrap",
                  wordBreak: "break-word",
                }}
              >
                {r.snippet}
              </div>
            )}
            <div
              style={{
                marginTop: 4,
                fontSize: 9,
                color: "var(--ink-3)",
                fontStyle: "italic",
              }}
            >
              linked as [[{r.linkedAs}]]
            </div>
          </button>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import type { JSONContent } from "@tiptap/react";
import { FileText, Plus, Search, Sparkles } from "lucide-react";
import type { DocumentNote } from "@launchstack/core/db/schema/document-notes";
import {
  type DraftState,
  EMPTY_DRAFT,
  type NoteAnchorLite,
  primaryPageOfAnchor,
} from "./_shared/anchor";
import { NoteCard } from "./_shared/NoteCard";
import { NoteDraftEditor } from "./_shared/NoteDraftEditor";
import { BacklinksPanel } from "./BacklinksPanel";

/**
 * Freeform / cross-document notes surface for the Studio drawer. Unlike
 * `DocumentNotesPanel`, notes here have no `documentId` and no anchor —
 * they are scratchpad / second-brain entries scoped to the current user.
 *
 * Reuses `NoteCard` and `NoteDraftEditor` from `_shared/`. The draft editor
 * runs with `supportsAnchor={false}` so the anchor `<details>` block is
 * hidden — anchored notes belong to `DocumentNotesPanel`.
 */
export function NotebookPane() {
  const [notes, setNotes] = useState<DocumentNote[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [draft, setDraft] = useState<DraftState>(EMPTY_DRAFT);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [query, setQuery] = useState("");
  const [semantic, setSemantic] = useState(false);
  const [semanticIds, setSemanticIds] = useState<number[] | null>(null);
  const [semanticBusy, setSemanticBusy] = useState(false);

  const fetchNotes = useCallback(async () => {
    try {
      const res = await fetch("/api/notes?surface=notebook");
      if (!res.ok) throw new Error(`Failed (${res.status})`);
      const data = (await res.json()) as { notes: DocumentNote[] };
      setNotes(data.notes ?? []);
    } catch (err) {
      setError(err instanceof Error ? err.message : "Failed to fetch notes");
    } finally {
      setIsLoading(false);
    }
  }, []);

  useEffect(() => {
    setIsLoading(true);
    void fetchNotes();
  }, [fetchNotes]);

  const filtered = useMemo(() => {
    if (semantic && semanticIds) {
      const byId = new Map(notes.map((n) => [n.id, n]));
      return semanticIds
        .map((id) => byId.get(id))
        .filter((n): n is (typeof notes)[number] => n !== undefined);
    }
    const q = query.trim().toLowerCase();
    if (!q) return notes;
    return notes.filter((n) => {
      const title = (n.title ?? "").toLowerCase();
      const body = (n.contentMarkdown ?? n.content ?? "").toLowerCase();
      const tags = ((n.tags) ?? []).join(" ").toLowerCase();
      return title.includes(q) || body.includes(q) || tags.includes(q);
    });
  }, [notes, query, semantic, semanticIds]);

  // Run vector search when semantic mode is on and the query stabilizes.
  useEffect(() => {
    if (!semantic) {
      setSemanticIds(null);
      return;
    }
    const q = query.trim();
    if (!q) {
      setSemanticIds(null);
      return;
    }
    let cancelled = false;
    setSemanticBusy(true);
    const handle = setTimeout(async () => {
      try {
        const res = await fetch("/api/notes/search", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ query: q, scope: "user", topK: 25 }),
        });
        if (!res.ok) throw new Error(`Search failed (${res.status})`);
        const data = (await res.json()) as {
          hits: Array<{ noteId: number }>;
        };
        if (!cancelled) {
          setSemanticIds(data.hits.map((h) => h.noteId));
        }
      } catch (err) {
        if (!cancelled) {
          setError(err instanceof Error ? err.message : "Search failed");
          setSemanticIds([]);
        }
      } finally {
        if (!cancelled) setSemanticBusy(false);
      }
    }, 250);
    return () => {
      cancelled = true;
      clearTimeout(handle);
    };
  }, [semantic, query]);

  const startNewDraft = () => {
    setDraft({ ...EMPTY_DRAFT, id: "new" });
    setError(null);
  };

  const startEditDraft = (note: DocumentNote) => {
    setDraft({
      id: note.id,
      title: note.title ?? "",
      rich: (note.contentRich as JSONContent | null) ?? null,
      text: note.contentMarkdown ?? note.content ?? "",
      tags: (note.tags) ?? [],
      anchorQuote: "",
      anchorPage: "",
      anchorQuads: [],
    });
    setError(null);
  };

  const cancelDraft = () => {
    setDraft(EMPTY_DRAFT);
    setError(null);
  };

  const saveDraft = async () => {
    if (!draft.id) return;
    if (!draft.title.trim() && !draft.text.trim() && !draft.rich) {
      setError("Add a title or body first.");
      return;
    }
    setSaving(true);
    setError(null);
    try {
      const payload: Record<string, unknown> = {
        title: draft.title.trim() || undefined,
        contentRich: draft.rich ?? undefined,
        contentMarkdown: draft.text || undefined,
        tags: draft.tags,
      };

      const url = draft.id === "new" ? "/api/notes" : `/api/notes/${draft.id}`;
      const method = draft.id === "new" ? "POST" : "PUT";
      const res = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload),
      });
      if (!res.ok) {
        const body = (await res.json().catch(() => ({}))) as { error?: string };
        throw new Error(body.error ?? `Failed (${res.status})`);
      }

      cancelDraft();
      await fetchNotes();
    } catch (err) {
      setError(err instanceof Error ? err.message : "Save failed");
    } finally {
      setSaving(false);
    }
  };

  const deleteNote = async (id: number) => {
    if (!confirm("Delete this note? This cannot be undone.")) return;
    try {
      const res = await fetch(`/api/notes/${id}`, { method: "DELETE" });
      if (!res.ok) throw new Error(`Failed (${res.status})`);
      setNotes((prev) => prev.filter((n) => n.id !== id));
    } catch (err) {
      setError(err instanceof Error ? err.message : "Delete failed");
    }
  };

  const editingExisting = draft.id !== null && draft.id !== "new";

  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        height: "100%",
        overflow: "hidden",
      }}
    >
      <div
        style={{
          padding: "14px 16px 10px",
          borderBottom: "1px solid var(--line-2)",
          display: "flex",
          flexDirection: "column",
          gap: 8,
        }}
      >
        <div
          style={{
            display: "flex",
            alignItems: "center",
            justifyContent: "space-between",
          }}
        >
          <div
            className="mono"
            style={{
              fontSize: 10,
              fontWeight: 600,
              letterSpacing: "0.08em",
              color: "var(--ink-3)",
              textTransform: "uppercase",
            }}
          >
            Notebook
          </div>
          <span
            className="mono"
            style={{
              fontSize: 10,
              padding: "1px 6px",
              borderRadius: 4,
              background: "var(--panel-2)",
              color: "var(--ink-3)",
            }}
          >
            {notes.length}
          </span>
        </div>
        <div style={{ fontSize: 11, color: "var(--ink-3)" }}>
          Cross-document scratchpad. Notes here aren&apos;t tied to a source.
        </div>
        <div
          style={{
            display: "flex",
            alignItems: "center",
            gap: 6,
            padding: "5px 6px 5px 8px",
            borderRadius: 7,
            border: "1px solid var(--line)",
            background: "var(--panel)",
          }}
        >
          <Search size={12} style={{ color: "var(--ink-3)" }} />
          <input
            placeholder={semantic ? "Search by meaning…" : "Filter notes…"}
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            style={{
              flex: 1,
              padding: 0,
              border: "none",
              background: "transparent",
              color: "var(--ink)",
              fontSize: 12,
              outline: "none",
            }}
          />
          <button
            type="button"
            onClick={() => setSemantic((s) => !s)}
            title={
              semantic
                ? "Switch to title/body filter"
                : "Switch to semantic search"
            }
            style={{
              display: "inline-flex",
              alignItems: "center",
              gap: 3,
              padding: "2px 6px",
              borderRadius: 5,
              fontSize: 10,
              fontWeight: 600,
              border: "1px solid var(--line)",
              background: semantic ? "var(--accent)" : "var(--panel-2)",
              color: semantic ? "white" : "var(--ink-3)",
              cursor: "pointer",
            }}
          >
            <Sparkles size={10} />
            {semanticBusy ? "…" : "Semantic"}
          </button>
        </div>
        <button
          type="button"
          onClick={startNewDraft}
          disabled={draft.id !== null}
          style={{
            padding: "7px 10px",
            borderRadius: 7,
            background: draft.id !== null ? "var(--line)" : "var(--accent)",
            color: draft.id !== null ? "var(--ink-3)" : "white",
            fontSize: 12,
            fontWeight: 600,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 6,
            cursor: draft.id !== null ? "not-allowed" : "pointer",
            border: "none",
          }}
        >
          <Plus size={13} /> New note
        </button>
      </div>

      <div
        style={{
          flex: 1,
          overflowY: "auto",
          padding: "10px 10px 16px",
        }}
      >
        {error && draft.id === null && (
          <div
            style={{
              margin: "0 6px 10px",
              padding: "8px 10px",
              borderRadius: 7,
              background: "oklch(0.96 0.04 30)",
              border: "1px solid oklch(0.86 0.11 30)",
              color: "oklch(0.4 0.14 30)",
              fontSize: 11,
              lineHeight: 1.4,
            }}
          >
            {error}
          </div>
        )}

        {draft.id !== null && (
          <>
            <NoteDraftEditor
              draft={draft}
              setDraft={setDraft}
              saving={saving}
              error={error}
              onSave={() => void saveDraft()}
              onCancel={cancelDraft}
              supportsAnchor={false}
              editingExisting={editingExisting}
            />
            {typeof draft.id === "number" && (
              <BacklinksPanel
                noteId={draft.id}
                onOpenNote={(id) => {
                  const n = notes.find((x) => x.id === id);
                  if (n) startEditDraft(n);
                }}
              />
            )}
          </>
        )}

        {isLoading ? (
          <div
            style={{
              padding: "14px 16px",
              color: "var(--ink-3)",
              fontSize: 11,
            }}
          >
            Loading notes…
          </div>
        ) : filtered.length === 0 && draft.id === null ? (
          <div
            style={{
              padding: "32px 16px",
              textAlign: "center",
              color: "var(--ink-3)",
              fontSize: 12,
            }}
          >
            <FileText
              size={28}
              style={{ margin: "0 auto 8px", opacity: 0.3 }}
            />
            <div>
              {query ? "No matches." : "Your notebook is empty."}
            </div>
            <div style={{ fontSize: 11, opacity: 0.7, marginTop: 4 }}>
              {query
                ? "Try a different search."
                : 'Click "New note" to capture an idea.'}
            </div>
          </div>
        ) : (
          <div
            style={{ display: "flex", flexDirection: "column", gap: 6 }}
          >
            {filtered.map((n) => (
              <NoteCard
                key={n.id}
                note={n}
                editing={draft.id === n.id}
                onEdit={() => startEditDraft(n)}
                onDelete={() => void deleteNote(n.id)}
                onClick={() => {
                  // No-op: notebook notes have no source to scroll to.
                  startEditDraft(n);
                }}
              />
            ))}
          </div>
        )}
      </div>
    </div>
  );
}

﻿import { asc, eq } from "drizzle-orm";
import { db } from "~/server/db";
import { documentRetrievalChunks } from "@launchstack/core/db/schema";
import { ExperimentalEmbeddingClient } from "./client";
import { type ExperimentalEmbeddingConfig, type ExperimentalEmbeddingMetadata } from "./types";
import { storeExperimentalEmbeddings } from "./store";

const DEFAULT_ENDPOINT = process.env.EXPERIMENTAL_EMBEDDING_ENDPOINT ||
  (process.env.SIDECAR_URL ? `${process.env.SIDECAR_URL}/embed` : "");
const DEFAULT_PROVIDER = process.env.EXPERIMENTAL_EMBEDDING_PROVIDER || "sidecar";
const DEFAULT_MODEL = process.env.EXPERIMENTAL_EMBEDDING_MODEL || "bge-large-en-v1.5";
const DEFAULT_VERSION = process.env.EXPERIMENTAL_EMBEDDING_VERSION || "exp-v1";
const DEFAULT_DIMENSION = Number(process.env.EXPERIMENTAL_EMBEDDING_DIMENSION || "1024");

export interface ExperimentalPipelineOptions {
  documentId: number;
  endpoint?: string;
  provider?: string;
  model?: string;
  version?: string;
  dimension?: number;
  apiKey?: string;
  batchSize?: number;
}

export function resolveExperimentalConfig(overrides?: Partial<ExperimentalEmbeddingConfig>): ExperimentalEmbeddingConfig {
  const endpoint = overrides?.endpoint ?? DEFAULT_ENDPOINT;
  return {
    endpoint,
    provider: overrides?.provider ?? DEFAULT_PROVIDER,
    model: overrides?.model ?? DEFAULT_MODEL,
    version: overrides?.version ?? DEFAULT_VERSION,
    dimension: overrides?.dimension ?? DEFAULT_DIMENSION,
    apiKey: overrides?.apiKey,
    batchSize: overrides?.batchSize,
  };
}

export async function experimentalEmbedDocument(options: ExperimentalPipelineOptions): Promise<ExperimentalEmbeddingMetadata & { embeddedChunkCount: number }> {
  const { documentId, ...overrides } = options;
  const config = resolveExperimentalConfig(overrides);
  const client = new ExperimentalEmbeddingClient(config);

  const rows = await db
    .select({
      id: documentRetrievalChunks.id,
      content: documentRetrievalChunks.content,
    })
    .from(documentRetrievalChunks)
    .where(eq(documentRetrievalChunks.documentId, BigInt(documentId)))
    .orderBy(asc(documentRetrievalChunks.id));

  if (rows.length === 0) {
    throw new Error(`No retrieval chunks found for document ${documentId}`);
  }

  const texts = rows.map((row) => row.content ?? "");
  const chunkIds = rows.map((row) => Number(row.id));
  const { embeddings, dimension } = await client.embedTexts(texts);

  await storeExperimentalEmbeddings({
    documentId,
    retrievalChunkIds: chunkIds,
    vectors: embeddings,
    provider: config.provider,
    model: config.model,
    version: config.version,
    dimension,
  });

  return {
    provider: config.provider,
    model: config.model,
    version: config.version,
    dimension,
    embeddedChunkCount: rows.length,
  };
}

export async function experimentalEmbedQuery(
  text: string,
  overrides?: Partial<ExperimentalEmbeddingConfig>,
): Promise<{ vector: number[]; metadata: ExperimentalEmbeddingMetadata }> {
  const config = resolveExperimentalConfig(overrides);
  const client = new ExperimentalEmbeddingClient(config);
  const { embeddings, dimension } = await client.embedTexts([text]);
  const vector = embeddings[0];
  if (!vector) {
    throw new Error("Experimental query embedding failed: empty response");
  }

  return {
    vector,
    metadata: {
      provider: config.provider,
      model: config.model,
      version: config.version,
      dimension,
    },
  };
}

import { randomUUID } from "node:crypto";
import type { DeleteResult, ObjectRef } from "@launchstack/core/storage";

import { env } from "~/env";
import { resolveStorageLocationId } from "~/lib/storage-location-id";

// ---------------------------------------------------------------------------
// StorageError — wraps provider errors with provider name context
// ---------------------------------------------------------------------------

export class StorageError extends Error {
  constructor(
    message: string,
    public readonly provider: string,
    public readonly cause?: Error,
  ) {
    super(`[${provider}] ${message}`);
    this.name = "StorageError";
  }
}

// ---------------------------------------------------------------------------
// Backend resolution
// ---------------------------------------------------------------------------

export type StorageBackend = "s3" | "database";

function s3VarsConfigured(): boolean {
  return Boolean(
    env.server.NEXT_PUBLIC_S3_ENDPOINT &&
      env.server.S3_REGION &&
      env.server.S3_ACCESS_KEY &&
      env.server.S3_SECRET_KEY &&
      env.server.S3_BUCKET_NAME,
  );
}

/**
 * Resolves the active storage backend. Honors an explicit
 * NEXT_PUBLIC_STORAGE_PROVIDER setting; otherwise infers from whether the full
 * set of S3 env vars is present (auto-fallback to Postgres).
 */
export function resolveStorageBackend(): StorageBackend {
  const explicit = env.server.NEXT_PUBLIC_STORAGE_PROVIDER;
  if (explicit === "s3" || explicit === "database") {
    return explicit;
  }
  return s3VarsConfigured() ? "s3" : "database";
}

export function isS3Storage(): boolean {
  return resolveStorageBackend() === "s3";
}

export function isLocalStorage(): boolean {
  return resolveStorageBackend() === "database";
}

// ---------------------------------------------------------------------------
// Upload interface
// ---------------------------------------------------------------------------

export interface UploadInput {
  filename: string;
  data: Buffer | ArrayBuffer | Uint8Array;
  contentType?: string;
  userId: string;
}

export interface UploadResult {
  url: string;
  pathname: string;
  ref: ObjectRef;
  contentType?: string;
  provider: StorageBackend;
}

// ---------------------------------------------------------------------------
// Filename sanitisation (shared with s3-client)
// ---------------------------------------------------------------------------

function sanitizeFilename(filename: string): string {
  return filename.replace(/\s+/g, "-").replace(/[^a-zA-Z0-9.\-_]/g, "");
}

function toBuffer(data: Buffer | ArrayBuffer | Uint8Array): Buffer {
  return Buffer.from(
    data instanceof ArrayBuffer ? new Uint8Array(data) : data,
  );
}

// ---------------------------------------------------------------------------
// uploadFile — delegates to the active backend
// ---------------------------------------------------------------------------

export async function uploadFile(input: UploadInput): Promise<UploadResult> {
  const backend = resolveStorageBackend();
  if (backend === "s3") {
    return uploadToS3(input);
  }
  return uploadToDatabase(input);
}

async function uploadToS3(input: UploadInput): Promise<UploadResult> {
  try {
    const { putObject, getObjectUrl, ensureBucketExists } = await import(
      "~/server/storage/s3-client"
    );

    const safeName = sanitizeFilename(input.filename);
    const key = `documents/${randomUUID()}-${safeName || "upload"}`;
    const body = toBuffer(input.data);

    await ensureBucketExists();
    await putObject(key, body, input.contentType);

    return {
      url: getObjectUrl(key),
      pathname: key,
      ref: {
        adapter: "s3",
        storageLocationId: resolveStorageLocationId("s3"),
        key,
      },
      contentType: input.contentType,
      provider: "s3",
    };
  } catch (err) {
    if (err instanceof StorageError) throw err;
    throw new StorageError(
      err instanceof Error ? err.message : String(err),
      "s3",
      err instanceof Error ? err : undefined,
    );
  }
}

async function uploadToDatabase(input: UploadInput): Promise<UploadResult> {
  try {
    const { db } = await import("~/server/db");
    const { fileUploads } = await import("@launchstack/core/db/schema");

    const body = toBuffer(input.data);
    const safeName = sanitizeFilename(input.filename);
    const pathname = `documents/${randomUUID()}-${safeName || "upload"}`;

    const [row] = await db
      .insert(fileUploads)
      .values({
        userId: input.userId,
        filename: input.filename,
        mimeType: input.contentType ?? "application/octet-stream",
        fileData: body.toString("base64"),
        fileSize: body.length,
        storageProvider: "database",
        storageUrl: null,
        storagePathname: pathname,
      })
      .returning({ id: fileUploads.id });

    if (!row) {
      throw new Error("Insert into fileUploads returned no row");
    }

    return {
      url: `/api/files/${row.id}`,
      pathname,
      ref: {
        adapter: "database",
        storageLocationId: resolveStorageLocationId("database"),
        key: String(row.id),
      },
      contentType: input.contentType,
      provider: "database",
    };
  } catch (err) {
    if (err instanceof StorageError) throw err;
    throw new StorageError(
      err instanceof Error ? err.message : String(err),
      "database",
      err instanceof Error ? err : undefined,
    );
  }
}

// ---------------------------------------------------------------------------
// getFileUrl — resolve a storage key to a URL
// ---------------------------------------------------------------------------

export function getFileUrl(key: string, provider?: StorageBackend): string {
  const resolvedProvider = provider ?? resolveStorageBackend();

  if (resolvedProvider === "s3") {
    const endpoint =
      env.server.NEXT_PUBLIC_S3_ENDPOINT ?? env.client.NEXT_PUBLIC_S3_ENDPOINT;
    if (!endpoint) {
      throw new StorageError(
        "NEXT_PUBLIC_S3_ENDPOINT is not configured",
        "s3",
      );
    }
    const bucket = env.server.S3_BUCKET_NAME;
    const base = endpoint.replace(/\/+$/, "");
    return bucket ? `${base}/${bucket}/${key}` : `${base}/${key}`;
  }

  // database: key is already a /api/files/<id> URL
  return key;
}

// ---------------------------------------------------------------------------
// deleteFile — remove an object from storage
// ---------------------------------------------------------------------------

export async function deleteFile(
  keyOrUrl: string,
  provider?: StorageBackend,
): Promise<void> {
  const resolvedProvider = provider ?? resolveStorageBackend();

  if (resolvedProvider === "s3") {
    try {
      const { deleteObject } = await import("~/server/storage/s3-client");
      await deleteObject(keyOrUrl);
    } catch (err) {
      if (err instanceof StorageError) throw err;
      throw new StorageError(
        err instanceof Error ? err.message : String(err),
        "s3",
        err instanceof Error ? err : undefined,
      );
    }
    return;
  }

  // database: remove the fileUploads row matching this /api/files/<id> URL
  try {
    const idFromApiUrl = /^(?:https?:\/\/[^/]+)?\/api\/files\/(\d+)$/.exec(keyOrUrl)?.[1];
    const idFromOpaqueKey = /^(\d+)$/.exec(keyOrUrl)?.[1];
    const rawId = idFromApiUrl ?? idFromOpaqueKey;

    if (!rawId) {
      throw new StorageError(
        `Invalid database file reference: ${keyOrUrl}`,
        "database",
      );
    }

    const id = parseInt(rawId, 10);
    if (isNaN(id)) {
      throw new StorageError(
        `Invalid database file id: ${rawId}`,
        "database",
      );
    }

    const { db } = await import("~/server/db");
    const { fileUploads } = await import("@launchstack/core/db/schema");
    const { eq } = await import("drizzle-orm");
    await db.delete(fileUploads).where(eq(fileUploads.id, id));
  } catch (err) {
    if (err instanceof StorageError) throw err;
    throw new StorageError(
      err instanceof Error ? err.message : String(err),
      "database",
      err instanceof Error ? err : undefined,
    );
  }
}

function mapDeleteError(ref: ObjectRef, err: unknown): DeleteResult {
  const message = err instanceof Error ? err.message : String(err);
  const name =
    typeof err === "object" &&
    err &&
    "name" in err &&
    typeof (err as { name?: unknown }).name === "string"
      ? (err as { name: string }).name
      : "delete_failed";

  const providerCode =
    typeof err === "object" &&
    err &&
    "code" in err &&
    typeof (err as { code?: unknown }).code === "string"
      ? (err as { code: string }).code
      : typeof err === "object" &&
          err &&
          "Code" in err &&
          typeof (err as { Code?: unknown }).Code === "string"
        ? (err as { Code: string }).Code
        : undefined;

  const statusCode =
    typeof err === "object" &&
    err &&
    "$metadata" in err &&
    typeof (err as { $metadata?: { httpStatusCode?: unknown } }).$metadata
      ?.httpStatusCode === "number"
      ? (err as { $metadata: { httpStatusCode: number } }).$metadata.httpStatusCode
      : typeof err === "object" &&
          err &&
          "statusCode" in err &&
          typeof (err as { statusCode?: unknown }).statusCode === "number"
        ? (err as { statusCode: number }).statusCode
        : undefined;

  const code = providerCode ?? name;

  if (
    statusCode === 404 ||
    /NoSuchKey|NotFound|BlobNotFound|404/i.test(message) ||
    /NoSuchKey|NotFound|BlobNotFound/i.test(code)
  ) {
    return { ref, outcome: "not_found" };
  }

  if (
    statusCode === 401 ||
    statusCode === 403 ||
    /AccessDenied|Unauthorized|Forbidden|InvalidAccessKeyId|SignatureDoesNotMatch|InvalidToken|AuthFailed|Credentials|Credential|permission/i.test(
      `${code} ${message}`,
    ) ||
    /not configured|unparseable|misconfigured|configuration/i.test(message)
  ) {
    return {
      ref,
      outcome: "blocked",
      errorCode: code,
      message,
    };
  }

  return {
    ref,
    outcome: "retryable",
    errorCode: code,
    message,
  };
}

export async function deleteFileByRef(ref: ObjectRef): Promise<DeleteResult> {
  const adapter = ref.adapter;
  if (
    adapter !== "s3" &&
    adapter !== "database" &&
    adapter !== "vercel-blob" &&
    adapter !== "uploadthing"
  ) {
    return {
      ref,
      outcome: "rejected",
      errorCode: "unsupported_adapter",
      message: `Unsupported storage adapter: ${String(adapter)}`,
    };
  }

  try {
    const expectedLocationId = resolveStorageLocationId(adapter);
    if (ref.storageLocationId !== expectedLocationId) {
      return {
        ref,
        outcome: "blocked",
        errorCode: "storage_location_mismatch",
        message: `Ref storageLocationId (${ref.storageLocationId}) does not match active adapter location (${expectedLocationId}).`,
      };
    }
  } catch (err) {
    return {
      ref,
      outcome: "blocked",
      errorCode: "location_resolution_failed",
      message: err instanceof Error ? err.message : String(err),
    };
  }

  try {
    if (adapter === "s3" || adapter === "database") {
      await deleteFile(ref.key, adapter);
    } else if (adapter === "vercel-blob") {
      const { deleteFile: deleteBlobFile } = await import("~/server/storage/vercel-blob");
      await deleteBlobFile(ref.key);
    } else if (adapter === "uploadthing") {
      const { deleteUploadThingFileByKey } = await import("~/server/storage/uploadthing");
      const outcome = await deleteUploadThingFileByKey(ref.key);
      if (outcome.outcome === "retryable") {
        return {
          ref,
          outcome: "retryable",
          errorCode: outcome.errorCode,
          message: outcome.message,
        };
      }
      if (outcome.outcome === "blocked") {
        return {
          ref,
          outcome: "blocked",
          errorCode: outcome.errorCode,
          message: outcome.message,
        };
      }
      if (outcome.outcome === "not_found") {
        return { ref, outcome: "not_found" };
      }
    } else {
      return {
        ref,
        outcome: "rejected",
        errorCode: "unsupported_adapter",
        message: `Unsupported storage adapter: ${adapter}`,
      };
    }

    return { ref, outcome: "deleted" };
  } catch (err) {
    return mapDeleteError(ref, err);
  }
}

/**
 * Batch delete canonical storage refs with stable per-item outcomes.
 *
 * Refs are grouped by (adapter, storageLocationId) to preserve location
 * isolation and to allow adapter-level batching where available.
 */
export async function deleteManyByRef(refs: readonly ObjectRef[]): Promise<DeleteResult[]> {
  if (refs.length === 0) {
    return [];
  }

  const grouped = new Map<string, ObjectRef[]>();
  for (const ref of refs) {
    const groupKey = `${ref.adapter}::${ref.storageLocationId}`;
    const current = grouped.get(groupKey);
    if (current) {
      current.push(ref);
    } else {
      grouped.set(groupKey, [ref]);
    }
  }

  const results: DeleteResult[] = [];
  for (const groupRefs of grouped.values()) {
    const first = groupRefs[0];
    if (!first) continue;

    if (first.adapter === "s3") {
      let expectedLocationId: string;
      try {
        expectedLocationId = resolveStorageLocationId("s3");
      } catch (err) {
        for (const ref of groupRefs) {
          results.push({
            ref,
            outcome: "blocked",
            errorCode: "location_resolution_failed",
            message: err instanceof Error ? err.message : String(err),
          });
        }
        continue;
      }

      if (first.storageLocationId !== expectedLocationId) {
        for (const ref of groupRefs) {
          results.push({
            ref,
            outcome: "blocked",
            errorCode: "storage_location_mismatch",
            message: `Ref storageLocationId (${ref.storageLocationId}) does not match active adapter location (${expectedLocationId}).`,
          });
        }
        continue;
      }

      const { deleteObjects: deleteObjectsInS3 } = await import("~/server/storage/s3-client");
      const outcomes = await deleteObjectsInS3(groupRefs.map((ref) => ref.key));
      const outcomeByKey = new Map(outcomes.map((outcome) => [outcome.key, outcome] as const));

      for (const ref of groupRefs) {
        const outcome = outcomeByKey.get(ref.key);
        if (!outcome) {
          results.push({
            ref,
            outcome: "retryable",
            errorCode: "missing_delete_outcome",
            message: `No delete outcome returned for key "${ref.key}".`,
          });
          continue;
        }

        results.push({
          ref,
          outcome: outcome.outcome,
          errorCode: outcome.errorCode,
          message: outcome.message,
        });
      }
      continue;
    }

    for (const ref of groupRefs) {
      results.push(await deleteFileByRef(ref));
    }
  }

  return results;
}

export async function deleteObjects(keys: string[]): Promise<DeleteResult[]> {
  if (keys.length === 0) return [];

  const storageLocationId = resolveStorageLocationId("s3");
  const { deleteObjects: deleteObjectsInS3 } = await import(
    "~/server/storage/s3-client"
  );
  const outcomes = await deleteObjectsInS3(keys);

  return outcomes.map((outcome) => ({
    ref: {
      adapter: "s3",
      storageLocationId,
      key: outcome.key,
    },
    outcome: outcome.outcome,
    errorCode: outcome.errorCode,
    message: outcome.message,
  }));
}

/**
 * Delete a historical stored file by its URL, regardless of provider.
 *
 * @deprecated New lifecycle code must call `deleteFileByRef`; this shim is
 * retained only for unmanifested historical rows.
 */
export async function deleteFileByUrl(url: string): Promise<void> {
  if (!url) return;

  const { promoteLegacyUrlToRef } = await import("~/server/storage/legacy-promote");
  const promoted = promoteLegacyUrlToRef({ value: url });
  if (!promoted.ok) {
    throw new StorageError(
      `Ref promotion failed (${promoted.reason})`,
      resolveStorageBackend(),
    );
  }

  const result = await deleteFileByRef(promoted.ref);
  if (result.outcome === "retryable" || result.outcome === "blocked" || result.outcome === "rejected") {
    throw new StorageError(result.message ?? `Delete failed with outcome=${result.outcome}`, promoted.ref.adapter);
  }
}

// ---------------------------------------------------------------------------
// fetchFile — unified retrieval for any storage URL
// ---------------------------------------------------------------------------

export async function fetchFile(
  url: string,
  init?: RequestInit,
): Promise<Response> {
  const s3Endpoint =
    env.server.NEXT_PUBLIC_S3_ENDPOINT ?? env.client.NEXT_PUBLIC_S3_ENDPOINT;

  // S3 URLs — plain fetch
  if (s3Endpoint && url.startsWith(s3Endpoint)) {
    try {
      return await fetch(url, init);
    } catch (err) {
      throw new StorageError(
        `S3 storage unavailable at ${s3Endpoint}: ${err instanceof Error ? err.message : String(err)}`,
        "s3",
        err instanceof Error ? err : undefined,
      );
    }
  }

  // Legacy private Vercel Blob URLs — delegate to fetchBlob for auth
  try {
    const { fetchBlob, isPrivateBlobUrl } = await import(
      "~/server/storage/vercel-blob"
    );
    if (isPrivateBlobUrl(url)) {
      return await fetchBlob(url, init);
    }
  } catch {
    // vercel-blob module unavailable — fall through to plain fetch
  }

  // Public URLs (legacy Vercel Blob, etc.) — plain fetch
  try {
    return await fetch(url, init);
  } catch (err) {
    throw new StorageError(
      err instanceof Error ? err.message : String(err),
      "s3",
      err instanceof Error ? err : undefined,
    );
  }
}

import type { MutableRefObject, Dispatch, SetStateAction } from "react";

export type VoiceCallState = "connected" | "listening" | "speaking" | "muted";

interface PlayTextToSpeechParams {
  text: string;
  audioRef: MutableRefObject<HTMLAudioElement | null>;
  isPlayingAudio: boolean;
  isGeneratingTTSRef: MutableRefObject<boolean>;
  setCallState: Dispatch<SetStateAction<VoiceCallState>>;
  setIsLoadingAudio: Dispatch<SetStateAction<boolean>>;
  setIsPlayingAudio: Dispatch<SetStateAction<boolean>>;
  setError: Dispatch<SetStateAction<string | null>>;
  isProcessingRef: MutableRefObject<boolean>;
  ttsStartedAtRef: MutableRefObject<number>;
}

const canUseMediaSourceStreaming = (): boolean => {
  if (typeof window === "undefined") return false;
  const ua = navigator.userAgent;
  const isFirefox = ua.includes("Firefox");
  const isMac = ua.includes("Mac OS");
  if (isFirefox && isMac) return false;
  if (typeof MediaSource !== "undefined" && MediaSource.isTypeSupported("audio/mpeg")) return true;
  return false;
};

export async function playTextToSpeech({
  text,
  audioRef,
  isPlayingAudio,
  isGeneratingTTSRef,
  setCallState,
  setIsLoadingAudio,
  setIsPlayingAudio,
  setError,
  isProcessingRef,
  ttsStartedAtRef,
}: PlayTextToSpeechParams) {
  if (!text || text.trim().length === 0) return;
  if (isPlayingAudio || isGeneratingTTSRef.current) return;

  isGeneratingTTSRef.current = true;

  try {
    setError(null);
    setCallState("speaking");
    setIsLoadingAudio(true);
    setIsPlayingAudio(true);

    if (audioRef.current) {
      audioRef.current.pause();
      audioRef.current = null;
    }

    const response = await fetch("/api/voice/text-to-speech", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        text,
        modelId: "eleven_v3",
        stability: 0.5,
        similarityBoost: 0.75,
        useSpeakerBoost: true,
      }),
    });

    if (!response.ok) {
      const errorData = (await response.json().catch(() => ({ error: "Unknown error" }))) as { error?: string };
      throw new Error(errorData.error ?? `Failed to generate speech: ${response.statusText}`);
    }

    const setupAudioHandlers = (audio: HTMLAudioElement, urlToRevoke: string) => {
      audio.onloadeddata = () => setIsLoadingAudio(false);
      audio.onended = () => {
        setIsPlayingAudio(false);
        setIsLoadingAudio(false);
        setCallState("connected");
        URL.revokeObjectURL(urlToRevoke);
        audioRef.current = null;
        isGeneratingTTSRef.current = false;
      };
      audio.onerror = () => {
        setIsPlayingAudio(false);
        setIsLoadingAudio(false);
        setCallState("connected");
        setError("Failed to play audio");
        URL.revokeObjectURL(urlToRevoke);
        audioRef.current = null;
        isGeneratingTTSRef.current = false;
      };
    };

    if (canUseMediaSourceStreaming()) {
      const mediaSource = new MediaSource();
      const audio = new Audio();
      audioRef.current = audio;

      const mediaSourceUrl = URL.createObjectURL(mediaSource);
      audio.src = mediaSourceUrl;
      setupAudioHandlers(audio, mediaSourceUrl);

      mediaSource.addEventListener("sourceopen", () => {
        void (async () => {
          try {
            const sourceBuffer = mediaSource.addSourceBuffer("audio/mpeg");
            const reader = response.body!.getReader();

            const pump = async (): Promise<void> => {
              const { done, value } = await reader.read();
              if (done) {
                if (mediaSource.readyState === "open") mediaSource.endOfStream();
                return;
              }
              if (sourceBuffer.updating) {
                await new Promise<void>((resolve) => {
                  sourceBuffer.addEventListener("updateend", () => resolve(), { once: true });
                });
              }
              sourceBuffer.appendBuffer(value);
              await new Promise<void>((resolve) => {
                sourceBuffer.addEventListener("updateend", () => resolve(), { once: true });
              });
              return pump();
            };

            await pump();
          } catch (err) {
            console.error("❌ [Voice] Error streaming audio:", err);
            if (mediaSource.readyState === "open") mediaSource.endOfStream("decode");
          }
        })();
      });

      ttsStartedAtRef.current = performance.now();
      await audio.play();
    } else {
      const audioBlob = await response.blob();
      const audioUrl = URL.createObjectURL(audioBlob);

      const audio = new Audio(audioUrl);
      audioRef.current = audio;
      setupAudioHandlers(audio, audioUrl);

      await audio.play();
    }
  } catch (error) {
    console.error("Error playing audio:", error);
    setIsPlayingAudio(false);
    setIsLoadingAudio(false);
    setCallState("connected");
    setError(error instanceof Error ? error.message : "Failed to generate speech");
    isGeneratingTTSRef.current = false;
    setTimeout(() => setError(null), 5000);
  }
}

/**
 * Inngest Document Processing Function
 * Background job handler that delegates to the backend Doc Ingestion tool.
 *
 * ZIP archives are detected early and self-extracted: each file inside the ZIP
 * becomes its own document row, gets stored individually in Vercel Blob, and
 * receives a separate ingestion event. The original ZIP document is deleted.
 */

import { inngest } from "../client";
import { runDocIngestionTool } from "~/lib/tools";
import { db } from "~/server/db";
import { document, ocrJobs } from "@launchstack/core/db/schema";
import { findObjectByRef, registerArtifactEdge, registerObject } from "~/server/services/storage-manifest";
import { requestDocumentDeletionAndDispatch } from "~/server/services/storage-deletion-coordinator";
import { isStorageDeletionLifecycleEnabled } from "~/server/services/storage-deletion-flags";
import { putFile } from "~/server/storage/vercel-blob";
import { fetchFile } from "~/lib/storage";

import type {
  ProcessDocumentEventData,
  PipelineResult,
  VectorizedChunk,
} from "@launchstack/core/ocr/types";

export type { ProcessDocumentEventData, PipelineResult, VectorizedChunk };

// ---------------------------------------------------------------------------
// ZIP detection & extraction helpers
// ---------------------------------------------------------------------------

