function isZipFile(mimeType?: string, filename?: string): boolean {
  if (mimeType && ZIP_MIME_TYPES.has(mimeType)) return true;
  if (filename?.toLowerCase().endsWith(".zip")) return true;
  return false;
}

function shouldSkipEntry(path: string): boolean {
  return ZIP_SKIP_PATTERNS.some((re) => re.test(path));
}

function extractExtension(filename: string): string {
  const dot = filename.lastIndexOf(".");
  return dot >= 0 ? filename.slice(dot).toLowerCase() : "";
}

function mimeFromExtension(ext: string): string | undefined {
  return EXTENSION_TO_MIME[ext.toLowerCase()];
}

interface ExtractedFileInfo {
  documentId: number;
  documentUrl: string;
  documentName: string;
  originalFilename: string;
  mimeType: string | undefined;
  jobId: string;
  storageRef: import("@launchstack/core/storage").ObjectRef;
}

interface ZipExtractionResult {
  files: ExtractedFileInfo[];
  /** Full file tree (all paths after basic filtering) for the project summary */
  fileTree: string;
  /** README content extracted during the main pass (avoids re-downloading ZIP) */
  readmeContent: string;
  /** Stats for logging/user feedback */
  stats: {
    totalEntries: number;
    afterBasicFilter: number;
    skippedLowValue: number;
    indexed: number;
  };
}

const TEXT_FAST_PATH_MIMES = new Set([
  "text/plain", "text/markdown", "text/css", "text/xml",
  "text/javascript", "text/typescript", "text/jsx", "text/tsx",
  "text/csv", "text/html", "application/json",
]);

const TEXT_FAST_PATH_EXTENSIONS = new Set([
  ".txt", ".md", ".markdown", ".log", ".rst", ".adoc",
  ".py", ".js", ".ts", ".jsx", ".tsx", ".css", ".scss", ".less",
  ".java", ".c", ".cpp", ".h", ".hpp", ".go", ".rs", ".rb", ".php",
  ".swift", ".kt", ".sh", ".bash", ".sql", ".r", ".lua", ".pl", ".scala",
  ".xml", ".yaml", ".yml", ".toml", ".ini", ".cfg", ".env",
  ".json", ".geojson", ".csv",
]);

const EXTENSIONLESS_TEXT_FILENAMES = new Set([
  "makefile", "dockerfile", "license", "licence", "readme",
  "gemfile", "procfile", "vagrantfile", "rakefile", "brewfile",
  "justfile", "taskfile",
]);

function isTextFastPathFile(mimeType?: string, filename?: string): boolean {
  if (mimeType && TEXT_FAST_PATH_MIMES.has(mimeType)) return true;
  if (filename) {
    const ext = extractExtension(filename);
    if (ext && TEXT_FAST_PATH_EXTENSIONS.has(ext)) return true;
    const base = filename.split("/").pop()?.toLowerCase() ?? "";
    if (EXTENSIONLESS_TEXT_FILENAMES.has(base)) return true;
  }
  return false;
}

function sniffTextContent(buffer: Buffer): boolean {
  const sample = buffer.subarray(0, 1024);
  let nullCount = 0;
  for (let i = 0; i < sample.length; i++) {
    if (sample[i] === 0) nullCount++;
  }
  return nullCount === 0;
}

// ---------------------------------------------------------------------------
// Inngest Function
// ---------------------------------------------------------------------------
import { handleProcessDocumentFailure } from "./processDocumentFailure";
export const uploadDocument = inngest.createFunction(
  {
    id: "process-document",
    name: "Document Ingestion Pipeline (V2)",
    retries: 5,
    concurrency: [{ limit: 3 }],
    throttle: { limit: 30, period: "1m" },
    timeouts: { finish: "120m" },
    onFailure: handleProcessDocumentFailure,
    },
  { event: "document/process.requested" },
  async ({ event, step }) => {
    const eventData = event.data;
    const routingName = eventData.originalFilename ?? eventData.documentName;

    // ------------------------------------------------------------------
    // ZIP self-extraction: detect ZIP, extract files, fan out
    // ------------------------------------------------------------------
    if (isZipFile(eventData.mimeType, routingName)) {
      console.log(
        `[ProcessDocument] ZIP detected: "${routingName}", extracting files...`,
      );

      const MAX_EXTRACTED_FILES = 500;
      const MAX_FILE_SIZE_BYTES = 10 * 1024 * 1024; // 10MB per file

      const extraction = await step.run(
        "extract-zip-archive",
        async (): Promise<ZipExtractionResult> => {
          const JSZip = (await import("jszip")).default;

          const res = await fetchFile(eventData.documentUrl);
          if (!res.ok) {
            throw new Error(
              `Failed to fetch ZIP archive: ${res.status} ${res.statusText}`,
            );
          }
          const zipBuffer = Buffer.from(await res.arrayBuffer());
          const zip = await JSZip.loadAsync(zipBuffer);

          const allPaths = Object.keys(zip.files);
          const entries = allPaths
            .filter((p) => !zip.files[p]!.dir && !shouldSkipEntry(p))
            .sort();

          // Smart relevance filter: skip low-value files, prioritize high-value ones
          const { selected: cappedEntries, totalBefore, skippedLowValue } =
            selectRelevantFiles(entries, MAX_EXTRACTED_FILES);

          console.log(
            `[ProcessDocument] ZIP contains ${allPaths.length} entries, ` +
              `${totalBefore} after basic filter, ${skippedLowValue} skipped as low-value, ` +
              `${cappedEntries.length} selected for indexing`,
          );

          // Build file tree + extract README in same pass (avoids re-downloading ZIP later)
          const fileTree = entries.map((p) => `  ${p}`).join("\n");
          let readmeContent = "";
          const readmePath = entries.find((p) => {
            const name = p.split("/").pop()?.toLowerCase() ?? "";
            return name === "readme.md" || name === "readme" || name === "readme.txt" || name === "readme.rst";
          });
          if (readmePath) {
            try {
              readmeContent = (await zip.files[readmePath]!.async("string")).slice(0, 8000);
            } catch { /* ignore read errors */ }
          }

          const archiveName = routingName;
          const results: ExtractedFileInfo[] = [];

          for (const entryPath of cappedEntries) {
            const ext = extractExtension(entryPath);
            const baseName = entryPath.split("/").pop() ?? entryPath;
            const titleName = baseName;

            if (ext === ".zip") {
              console.log(`[ProcessDocument] Skipping nested ZIP: ${entryPath}`);
              continue;
            }

            try {
              const entry = zip.files[entryPath]!;
              const compressedSize = (entry as unknown as { _data?: { compressedSize?: number } })._data?.compressedSize ?? 0;
              if (compressedSize > MAX_FILE_SIZE_BYTES) {
                console.warn(
                  `[ProcessDocument] Skipping oversized file: ${entryPath} (${(compressedSize / 1024 / 1024).toFixed(1)}MB)`,
                );
                continue;
              }

              const fileBuffer = Buffer.from(
                await entry.async("arraybuffer"),
              );

              if (fileBuffer.length > MAX_FILE_SIZE_BYTES) {
                console.warn(
                  `[ProcessDocument] Skipping oversized extracted file: ${entryPath} (${(fileBuffer.length / 1024 / 1024).toFixed(1)}MB)`,
                );
                continue;
              }

              let fileMime = mimeFromExtension(ext);
              if (!fileMime && !ext) {
                const lowerBase = baseName.toLowerCase();
                if (EXTENSIONLESS_TEXT_FILENAMES.has(lowerBase) || sniffTextContent(fileBuffer)) {
                  fileMime = "text/plain";
                }
              }

              console.log(
                `[ProcessDocument] Storing extracted file: ${entryPath} (${(fileBuffer.length / 1024).toFixed(1)}KB, mime=${fileMime ?? "unknown"})`,
              );

              const blob = await putFile({
                filename: baseName,
                data: fileBuffer,
                contentType: fileMime,
              });
              const child = await db.transaction(async (tx) => {
                const [newDoc] = await tx
                  .insert(document)
                  .values({
                    url: blob.url,
                    title: titleName,
                    mimeType: fileMime ?? null,
                    category: eventData.category,
                    companyId: BigInt(eventData.companyId),
                    ocrEnabled: true,
                    ocrProcessed: false,
                    sourceArchiveName: archiveName,
                  })
                  .returning({
                    id: document.id,
                    url: document.url,
                    title: document.title,
                  });

                if (!newDoc) return null;

                const childManifest = await registerObject(tx, {
                  ref: blob.ref,
                  companyId: BigInt(eventData.companyId),
                  documentId: newDoc.id,
                  contentType: fileMime,
                  sizeBytes: fileBuffer.length,
                  sourceOperation: "zip-extracted-child",
                });

                if (eventData.storageRef) {
                  const parentManifest = await findObjectByRef(tx, eventData.storageRef);
                  if (parentManifest && parentManifest.id !== childManifest.id) {
                    await registerArtifactEdge(tx, {
                      parentObjectId: parentManifest.id,
                      childObjectId: childManifest.id,
                      edgeType: "zip-child",
                    });
                  }
                }

                const childJobId = `ocr-${Date.now().toString(36)}-${Math.random().toString(36).substring(2, 10)}`;
                await tx.insert(ocrJobs).values({
                  id: childJobId,
                  companyId: BigInt(eventData.companyId),
                  userId: eventData.userId,
                  status: "queued",
                  documentUrl: blob.url,
                  documentName: titleName,
                });

                return { newDoc, childJobId };
              });

              if (child) {
                results.push({
                  documentId: child.newDoc.id,
                  documentUrl: blob.url,
                  documentName: titleName,
                  originalFilename: baseName,
                  mimeType: fileMime,
                  jobId: child.childJobId,
                  storageRef: blob.ref,
                });
              }
            } catch (err) {
              console.warn(
                `[ProcessDocument] Failed to extract ${entryPath}: ${err instanceof Error ? err.message : String(err)}`,
              );
            }
          }

          console.log(
            `[ProcessDocument] Extracted ${results.length} files from ${archiveName}`,
          );
          return {
            files: results,
            fileTree,
            readmeContent,
            stats: {
              totalEntries: allPaths.length,
              afterBasicFilter: totalBefore,
              skippedLowValue,
              indexed: results.length,
            },
          };
        },
      );

      const extractedFiles = extraction.files;

      // ----------------------------------------------------------------
      // Generate a project summary chunk from file tree + README content
      // ----------------------------------------------------------------
      if (extractedFiles.length > 0) {
        await step.run("generate-project-summary", async () => {
          const archiveName = routingName;
          const { fileTree, readmeContent, stats } = extraction;

          const summaryText = [
            `# Project Summary: ${archiveName}`,
            "",
            `**Indexing stats:** ${stats.indexed} files indexed out of ${stats.afterBasicFilter} ` +
              `(${stats.skippedLowValue} low-value files skipped: build output, generated code, assets)`,
            "",
            `## File Structure (${stats.afterBasicFilter} files)`,
            fileTree,
            "",
            ...(readmeContent
              ? ["## README", "", readmeContent]
              : []),
          ].join("\n");

          const summaryBlob = await putFile({
            filename: `_summary_${archiveName}.md`,
            data: Buffer.from(summaryText, "utf-8"),
            contentType: "text/markdown",
          });

          const summaryJobId = `ocr-${Date.now().toString(36)}-summary`;
          const summary = await db.transaction(async (tx) => {
            const [summaryDoc] = await tx
              .insert(document)
              .values({
                url: summaryBlob.url,
                title: `_project_summary.md`,
                mimeType: "text/markdown",
                category: eventData.category,
                companyId: BigInt(eventData.companyId),
                ocrEnabled: true,
                ocrProcessed: false,
                sourceArchiveName: archiveName,
              })
              .returning({ id: document.id });

            if (!summaryDoc) return null;

            const summaryManifest = await registerObject(tx, {
              ref: summaryBlob.ref,
              companyId: BigInt(eventData.companyId),
              documentId: summaryDoc.id,
              contentType: "text/markdown",
              sizeBytes: Buffer.byteLength(summaryText, "utf8"),
              sourceOperation: "zip-project-summary",
            });

            if (eventData.storageRef) {
              const parentManifest = await findObjectByRef(tx, eventData.storageRef);
              if (parentManifest && parentManifest.id !== summaryManifest.id) {
                await registerArtifactEdge(tx, {
                  parentObjectId: parentManifest.id,
                  childObjectId: summaryManifest.id,
                  edgeType: "zip-summary",
                });
              }
            }

            await tx.insert(ocrJobs).values({
              id: summaryJobId,
              companyId: BigInt(eventData.companyId),
              userId: eventData.userId,
              status: "queued",
              documentUrl: summaryBlob.url,
              documentName: `_project_summary.md`,
            });

            return { summaryDoc };
          });

          if (summary) {
            extractedFiles.push({
              documentId: summary.summaryDoc.id,
              documentUrl: summaryBlob.url,
              documentName: `_project_summary.md`,
              originalFilename: `_project_summary.md`,
              mimeType: "text/markdown",
              jobId: summaryJobId,
              storageRef: summaryBlob.ref,
            });

            console.log(
              `[ProcessDocument] Generated project summary for ${archiveName} (${summaryText.length} chars)`,
            );
          }
        });
      }

      const FAN_OUT_BATCH_SIZE = 10;
      if (extractedFiles.length > 0) {
        for (let i = 0; i < extractedFiles.length; i += FAN_OUT_BATCH_SIZE) {
          const batch = extractedFiles.slice(i, i + FAN_OUT_BATCH_SIZE);
          await step.sendEvent(
            `fan-out-batch-${i}`,
            batch.map((f) => ({
              name: "document/process.requested" as const,
              data: {
                jobId: f.jobId,
                documentUrl: f.documentUrl,
                documentName: f.documentName,
                originalFilename: f.originalFilename,
                companyId: eventData.companyId,
                userId: eventData.userId,
                documentId: f.documentId,
                category: eventData.category,
                mimeType: f.mimeType,
                storageRef: f.storageRef,
                artifactGroupId:
                  eventData.artifactGroupId ?? `document:${eventData.documentId}`,
                options: {
                  embeddingIndexKey: eventData.options?.embeddingIndexKey,
                },
              },
            })),
          );
          if (i + FAN_OUT_BATCH_SIZE < extractedFiles.length) {
            await step.sleep(`fan-out-delay-${i}`, "2s");
          }
        }
      }

      if (isStorageDeletionLifecycleEnabled()) {
        await step.run("request-zip-document-deletion", async () => {
          await requestDocumentDeletionAndDispatch({
            docId: eventData.documentId,
            companyId: Number(eventData.companyId),
            actorId: eventData.userId,
          });
          console.log(
            `[ProcessDocument] Requested lifecycle deletion for original ZIP document id=${eventData.documentId}`,
          );
        });
      } else {
        console.warn(
          "[ProcessDocument] Skipping ZIP source deletion because the lifecycle flag is disabled",
        );
      }

      return {
        success: true,
        jobId: eventData.jobId,
        extracted: extractedFiles.length,
        stats: extraction.stats,
      };
    }

    // ------------------------------------------------------------------
    // Fast path: text/code files skip the full OCR pipeline
    // ------------------------------------------------------------------
    if (isTextFastPathFile(eventData.mimeType, routingName)) {
      console.log(
        `[ProcessDocument] Text fast-path for "${routingName}" (mime=${eventData.mimeType ?? "none"})`,
      );

      const result = await runDocIngestionTool({
        ...eventData,
        runtime: {
          updateJobStatus: false,
          markFailureInDb: false,
          fastTextPath: true,
          runStep: async <T>(stepName: string, fn: () => Promise<T>) =>
            step.run(stepName, fn) as Promise<T>,
        },
      });

      if (result.success && eventData.documentId && eventData.companyId) {
        await step.sendEvent("trigger-metadata-extraction", {
          name: "company-metadata/extract.requested" as const,
          data: {
            documentId: eventData.documentId,
            companyId: String(eventData.companyId),
          },
        });

        // Re-anchor sticky notes against the new version once chunks are
        // in place. Skips the initial v1 pipeline since no prior anchors
        // can exist; only meaningful for subsequent versions.
        if (eventData.versionId) {
          await step.sendEvent("trigger-rehydrate-note-anchors", {
            name: "notes-anchors/rehydrate.requested" as const,
            data: {
              documentId: eventData.documentId,
              versionId: eventData.versionId,
            },
          });
        }
      }

      return result;
    }

    // ------------------------------------------------------------------
    // Normal (non-ZIP) document processing
    // ------------------------------------------------------------------
    const result = await runDocIngestionTool({
      ...eventData,
      runtime: {
        updateJobStatus: false,
        markFailureInDb: false,
        runStep: async <T>(stepName: string, fn: () => Promise<T>) =>
          step.run(stepName, fn) as Promise<T>,
      },
    });

    if (result.success && eventData.documentId && eventData.companyId) {
      await step.sendEvent("trigger-metadata-extraction", {
        name: "company-metadata/extract.requested" as const,
        data: {
          documentId: eventData.documentId,
          companyId: String(eventData.companyId),
        },
      });
    }

    return result;
  },
);

/**
 * Re-anchor sticky notes against a newly-processed document version.
 *
 * Anchors use the W3C Web Annotation pattern: a format-native `primary`
 * plus a durable `quote` (exact text with optional prefix/suffix). When a
 * new version is uploaded, the primary anchor (e.g. page + quads) is
 * almost always invalid — pagination shifts, OCR re-extracts, etc. — but
 * the quoted span usually still exists, possibly in a new location.
 *
 * Strategy per note:
 *   1. Already on the new version → skip (idempotent).
 *   2. Exact ILIKE match against the new version's context chunks → mark
 *      `resolved`, update `primary.page` to the matched chunk's page.
 *   3. Fuzzy match via `diff-match-patch` (the same library Hypothes.is
 *      uses via dom-anchor-text-quote) with a reflow-tolerant threshold
 *      → mark `drifted`, update `primary.page` to the best match.
 *   4. Neither → mark `orphaned`. We DO NOT move the note's versionId in
 *      this case: keeping it pinned to the original version preserves the
 *      truthful statement "this note was written against v3" and lets
 *      future code re-try rehydration against intervening versions.
 *
 * The embedding is regenerated for resolved/drifted notes because
 * `documentNoteEmbeddings.versionId` is a derived field used by retrievers
 * to scope results to the current version.
 */

import { and, asc, eq, isNotNull, sql } from "drizzle-orm";
import DiffMatchPatch from "diff-match-patch";

import { db } from "~/server/db";
import {
    documentNotes,
    documentContextChunks,
    type NoteAnchor,
    type AnchorStatus,
} from "@launchstack/core/db/schema";
import { embedNoteAsync } from "./embed-note";

// Fuzzy matcher knobs.
//
//   Match_Threshold lives on [0, 1]: 0 = exact, 1 = anything. 0.3 allows
//   reflow / whitespace changes and minor edits without crossing into
//   "semantically unrelated content" territory.
//
//   Match_Distance is the half-life of the location penalty. Large values
//   make location irrelevant, which is what we want here — the quote may
//   have moved many KB across the doc after re-OCR.
const MATCH_THRESHOLD = 0.3;
const MATCH_DISTANCE = 10_000;

export interface RehydrationResult {
    documentId: number;
    versionId: number;
    considered: number;
    resolved: number;
    drifted: number;
    orphaned: number;
    skipped: number;
}

interface ChunkRow {
    id: number | bigint;
    pageNumber: number | null;
    content: string;
}

/**
 * Run anchor rehydration for every anchored note on a document, against
 * the chunks already ingested for `newVersionId`. Idempotent: re-running
 * after a successful pass is a no-op.
 *
 * Throws if chunks for the target version are not yet in the DB — this
 * signals to the Inngest retry layer that the OCR pipeline hasn't
 * finished, and we should wait.
 */
export async function rehydrateNotesForDocument(
    documentId: number,
    newVersionId: number,
): Promise<RehydrationResult> {
    const notes = await db
        .select()
        .from(documentNotes)
        .where(
            and(
                eq(documentNotes.documentId, String(documentId)),
                isNotNull(documentNotes.anchor),
            ),
        );

    const result: RehydrationResult = {
        documentId,
        versionId: newVersionId,
        considered: notes.length,
        resolved: 0,
        drifted: 0,
        orphaned: 0,
        skipped: 0,
    };

    if (notes.length === 0) return result;

    const chunks = await fetchChunksForVersion(documentId, newVersionId);
    if (chunks.length === 0) {
        // OCR pipeline hasn't populated chunks yet. Let the caller retry.
        throw new Error(
            `[rehydrate] no context chunks for document=${documentId} version=${newVersionId} yet`,
        );
    }

    const dmp = new DiffMatchPatch();
    dmp.Match_Threshold = MATCH_THRESHOLD;
    dmp.Match_Distance = MATCH_DISTANCE;

    const newVersionBig = BigInt(newVersionId);

    for (const note of notes) {
        if (note.versionId === newVersionBig) {
            result.skipped += 1;
            continue;
        }
        const anchor = (note.anchor ?? null) as NoteAnchor | null;
        if (!anchor?.quote?.exact) {
            result.skipped += 1;
            continue;
        }

        const outcome = matchQuoteInChunks(anchor.quote.exact, chunks, dmp);
        const nextAnchor = rebuildAnchor(anchor, outcome);
        const status: AnchorStatus = outcome.kind;

        // Orphaned notes keep their original versionId — the quote no
        // longer lives in this version, so moving them would be a lie.
        // Resolved/drifted advance to the new version.
        const nextVersionId =
            status === "orphaned" ? note.versionId : newVersionBig;

        await db
            .update(documentNotes)
            .set({
                anchor: nextAnchor,
                anchorStatus: status,
                versionId: nextVersionId,
            })
            .where(eq(documentNotes.id, note.id));

        if (status === "resolved") result.resolved += 1;
        else if (status === "drifted") result.drifted += 1;
        else result.orphaned += 1;

        // Re-embed so the vector's versionId tag matches what the note now
        // says. Fire-and-forget — embedding failure must not revert the
        // anchor update.
        embedNoteAsync(note.id);
    }

    return result;
}

async function fetchChunksForVersion(
    documentId: number,
    versionId: number,
): Promise<ChunkRow[]> {
    const rows = await db
        .select({
            id: documentContextChunks.id,
            pageNumber: documentContextChunks.pageNumber,
            content: documentContextChunks.content,
        })
        .from(documentContextChunks)
        .where(
            and(
                eq(documentContextChunks.documentId, BigInt(documentId)),
                eq(documentContextChunks.versionId, BigInt(versionId)),
            ),
        )
        .orderBy(
            asc(documentContextChunks.pageNumber),
            asc(documentContextChunks.id),
        );
    return rows;
}

type MatchOutcome =
    | { kind: "resolved"; chunk: ChunkRow; index: number }
    | { kind: "drifted"; chunk: ChunkRow; index: number }
    | { kind: "orphaned" };

function matchQuoteInChunks(
    quote: string,
    chunks: ChunkRow[],
    dmp: DiffMatchPatch,
): MatchOutcome {
    const normQuote = normalize(quote);
    if (!normQuote) return { kind: "orphaned" };

    // 1) Exact match (cheap, covers most "PDF was re-OCR'd identically"
    //    cases). We normalize whitespace on both sides so line-wrap
    //    differences don't break a match.
    for (const chunk of chunks) {
        const idx = normalize(chunk.content).indexOf(normQuote);
        if (idx >= 0) return { kind: "resolved", chunk, index: idx };
    }

    // 2) Fuzzy match. diff-match-patch's `match_main` uses Bitap with
    //    a score function that blends edit-distance + location penalty.
    //    We scan each chunk with loc=0 (accept match anywhere) and keep
    //    the first chunk that accepts the quote within MATCH_THRESHOLD.
    for (const chunk of chunks) {
        const idx = dmp.match_main(chunk.content, quote, 0);
        if (idx >= 0) return { kind: "drifted", chunk, index: idx };
    }

    return { kind: "orphaned" };
}

function normalize(text: string): string {
    return text.replace(/\s+/g, " ").trim();
}

/**
 * Return a new anchor with the `primary` updated to reflect the new
 * version's layout. For PDFs, we update the page number to the matched
 * chunk's page (quads require the viewer; we recompute them when the
 * user next opens the note in a PDF.js-capable renderer).
 */
function rebuildAnchor(
    anchor: NoteAnchor,
    outcome: MatchOutcome,
): NoteAnchor {
    if (outcome.kind === "orphaned") {
        // Drop primary — it no longer points anywhere truthful.
        const { primary: _primary, ...rest } = anchor;
        return rest as NoteAnchor;
    }

    const page = outcome.chunk.pageNumber ?? undefined;
    if (anchor.type === "pdf" && typeof page === "number") {
        return {
            ...anchor,
            primary: { kind: "pdf", page, quads: [] },
        };
    }
    return anchor;
}

/**
 * Wait for at least one context chunk for `(documentId, versionId)` to
 * exist, polling with exponential backoff. Used by the Inngest handler to
 * bridge the gap between the "new version inserted" event and the OCR
 * pipeline actually finishing — without coupling the two functions
 * directly. Returns `true` if chunks appeared, `false` if the budget
 * elapsed.
 */
export async function waitForVersionChunks(
    documentId: number,
    versionId: number,
    opts: { maxWaitMs?: number; initialDelayMs?: number } = {},
): Promise<boolean> {
    const maxWait = opts.maxWaitMs ?? 180_000; // 3 min default
    let delay = opts.initialDelayMs ?? 2_000;
    const start = Date.now();

    while (Date.now() - start < maxWait) {
        const [row] = await db
            .select({ n: sql<number>`count(*)::int` })
            .from(documentContextChunks)
            .where(
                and(
                    eq(documentContextChunks.documentId, BigInt(documentId)),
                    eq(documentContextChunks.versionId, BigInt(versionId)),
                ),
            );
        if ((row?.n ?? 0) > 0) return true;
        await new Promise((r) => setTimeout(r, delay));
        delay = Math.min(delay * 1.6, 15_000);
    }
    return false;
}

