export interface DocumentUploadUserContext {
  userId: string;
  companyId: bigint;
}

export interface DocumentUploadParams {
  user: DocumentUploadUserContext;
  documentName: string;
  rawDocumentUrl: string;
  requestUrl: string;
  category?: string;
  preferredProvider?: string;
  explicitStorageType?: StorageType;
  mimeType?: string;
  originalFilename?: string;
  isWebsite?: boolean;
  /** Links crawled pages together for UI grouping */
  crawlGroupId?: string;
  embeddingIndexKey?: string;
  /** ObjectRef minted by the adapter that wrote rawDocumentUrl. */
  storageRef?: ObjectRef;
}

export interface DocumentUploadResult {
  jobId: string;
  eventIds: string[];
  storageType: StorageType;
  document: {
    id: number;
    title: string;
    url: string;
    category: string;
  };
  resolvedDocumentUrl: string;
}

function resolveStorageRef(rawDocumentUrl: string, supplied?: ObjectRef): ObjectRef {
  if (supplied) return supplied;

  const promoted = promoteLegacyUrlToRef({ value: rawDocumentUrl });
  if (!promoted.ok) {
    throw new Error(
      `Document upload requires an adapter ObjectRef; legacy reference promotion failed (${promoted.reason}).`,
    );
  }
  return promoted.ref;
}

/**
 * Create the initial (version 1) row in `document_versions` for a freshly-inserted
 * document, point the document at it via `currentVersionId`, and lock in `fileType`.
 *
 * This is the authoritative path for new uploads. Every document created after
 * Step 2 of the versioning rollout will have a v1 row from the start — the
 * backfill script is only for documents that existed before this change.
 *
 * Runs as a single transaction so the document row and its v1 version are
 * always consistent with each other.
 */
async function createInitialVersion(params: {
  documentId: number;
  url: string;
  mimeType: string | null | undefined;
  uploadedBy: string;
  ocrProcessed?: boolean;
  ocrMetadata?: Record<string, unknown>;
  storageObjectId?: number;
}): Promise<number> {
  const {
    documentId,
    url,
    mimeType,
    uploadedBy,
    ocrProcessed,
    ocrMetadata,
    storageObjectId,
  } = params;

  // Fall back to application/octet-stream only if the caller genuinely has no
  // MIME info. This matches the backfill script's behavior so old and new rows
  // look the same.
  const resolvedMime = mimeType ?? "application/octet-stream";

  return db.transaction(async (tx) => {
    const [version] = await tx
      .insert(documentVersions)
      .values({
        documentId: BigInt(documentId),
        versionNumber: 1,
        url,
        mimeType: resolvedMime,
        uploadedBy,
        ocrProcessed: ocrProcessed ?? false,
        ocrMetadata: ocrMetadata ?? null,
      })
      .returning({ id: documentVersions.id });

    if (!version) {
      throw new Error(
        `Failed to create initial document_versions row for document ${documentId}`
      );
    }

    await tx
      .update(document)
      .set({
        currentVersionId: BigInt(version.id),
        fileType: resolvedMime,
      })
      .where(eq(document.id, documentId));

    if (storageObjectId !== undefined) {
      await tx
        .update(storageObjects)
        .set({
          documentId: null,
          documentVersionId: BigInt(version.id),
        })
        .where(
          and(
            eq(storageObjects.id, storageObjectId),
            eq(storageObjects.documentId, BigInt(documentId)),
          ),
        );
    }

    return Number(version.id);
  });
}

/**
 * Core document upload handler shared by single-file and batch commits.
 */
export async function processDocumentUpload({
  user,
  documentName,
  rawDocumentUrl,
  requestUrl,
  category,
  preferredProvider,
  explicitStorageType,
  mimeType,
  originalFilename,
  isWebsite,
  embeddingIndexKey,
  storageRef,
}: DocumentUploadParams): Promise<DocumentUploadResult> {
  const resolvedStorageRef = resolveStorageRef(rawDocumentUrl, storageRef);
  const storageType = explicitStorageType ?? detectStorageType(rawDocumentUrl);
  const resolvedDocumentUrl =
    storageType === "database" ? toAbsoluteUrl(rawDocumentUrl, requestUrl) : rawDocumentUrl;

  const documentCategory = category ?? "Uncategorized";

  // ------------------------------------------------------------------
  // Credit pre-check (cloud mode only)
  // ------------------------------------------------------------------
  if (isCloudMode()) {
    // Rough estimate: 20 credits covers a typical document (OCR + embeddings)
    const estimatedCredits = shouldTranscribeFile(mimeType, originalFilename) ? 30 : 20;
    const sufficient = await hasTokens(user.companyId, estimatedCredits);
    if (!sufficient) {
      throw new Error(
        "Insufficient credits to process this document. Please add more credits to continue."
      );
    }
  }

  // Resolve the embedding index key ONCE at enqueue time and thread it through
  // the Inngest event payload. The worker must never re-resolve from DB — that
  // would race against a mid-flight `updateCompany` index switch and produce
  // embeddings under the wrong index_key. Prefer `pending` during an active
  // reindex so new docs end up in the in-flight target.
  const resolvedEmbeddingIndexKey =
    embeddingIndexKey ??
    (await resolveIngestIndexKey(user.companyId)) ??
    undefined;

  // ------------------------------------------------------------------
  // Audio file: save the original audio as a document, then create a
  // separate transcript document that goes through the embedding pipeline.
  // ------------------------------------------------------------------
  if (shouldTranscribeFile(mimeType, originalFilename)) {
    console.log(`[DocumentUpload] Audio file detected: ${documentName}, transcribing...`);

    const audioDocument = await createDocumentRecord({
      url: rawDocumentUrl,
      title: documentName,
      mimeType,
      category: documentCategory,
      companyId: user.companyId,
      ocrEnabled: false,
      ocrProcessed: true,
      storageRef: resolvedStorageRef,
      sourceOperation: "audio-upload",
    });

    // The original audio file is its own v1. Embeddings are generated from the
    // transcript document (below), not the audio itself — but we still create
    // a version row so delete/revert works consistently across file types.
    await createInitialVersion({
      documentId: audioDocument.id,
      url: rawDocumentUrl,
      mimeType: mimeType ?? null,
      uploadedBy: user.userId,
      ocrProcessed: true,
      storageObjectId: audioDocument.storageObjectId,
    });

    try {
      getEngine();
      const transcriptionResult = await transcribeAudioFromUrl(
        resolvedDocumentUrl,
        originalFilename || documentName,
        user.companyId,
      );

      const textBlob = await uploadFile({
        filename: `${documentName}-transcription.txt`,
        data: Buffer.from(transcriptionResult.text, "utf-8"),
        contentType: "text/plain",
        userId: user.userId,
      });

      const transcriptionMetadata = {
        source: "whisper",
        audioFilename: originalFilename || documentName,
        audioDocumentId: audioDocument.id,
        audioUrl: resolvedDocumentUrl,
        language: transcriptionResult.language,
        confidence: transcriptionResult.confidence,
        segments: transcriptionResult.segments,
        transcribedAt: new Date().toISOString(),
      };

      const transcriptName = `${documentName} (Transcription)`;

      const transcriptDocument = await createDocumentRecord({
        url: textBlob.url,
        title: transcriptName,
        mimeType: "text/plain",
        category: documentCategory,
        companyId: user.companyId,
        ocrEnabled: true,
        ocrProcessed: false,
        ocrMetadata: transcriptionMetadata,
        storageRef: textBlob.ref,
        sourceOperation: "audio-transcription",
        parentObjectId: audioDocument.storageObjectId,
        parentEdgeType: "audio-transcript",
      });

      // The transcript document is what goes through the OCR-to-Vector pipeline,
      // so its v1 version is the one that will receive embeddings. We capture
      // the versionId and forward it to the pipeline so every chunk/structure/
      // metadata/preview row gets tagged with the correct version.
      const transcriptVersionId = await createInitialVersion({
        documentId: transcriptDocument.id,
        url: textBlob.url,
        mimeType: "text/plain",
        uploadedBy: user.userId,
        ocrProcessed: false,
        ocrMetadata: transcriptionMetadata,
        storageObjectId: transcriptDocument.storageObjectId,
      });

      const { jobId, eventIds } = await triggerJob({
        documentUrl: textBlob.url,
        documentName: transcriptName,
        companyId: user.companyId,
        userId: user.userId,
        documentId: transcriptDocument.id,
        category: documentCategory,
        preferredProvider,
        mimeType: "text/plain",
        originalFilename: `${documentName}-transcription.txt`,
        transcriptionMetadata,
        versionId: transcriptVersionId,
        embeddingIndexKey: resolvedEmbeddingIndexKey,
        storageRef: textBlob.ref,
        artifactGroupId: `document:${transcriptDocument.id}`,
      });

      console.log(`[DocumentUpload] Audio + transcript saved: audio docId=${audioDocument.id}, transcript docId=${transcriptDocument.id}`);

      return {
        jobId,
        eventIds,
        storageType,
        document: audioDocument,
        resolvedDocumentUrl,
      };
    } catch (error) {
      console.error(`[DocumentUpload] Audio transcription failed for ${documentName}:`, error);
      return {
        jobId: "",
        eventIds: [],
        storageType,
        document: audioDocument,
        resolvedDocumentUrl,
      };
    }
  }

  // ------------------------------------------------------------------
  // Normal (non-audio) document processing
  // ------------------------------------------------------------------
  const newDocument = await createDocumentRecord({
    url: rawDocumentUrl,
    title: documentName,
    mimeType,
    category: documentCategory,
    companyId: user.companyId,
    ocrEnabled: true,
    ocrProcessed: false,
    storageRef: resolvedStorageRef,
    sourceOperation: "document-upload",
  });

  // Create the v1 row for this document and lock in its file type. The
  // returned versionId is forwarded to the OCR-to-Vector pipeline so every
  // embedding/structure/metadata row gets tagged with the version it came from.
  const versionId = await createInitialVersion({
    documentId: newDocument.id,
    url: rawDocumentUrl,
    mimeType,
    uploadedBy: user.userId,
    storageObjectId: newDocument.storageObjectId,
  });

  const { jobId, eventIds } = await triggerJob({
    documentUrl: resolvedDocumentUrl,
    documentName,
    companyId: user.companyId,
    userId: user.userId,
    documentId: newDocument.id,
    category: documentCategory,
    preferredProvider,
    mimeType,
    originalFilename,
    isWebsite,
    versionId,
    embeddingIndexKey: resolvedEmbeddingIndexKey,
    storageRef: resolvedStorageRef,
    artifactGroupId: `document:${newDocument.id}`,
  });

  return {
    jobId,
    eventIds,
    storageType,
    document: newDocument,
    resolvedDocumentUrl,
  };
}

// ------------------------------------------------------------------
// Video URL upload — download + transcribe via sidecar, then embed
// ------------------------------------------------------------------

export interface VideoUrlUploadParams {
  user: DocumentUploadUserContext;
  videoUrl: string;
  requestUrl: string;
  category: string;
  title?: string;
  preferredProvider?: string;
  embeddingIndexKey?: string;
  /** ObjectRef minted by the adapter that wrote rawDocumentUrl. */
  storageRef?: ObjectRef;
}

export async function processVideoUrlUpload({
  user,
  videoUrl,
  category,
  title,
  preferredProvider,
  embeddingIndexKey,
}: VideoUrlUploadParams): Promise<DocumentUploadResult> {
  if (!isVideoUrl(videoUrl)) {
    throw new Error("Unsupported video URL. Supported platforms include YouTube, Vimeo, TikTok, Twitter/X, and more.");
  }

  const documentCategory = category;

  const resolvedEmbeddingIndexKey =
    embeddingIndexKey ??
    (await resolveIngestIndexKey(user.companyId)) ??
    undefined;

  console.log(`[DocumentUpload] Video URL detected: ${videoUrl}, downloading & transcribing...`);

  // 1. Transcribe via sidecar (downloads audio with yt-dlp, then runs Whisper)
  const transcriptionResult = await transcribeVideoFromUrl(videoUrl);

  const documentName = title || transcriptionResult.title || "Video Transcription";

  // 2. Store the transcript as a text file in blob storage
  const textBlob = await putFile({
    filename: `${documentName}-transcription.txt`,
    data: Buffer.from(transcriptionResult.text, "utf-8"),
    contentType: "text/plain",
  });

  const transcriptionMetadata = {
    source: "whisper-ytdlp",
    videoTitle: transcriptionResult.title,
    videoDuration: transcriptionResult.duration,
    videoUrl,
    language: transcriptionResult.language,
    confidence: transcriptionResult.confidence,
    transcribedAt: new Date().toISOString(),
  };

  const transcriptName = `${documentName} (Transcription)`;

  // 3. Create the transcript document record
  const transcriptDocument = await createDocumentRecord({
    url: textBlob.url,
    title: transcriptName,
    mimeType: "text/plain",
    category: documentCategory,
    companyId: user.companyId,
    ocrEnabled: true,
    ocrProcessed: false,
    ocrMetadata: transcriptionMetadata,
    storageRef: textBlob.ref,
    sourceOperation: "video-transcription",
  });

  const transcriptVersionId = await createInitialVersion({
    documentId: transcriptDocument.id,
    url: textBlob.url,
    mimeType: "text/plain",
    uploadedBy: user.userId,
    ocrProcessed: false,
    ocrMetadata: transcriptionMetadata,
    storageObjectId: transcriptDocument.storageObjectId,
  });

  // 4. Trigger embedding pipeline
  const { jobId, eventIds } = await triggerJob({
    documentUrl: textBlob.url,
    documentName: transcriptName,
    companyId: user.companyId,
    userId: user.userId,
    documentId: transcriptDocument.id,
    category: documentCategory,
    preferredProvider,
    mimeType: "text/plain",
    originalFilename: `${documentName}-transcription.txt`,
    transcriptionMetadata,
    versionId: transcriptVersionId,
    embeddingIndexKey: resolvedEmbeddingIndexKey,
    storageRef: textBlob.ref,
    artifactGroupId: `document:${transcriptDocument.id}`,
  });

  console.log(`[DocumentUpload] Video transcript saved: docId=${transcriptDocument.id}, title="${documentName}"`);

  return {
    jobId,
    eventIds,
    storageType: detectStorageType(textBlob.url),
    document: transcriptDocument,
    resolvedDocumentUrl: textBlob.url,
  };
}

import "server-only";

import { ListObjectsV2Command } from "@aws-sdk/client-s3";
import type { ObjectRef } from "@launchstack/core/storage";
import { and, asc, eq, gt, like } from "drizzle-orm";

import { fileUploads } from "@launchstack/core/db/schema";
import { env } from "~/env";
import { resolveStorageLocationId, parseVercelBlobStoreIdFromToken } from "~/lib/storage-location-id";
import { db } from "~/server/db";
import { getS3BucketName, getS3Client } from "~/server/storage/s3-client";

export interface PrivilegedListObjectsInput {
  adapter: ObjectRef["adapter"];
  storageLocationId: string;
  prefix?: string;
  cursor?: string;
  limit?: number;
}

export interface PrivilegedInventoryObject {
  key: string;
  ref: ObjectRef;
  size?: number;
  lastModified?: string;
  etag?: string;
}

export type PrivilegedListObjectsErrorKind =
  | "unavailable"
  | "blocked"
  | "invalid_request"
  | "retryable";

export interface PrivilegedListObjectsError {
  kind: PrivilegedListObjectsErrorKind;
  code: string;
  message: string;
}

export type PrivilegedListObjectsResult =
  | {
      ok: true;
      objects: PrivilegedInventoryObject[];
      nextCursor?: string;
    }
  | {
      ok: false;
      error: PrivilegedListObjectsError;
    };

const DEFAULT_LIMIT = 200;
const MAX_LIMIT = 1000;

function clampLimit(input?: number): number {
  if (!Number.isFinite(input)) return DEFAULT_LIMIT;
  const value = Math.floor(input ?? DEFAULT_LIMIT);
  if (value < 1) return 1;
  if (value > MAX_LIMIT) return MAX_LIMIT;
  return value;
}

function locationMismatch(refLocationId: string, expectedLocationId: string): PrivilegedListObjectsResult {
  return {
    ok: false,
    error: {
      kind: "blocked",
      code: "storage_location_mismatch",
      message: `Requested storageLocationId (${refLocationId}) does not match active adapter location (${expectedLocationId}).`,
    },
  };
}

function makeRef(
  adapter: ObjectRef["adapter"],
  storageLocationId: string,
  key: string,
): ObjectRef {
  return { adapter, storageLocationId, key };
}

async function listS3Objects(input: Required<Pick<PrivilegedListObjectsInput, "storageLocationId">> & Omit<PrivilegedListObjectsInput, "storageLocationId">): Promise<PrivilegedListObjectsResult> {
  const limit = clampLimit(input.limit);

  try {
    const response = await getS3Client().send(
      new ListObjectsV2Command({
        Bucket: getS3BucketName(),
        Prefix: input.prefix,
        ContinuationToken: input.cursor,
        MaxKeys: limit,
      }),
    );

    const objects: PrivilegedInventoryObject[] = [];
    for (const entry of response.Contents ?? []) {
      if (!entry.Key) continue;
      objects.push({
        key: entry.Key,
        ref: makeRef("s3", input.storageLocationId, entry.Key),
        size: typeof entry.Size === "number" ? entry.Size : undefined,
        lastModified: entry.LastModified?.toISOString(),
        etag: entry.ETag,
      });
    }

    return {
      ok: true,
      objects,
      nextCursor: response.IsTruncated ? response.NextContinuationToken : undefined,
    };
  } catch (err) {
    return {
      ok: false,
      error: {
        kind: "retryable",
        code: "s3_list_failed",
        message: err instanceof Error ? err.message : String(err),
      },
    };
  }
}

async function listVercelBlobObjects(input: Required<Pick<PrivilegedListObjectsInput, "storageLocationId">> & Omit<PrivilegedListObjectsInput, "storageLocationId">): Promise<PrivilegedListObjectsResult> {
  const token = env.server.BLOB_READ_WRITE_TOKEN ?? process.env.BLOB_READ_WRITE_TOKEN;
  if (!token) {
    return {
      ok: false,
      error: {
        kind: "unavailable",
        code: "blob_token_missing",
        message: "BLOB_READ_WRITE_TOKEN is not configured.",
      },
    };
  }

  const storeId = parseVercelBlobStoreIdFromToken(token);
  if (!storeId) {
    return {
      ok: false,
      error: {
        kind: "unavailable",
        code: "blob_token_unparseable",
        message: "BLOB_READ_WRITE_TOKEN is unparseable (expected token.split(\"_\")[3]).",
      },
    };
  }

  const expectedLocationId = resolveStorageLocationId("vercel-blob");
  if (input.storageLocationId !== expectedLocationId) {
    return locationMismatch(input.storageLocationId, expectedLocationId);
  }

  const limit = clampLimit(input.limit);

  try {
    const blobSdk = (await import("@vercel/blob")) as {
      list: (options: {
        token: string;
        prefix?: string;
        cursor?: string;
        limit?: number;
      }) => Promise<unknown>;
    };

    const listed = await blobSdk.list({
      token,
      prefix: input.prefix,
      cursor: input.cursor,
      limit,
    });

    const rawBlobs =
      typeof listed === "object" && listed !== null && Array.isArray((listed as { blobs?: unknown }).blobs)
        ? (listed as { blobs: Array<Record<string, unknown>> }).blobs
        : [];

    const objects: PrivilegedInventoryObject[] = [];
    for (const blob of rawBlobs) {
      const key = typeof blob.pathname === "string" ? blob.pathname : null;
      if (!key) continue;

      const uploadedAt = blob.uploadedAt;
      const uploadedAtIso =
        uploadedAt instanceof Date
          ? uploadedAt.toISOString()
          : typeof uploadedAt === "string"
            ? uploadedAt
            : undefined;

      objects.push({
        key,
        ref: makeRef("vercel-blob", input.storageLocationId, key),
        size: typeof blob.size === "number" ? blob.size : undefined,
        lastModified: uploadedAtIso,
        etag: typeof blob.etag === "string" ? blob.etag : undefined,
      });
    }

    const hasMore =
      typeof listed === "object" && listed !== null && (listed as { hasMore?: unknown }).hasMore === true;
    const nextCursor =
      hasMore &&
      typeof (listed as { cursor?: unknown }).cursor === "string" &&
      (listed as { cursor: string }).cursor.length > 0
        ? (listed as { cursor: string }).cursor
        : undefined;

    return {
      ok: true,
      objects,
      nextCursor,
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    if (/not supported|unsupported|disabled/i.test(message)) {
      return {
        ok: false,
        error: {
          kind: "unavailable",
          code: "blob_listing_unavailable",
          message,
        },
      };
    }

    return {
      ok: false,
      error: {
        kind: "retryable",
        code: "blob_list_failed",
        message,
      },
    };
  }
}

async function listDatabaseObjects(input: Required<Pick<PrivilegedListObjectsInput, "storageLocationId">> & Omit<PrivilegedListObjectsInput, "storageLocationId">): Promise<PrivilegedListObjectsResult> {
  const expectedLocationId = resolveStorageLocationId("database");
  if (input.storageLocationId !== expectedLocationId) {
    return locationMismatch(input.storageLocationId, expectedLocationId);
  }

  const limit = clampLimit(input.limit);
  const cursor = input.cursor?.trim();
  const cursorId = cursor && cursor.length > 0 ? Number.parseInt(cursor, 10) : null;

  if (cursor && (cursorId == null || Number.isNaN(cursorId) || cursorId <= 0)) {
    return {
      ok: false,
      error: {
        kind: "invalid_request",
        code: "invalid_cursor",
        message: "Cursor must be a positive integer for database inventory scans.",
      },
    };
  }

  try {
    const predicates = [eq(fileUploads.storageProvider, "database")];
    if (cursorId != null) {
      predicates.push(gt(fileUploads.id, cursorId));
    }
    if (input.prefix && input.prefix.length > 0) {
      predicates.push(like(fileUploads.storagePathname, `${input.prefix}%`));
    }

    const rows = await db
      .select({
        id: fileUploads.id,
        fileSize: fileUploads.fileSize,
        createdAt: fileUploads.createdAt,
      })
      .from(fileUploads)
      .where(and(...predicates))
      .orderBy(asc(fileUploads.id))
      .limit(limit);

    const objects: PrivilegedInventoryObject[] = rows.map((row) => ({
      key: String(row.id),
      ref: makeRef("database", input.storageLocationId, String(row.id)),
      size: row.fileSize,
      lastModified: row.createdAt?.toISOString(),
    }));

    const nextCursor = rows.length === limit ? String(rows[rows.length - 1]!.id) : undefined;

    return {
      ok: true,
      objects,
      nextCursor,
    };
  } catch (err) {
    return {
      ok: false,
      error: {
        kind: "retryable",
        code: "database_list_failed",
        message: err instanceof Error ? err.message : String(err),
      },
    };
  }
}

/**
 * Privileged object inventory listing for storage-audit tooling.
 *
 * Server-only and intentionally not part of StoragePort.
 */
export async function listObjectsPrivileged(
  input: PrivilegedListObjectsInput,
): Promise<PrivilegedListObjectsResult> {
  if (input.adapter === "uploadthing") {
    return {
      ok: false,
      error: {
        kind: "unavailable",
        code: "uploadthing_list_unavailable",
        message: "UploadThing object listing is unavailable in this runtime.",
      },
    };
  }

  let expectedLocationId: string;
  try {
    expectedLocationId = resolveStorageLocationId(input.adapter);
  } catch (err) {
    return {
      ok: false,
      error: {
        kind: "blocked",
        code: "location_resolution_failed",
        message: err instanceof Error ? err.message : String(err),
      },
    };
  }

  if (input.storageLocationId !== expectedLocationId) {
    return locationMismatch(input.storageLocationId, expectedLocationId);
  }

  const normalizedInput = {
    ...input,
    storageLocationId: expectedLocationId,
  };

  if (input.adapter === "s3") {
    return listS3Objects(normalizedInput);
  }

  if (input.adapter === "vercel-blob") {
    return listVercelBlobObjects(normalizedInput);
  }

  if (input.adapter === "database") {
    return listDatabaseObjects(normalizedInput);
  }

  return {
    ok: false,
    error: {
      kind: "unavailable",
      code: "adapter_list_unavailable",
      message: `Object listing is unavailable for adapter "${input.adapter}".`,
    },
  };
}

