import {
  S3Client,
  PutObjectCommand,
  GetObjectCommand,
  DeleteObjectCommand,
  DeleteObjectsCommand,
  CreateBucketCommand,
  HeadBucketCommand,
} from "@aws-sdk/client-s3";
import { getSignedUrl } from "@aws-sdk/s3-request-presigner";

import { env } from "~/env";

// ---------------------------------------------------------------------------
// Singleton S3 client — lazy-initialized on first use
// ---------------------------------------------------------------------------

let _client: S3Client | null = null;
let _bucketEnsured = false;

export function getS3Client(): S3Client {
  if (!_client) {
    _client = new S3Client({
      endpoint: env.server.NEXT_PUBLIC_S3_ENDPOINT,
      region: env.server.S3_REGION ?? "us-east-1",
      credentials: {
        accessKeyId: env.server.S3_ACCESS_KEY!,
        secretAccessKey: env.server.S3_SECRET_KEY!,
      },
      forcePathStyle: true,
    });
  }
  return _client;
}

export function getS3BucketName(): string {
  return env.server.S3_BUCKET_NAME!;
}

// ---------------------------------------------------------------------------
// Bucket bootstrap — idempotent, runs once per process lifetime
// ---------------------------------------------------------------------------

export async function ensureBucketExists(): Promise<void> {
  if (_bucketEnsured) return;

  const client = getS3Client();
  const bucket = getS3BucketName();

  try {
    await client.send(new HeadBucketCommand({ Bucket: bucket }));
  } catch {
    // Bucket doesn't exist — create it
    try {
      await client.send(new CreateBucketCommand({ Bucket: bucket }));
      console.log(`[S3] Created bucket "${bucket}" at ${env.server.NEXT_PUBLIC_S3_ENDPOINT}`);
    } catch (createErr) {
      throw new Error(
        `Failed to create S3 bucket "${bucket}" at ${env.server.NEXT_PUBLIC_S3_ENDPOINT}: ${createErr instanceof Error ? createErr.message : String(createErr)}`,
      );
    }
  }

  _bucketEnsured = true;
}

// ---------------------------------------------------------------------------
// Core operations
// ---------------------------------------------------------------------------

export async function putObject(
  key: string,
  body: Buffer,
  contentType?: string,
): Promise<void> {
  const client = getS3Client();
  const bucket = getS3BucketName();
  try {
    await client.send(
      new PutObjectCommand({
        Bucket: bucket,
        Key: key,
        Body: body,
        ContentType: contentType,
      }),
    );
  } catch (err) {
    throw new Error(
      `Failed to upload object "${key}" to S3 at ${env.server.NEXT_PUBLIC_S3_ENDPOINT}: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

export function getObjectUrl(key: string): string {
  const endpoint = env.server.NEXT_PUBLIC_S3_ENDPOINT!;
  const bucket = getS3BucketName();
  // Strip trailing slash from endpoint to avoid double-slash
  return `${endpoint.replace(/\/+$/, "")}/${bucket}/${key}`;
}

export async function deleteObject(key: string): Promise<void> {
  const client = getS3Client();
  const bucket = getS3BucketName();
  try {
    await client.send(
      new DeleteObjectCommand({
        Bucket: bucket,
        Key: key,
      }),
    );
  } catch (err) {
    throw new Error(
      `Failed to delete object "${key}" from S3 at ${env.server.NEXT_PUBLIC_S3_ENDPOINT}: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

export interface DeleteObjectOutcome {
  key: string;
  outcome: "deleted" | "not_found" | "retryable" | "blocked";
  errorCode?: string;
  message?: string;
}

function isS3BlockedDeleteError(code: string, message?: string): boolean {
  const haystack = `${code} ${message ?? ""}`;
  return /AccessDenied|Unauthorized|Forbidden|InvalidAccessKeyId|SignatureDoesNotMatch|InvalidToken|ExpiredToken|Credentials|Credential|permission|AuthFailed/i.test(
    haystack,
  );
}

export async function deleteObjects(keys: string[]): Promise<DeleteObjectOutcome[]> {
  if (keys.length === 0) {
    return [];
  }

  const client = getS3Client();
  const bucket = getS3BucketName();

  try {
    const response = await client.send(
      new DeleteObjectsCommand({
        Bucket: bucket,
        Delete: {
          Objects: keys.map((key) => ({ Key: key })),
          Quiet: false,
        },
      }),
    );

    const outcomeByKey = new Map<string, DeleteObjectOutcome>();

    for (const deleted of response.Deleted ?? []) {
      if (!deleted.Key) continue;
      outcomeByKey.set(deleted.Key, {
        key: deleted.Key,
        outcome: "deleted",
      });
    }

    for (const error of response.Errors ?? []) {
      if (!error.Key) continue;
      const code = error.Code ?? "DeleteError";
      const isNotFound = /NoSuchKey|NotFound|404/i.test(code);
      const isBlocked = !isNotFound && isS3BlockedDeleteError(code, error.Message);
      outcomeByKey.set(error.Key, {
        key: error.Key,
        outcome: isNotFound ? "not_found" : isBlocked ? "blocked" : "retryable",
        errorCode: code,
        message: error.Message,
      });
    }

    return keys.map((key) => {
      return outcomeByKey.get(key) ?? {
        key,
        outcome: "deleted",
      };
    });
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    const name =
      typeof err === "object" &&
      err &&
      "name" in err &&
      typeof (err as { name?: unknown }).name === "string"
        ? (err as { name: string }).name
        : "DeleteObjectsFailed";
    const blocked = isS3BlockedDeleteError(name, message);
    return keys.map((key) => ({
      key,
      outcome: blocked ? "blocked" : "retryable",
      errorCode: blocked ? name : "DeleteObjectsFailed",
      message: `Failed to batch delete object "${key}" from S3 at ${env.server.NEXT_PUBLIC_S3_ENDPOINT}: ${message}`,
    }));
  }
}

// ---------------------------------------------------------------------------
// Presigned URLs
// ---------------------------------------------------------------------------

export async function getPresignedUploadUrl(
  key: string,
  contentType: string,
  expiresIn = 300,
): Promise<string> {
  const client = getS3Client();
  const bucket = getS3BucketName();
  try {
    return await getSignedUrl(
      client,
      new PutObjectCommand({
        Bucket: bucket,
        Key: key,
        ContentType: contentType,
      }),
      { expiresIn },
    );
  } catch (err) {
    throw new Error(
      `Failed to generate presigned upload URL for "${key}" at ${env.server.NEXT_PUBLIC_S3_ENDPOINT}: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

export async function getPresignedDownloadUrl(
  key: string,
  expiresIn = 300,
): Promise<string> {
  const client = getS3Client();
  const bucket = getS3BucketName();
  try {
    return await getSignedUrl(
      client,
      new GetObjectCommand({
        Bucket: bucket,
        Key: key,
      }),
      { expiresIn },
    );
  } catch (err) {
    throw new Error(
      `Failed to generate presigned download URL for "${key}" at ${env.server.NEXT_PUBLIC_S3_ENDPOINT}: ${err instanceof Error ? err.message : String(err)}`,
    );
  }
}

import {
  createCipheriv,
  createDecipheriv,
  randomBytes,
  timingSafeEqual,
} from "node:crypto";

import { createSlot } from "../internal/slot";

/**
 * The master key (base64-encoded 32-byte random value) is injected by the
 * host at startup via configureSecretBox(). A process.env fallback is kept
 * for the transitional window where some callers (tests, migration scripts,
 * CLI tools) still expect to import this module without a configured
 * Engine. Remove the fallback once all such entry points route through
 * createEngine / configureSecretBox.
 */

// The slot stores `string | null` so configureSecretBox(undefined) can
// clear a previously-registered key (matches the prior `_keyBase64 = ... ?? null`
// behavior used by tests).
const keySlot = createSlot<string | null>("crypto/keyBase64");

export interface SecretBoxConfig {
  /** EMBEDDING_SECRETS_KEY — base64-encoded 32-byte random value. */
  key: string | undefined;
}

export function configureSecretBox(config: SecretBoxConfig): void {
  keySlot.set(config.key ?? null);
}

/**
 * AES-256-GCM envelope encryption for short secrets (API keys) stored in the
 * database. The output format is a single base64 string so it round-trips
 * cleanly through Postgres `text` columns without bytea handling.
 *
 * Layout of the binary payload (before base64):
 *   byte 0      : key version (currently always 1)
 *   bytes 1-12  : 12-byte random IV (nonce)
 *   bytes 13-28 : 16-byte GCM auth tag
 *   bytes 29+   : ciphertext
 *
 * Rotation story: bump `CURRENT_KEY_VERSION`, keep the old key available via
 * another env var, and add a case to `resolveKey()` so existing ciphertexts
 * can still decrypt. For now a single version is sufficient.
 */

const CURRENT_KEY_VERSION = 1;
const IV_LENGTH = 12;
const TAG_LENGTH = 16;
const KEY_LENGTH = 32;

export class MissingSecretsKeyError extends Error {
  constructor() {
    super(
      "EMBEDDING_SECRETS_KEY is not configured. Required to encrypt per-company provider API keys. Generate with: node -e \"console.log(require('crypto').randomBytes(32).toString('base64'))\"",
    );
    this.name = "MissingSecretsKeyError";
  }
}

export class CiphertextDecodeError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "CiphertextDecodeError";
  }
}

function resolveKey(version: number): Buffer {
  if (version !== CURRENT_KEY_VERSION) {
    throw new CiphertextDecodeError(
      `Unknown encryption key version ${version}; expected ${CURRENT_KEY_VERSION}`,
    );
  }
  const raw = keySlot.get() ?? process.env.EMBEDDING_SECRETS_KEY;
  if (!raw) {
    throw new MissingSecretsKeyError();
  }
  const key = Buffer.from(raw, "base64");
  if (key.length !== KEY_LENGTH) {
    throw new CiphertextDecodeError(
      `EMBEDDING_SECRETS_KEY must decode to ${KEY_LENGTH} bytes (got ${key.length}). Ensure it is a base64-encoded 32-byte random value.`,
    );
  }
  return key;
}

/**
 * Encrypt a short secret. Returns the encoded ciphertext plus the key version
 * that was used — callers should persist both so future key rotations can
 * find the right key to decrypt each row.
 */
export function encryptSecret(plaintext: string): {
  ciphertext: string;
  keyVersion: number;
} {
  if (plaintext.length === 0) {
    throw new Error("Refusing to encrypt empty plaintext");
  }
  const key = resolveKey(CURRENT_KEY_VERSION);
  const iv = randomBytes(IV_LENGTH);
  const cipher = createCipheriv("aes-256-gcm", key, iv);
  const encrypted = Buffer.concat([
    cipher.update(plaintext, "utf8"),
    cipher.final(),
  ]);
  const tag = cipher.getAuthTag();
  const payload = Buffer.concat([
    Buffer.from([CURRENT_KEY_VERSION]),
    iv,
    tag,
    encrypted,
  ]);
  return {
    ciphertext: payload.toString("base64"),
    keyVersion: CURRENT_KEY_VERSION,
  };
}

/**
 * Decrypt a secret produced by `encryptSecret`. Throws if the payload is
 * malformed, the auth tag doesn't verify, or the key version is unknown.
 */
export function decryptSecret(ciphertext: string): string {
  const payload = Buffer.from(ciphertext, "base64");
  if (payload.length < 1 + IV_LENGTH + TAG_LENGTH + 1) {
    throw new CiphertextDecodeError("Ciphertext payload is too short");
  }
  const version = payload[0]!;
  const iv = payload.subarray(1, 1 + IV_LENGTH);
  const tag = payload.subarray(1 + IV_LENGTH, 1 + IV_LENGTH + TAG_LENGTH);
  const body = payload.subarray(1 + IV_LENGTH + TAG_LENGTH);
  const key = resolveKey(version);
  const decipher = createDecipheriv("aes-256-gcm", key, iv);
  decipher.setAuthTag(tag);
  try {
    const decrypted = Buffer.concat([decipher.update(body), decipher.final()]);
    return decrypted.toString("utf8");
  } catch (err) {
    throw new CiphertextDecodeError(
      err instanceof Error
        ? `Failed to decrypt secret: ${err.message}`
        : "Failed to decrypt secret",
    );
  }
}

/**
 * Convenience helper: decrypts and then constant-time compares with a known
 * value. Not currently used by the embedding path but handy for webhook
 * signature checks etc. Included here so all crypto lives in one module.
 */
export function timingSafeStringEqual(a: string, b: string): boolean {
  const aBuf = Buffer.from(a);
  const bBuf = Buffer.from(b);
  if (aBuf.length !== bBuf.length) return false;
  return timingSafeEqual(aBuf, bBuf);
}

import { eq } from "drizzle-orm";

import { getDb } from "../db";
import { company } from "../db/schema";
import { getCompanyCredentialsPlaintext } from "./company-credentials";
import { createSlot } from "../internal/slot";

export interface CompanyEmbeddingConfig {
  embeddingIndexKey?: string | null;
  openAIApiKey?: string | null;
  /**
   * Endpoint for the OpenAI-compatible embeddings provider. Required to use
   * that provider — there is no built-in default URL.
   */
  openAIBaseUrl?: string | null;
  huggingFaceApiKey?: string | null;
  ollamaBaseUrl?: string | null;
  ollamaModel?: string | null;
}

export interface EffectiveEmbeddingConfig {
  embeddingIndexKey?: string;
  openAIApiKey?: string;
  openAIBaseUrl?: string;
  huggingFaceApiKey?: string;
  ollamaBaseUrl?: string;
  ollamaModel?: string;
}

/**
 * Defaults used when a per-company override is absent or blank. apps/web/
 * src/server/engine.ts registers these via configureCompanyEmbeddingDefaults
 * so this module can be env-agnostic when it later moves to core. A
 * process.env fallback is retained for the transitional window.
 */
export interface CompanyEmbeddingDefaults {
  embeddingIndexKey?: string;
  openAIApiKey?: string;
  openAIBaseUrl?: string;
  huggingFaceApiKey?: string;
  ollamaBaseUrl?: string;
  ollamaEmbeddingModel?: string;
  ollamaModel?: string;
}

const defaultsSlot = createSlot<CompanyEmbeddingDefaults>(
  "embeddings/companyDefaults",
);

export function configureCompanyEmbeddingDefaults(
  defaults: CompanyEmbeddingDefaults,
): void {
  defaultsSlot.set(defaults);
}

function getDefaults(): CompanyEmbeddingDefaults {
  const registered = defaultsSlot.get();
  if (registered) return registered;
  // Endpoint and credential are read as a PAIR, most specific first, so a key
  // never reaches a service it does not belong to.
  const embedding = process.env.EMBEDDING_API_BASE_URL
    ? {
        baseUrl: process.env.EMBEDDING_API_BASE_URL,
        apiKey: process.env.EMBEDDING_API_KEY,
      }
    : {
        baseUrl: process.env.AI_BASE_URL,
        apiKey: process.env.AI_API_KEY ?? process.env.OPENAI_API_KEY,
      };

  return {
    embeddingIndexKey: process.env.EMBEDDING_INDEX,
    openAIApiKey: embedding.apiKey,
    openAIBaseUrl: embedding.baseUrl,
    huggingFaceApiKey: process.env.HUGGINGFACE_API_KEY,
    ollamaBaseUrl: process.env.OLLAMA_BASE_URL,
    ollamaEmbeddingModel: process.env.OLLAMA_EMBEDDING_MODEL,
    ollamaModel: process.env.OLLAMA_MODEL,
  };
}

function normalizeOptional(value: string | null | undefined): string | undefined {
  if (typeof value !== "string") return undefined;
  const trimmed = value.trim();
  return trimmed.length > 0 ? trimmed : undefined;
}

export function resolveEffectiveEmbeddingConfig(
  config?: CompanyEmbeddingConfig,
): EffectiveEmbeddingConfig {
  const defaults = getDefaults();

  // A credential and the endpoint it is sent to must come from the SAME
  // source. Resolving them independently would let a company's key fall
  // through to the deployment's URL and ship that key to whatever vendor the
  // operator configured globally — `.env.example` suggests SiliconFlow, so an
  // `sk-…` pasted into the field labelled "OpenAI API key" would go there.
  // Now that no built-in default endpoint backstops the pairing, they are
  // resolved together or not at all.
  const companyOpenAIApiKey = normalizeOptional(config?.openAIApiKey);
  const openAI = companyOpenAIApiKey
    ? {
        apiKey: companyOpenAIApiKey,
        baseUrl: normalizeOptional(config?.openAIBaseUrl),
      }
    : { apiKey: defaults.openAIApiKey, baseUrl: defaults.openAIBaseUrl };

  return {
    embeddingIndexKey:
      normalizeOptional(config?.embeddingIndexKey) ??
      defaults.embeddingIndexKey ??
      undefined,
    openAIApiKey: openAI.apiKey ?? undefined,
    openAIBaseUrl: openAI.baseUrl ?? undefined,
    huggingFaceApiKey:
      normalizeOptional(config?.huggingFaceApiKey) ??
      defaults.huggingFaceApiKey ??
      undefined,
    ollamaBaseUrl:
      normalizeOptional(config?.ollamaBaseUrl) ??
      defaults.ollamaBaseUrl ??
      undefined,
    ollamaModel:
      normalizeOptional(config?.ollamaModel) ??
      defaults.ollamaEmbeddingModel ??
      defaults.ollamaModel ??
      undefined,
  };
}

/**
 * Load the effective per-company embedding configuration. Secrets (API
 * keys) are decrypted from `company_embedding_credentials`; the
 * `embeddingIndexKey` still lives on the `company` row because it isn't a
 * secret and is frequently read alongside non-credential metadata.
 */
export async function getCompanyEmbeddingConfig(
  companyId: bigint | number | string,
): Promise<CompanyEmbeddingConfig | null> {
  const numericCompanyId =
    typeof companyId === "bigint" ? Number(companyId) : Number(companyId);

  if (!Number.isFinite(numericCompanyId)) {
    return null;
  }

  const [indexRow, creds] = await Promise.all([
    getDb()
      .select({
        activeIndexKey: company.activeEmbeddingIndexKey,
        legacyIndexKey: company.embeddingIndexKey,
      })
      .from(company)
      .where(eq(company.id, numericCompanyId))
      .limit(1),
    getCompanyCredentialsPlaintext(numericCompanyId),
  ]);

  if (!indexRow[0] && !creds) return null;

  // Prefer the new active column; fall back to the legacy column for
  // companies that pre-date migration 0012. Callers who need the
  // ingest-time vs query-time distinction should use
  // `resolveIngestIndexKey` / `resolveQueryIndexKey` from
  // `company-reindex-state` instead of reading this field directly.
  const indexKey =
    indexRow[0]?.activeIndexKey ?? indexRow[0]?.legacyIndexKey ?? null;

  return {
    embeddingIndexKey: indexKey,
    openAIApiKey: creds?.openAIApiKey ?? null,
    huggingFaceApiKey: creds?.huggingFaceApiKey ?? null,
    ollamaBaseUrl: creds?.ollamaBaseUrl ?? null,
    ollamaModel: creds?.ollamaModel ?? null,
  };
}

import type {
  SourceAdapter,
  SourceAdapterOptions,
  StandardizedDocument,
  StandardizedPage,
} from "../types";

export class PptxAdapter implements SourceAdapter {
  readonly name = "PptxAdapter";

  private static readonly MIME_TYPES = new Set([
    "application/vnd.openxmlformats-officedocument.presentationml.presentation",
    "application/vnd.ms-powerpoint",
  ]);

  private static readonly EXTENSIONS = new Set([".pptx", ".ppt"]);

  canHandle(mimeType: string, extension: string): boolean {
    return (
      PptxAdapter.MIME_TYPES.has(mimeType) ||
      PptxAdapter.EXTENSIONS.has(extension.toLowerCase())
    );
  }

  async process(
    input: string | Buffer,
    options?: SourceAdapterOptions,
  ): Promise<StandardizedDocument> {
    const startTime = Date.now();
    console.log(
      `[PptxAdapter] Processing: file=${options?.filename ?? "unknown"}, mime=${options?.mimeType ?? "none"}`,
    );

    const JSZip = (await import("jszip")).default;

    // #region agent log
    try {
      const typeGlobalFile = typeof global.File;
      const typeGlobalThisFile = typeof globalThis.File;
      await fetch('http://127.0.0.1:7243/ingest/bcb599e5-0995-455d-900a-f795e258dd22',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'pptx-adapter.ts:35',message:'Before polyfill',data:{typeGlobalFile, typeGlobalThisFile, nodeVersion: process.version},timestamp:Date.now()})}).catch(() => void 0);
    } catch {}
    // #endregion

    // Polyfill File for Node.js < 20 (required by cheerio/undici)
    if (!globalThis.File) {
      const { File } = await import("node:buffer");
      // @ts-expect-error - polyfill File for Node.js < 20 environment
      globalThis.File = File;
      // @ts-expect-error - polyfill File for Node.js < 20 environment
      global.File = File;
    }

    // #region agent log
    try {
      const typeGlobalFile = typeof global.File;
      const typeGlobalThisFile = typeof globalThis.File;
      await fetch('http://127.0.0.1:7243/ingest/bcb599e5-0995-455d-900a-f795e258dd22',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({location:'pptx-adapter.ts:47',message:'After polyfill',data:{typeGlobalFile, typeGlobalThisFile},timestamp:Date.now()})}).catch(() => void 0);
    } catch {}
    // #endregion

    const cheerio = await import("cheerio");

    const buffer = await this.resolveBuffer(input);
    console.log(`[PptxAdapter] Buffer resolved: ${buffer.length} bytes`);

    const zip = await JSZip.loadAsync(buffer);

    // Discover slide files (ppt/slides/slide1.xml, slide2.xml, …)
    const slideEntries = Object.keys(zip.files)
      .filter((name) => /^ppt\/slides\/slide\d+\.xml$/i.test(name))
      .sort((a, b) => {
        const slideNumRegex = /slide(\d+)/i;
        const numA = parseInt(slideNumRegex.exec(a)?.[1] ?? "0", 10);
        const numB = parseInt(slideNumRegex.exec(b)?.[1] ?? "0", 10);
        return numA - numB;
      });

    console.log(`[PptxAdapter] Found ${slideEntries.length} slides in ZIP`);

    const pages: StandardizedPage[] = [];

    for (let i = 0; i < slideEntries.length; i++) {
      const entry = slideEntries[i]!;
      const xml = await zip.files[entry]!.async("text");

      // cheerio is XML-mode capable; use xmlMode to parse slide XML
      const $ = cheerio.load(xml, { xmlMode: true });

      // Extract all text runs (<a:t> elements hold the actual text)
      const textParts: string[] = [];
      $("a\\:t, t").each((_idx, el) => {
        const text = $(el).text().trim();
        if (text.length > 0) {
          textParts.push(text);
        }
      });

      const slideText = textParts.join(" ").trim();
      console.log(
        `[PptxAdapter] Slide ${i + 1}: ${textParts.length} text runs, ${slideText.length} chars`,
      );

      pages.push({
        pageNumber: i + 1,
        textBlocks: slideText.length > 0
          ? [slideText]
          : [`[Slide ${i + 1}: no text content]`],
        tables: [],
      });
    }

    // If the PPTX has no slides at all, return a placeholder
    if (pages.length === 0) {
      console.warn("[PptxAdapter] No slides found in PPTX file");
      pages.push({
        pageNumber: 1,
        textBlocks: ["Empty presentation — no slides found."],
        tables: [],
      });
    }

    const elapsed = Date.now() - startTime;
    console.log(
      `[PptxAdapter] Done: ${pages.length} slides extracted (${elapsed}ms)`,
    );

    return {
      pages,
      metadata: {
        sourceType: "pptx",
        totalPages: pages.length,
        provider: "native_text",
        processingTimeMs: elapsed,
        confidenceScore: 85,
        originalFilename: options?.filename,
        mimeType: options?.mimeType,
      },
    };
  }

  private async resolveBuffer(input: string | Buffer): Promise<Buffer> {
    if (Buffer.isBuffer(input)) return input;

    const res = await fetch(input);
    if (!res.ok) {
      throw new Error(`PptxAdapter fetch failed: ${res.status}`);
    }
    const ab = await res.arrayBuffer();
    return Buffer.from(ab);
  }
}

import type {
  SourceAdapter,
  SourceAdapterOptions,
  StandardizedDocument,
} from "../types";
import { isGitHubExport, processGitHubExport } from "./github-export-adapter";

interface SlackMessage {
  type?: string;
  subtype?: string;
  user?: string;
  bot_id?: string;
  text?: string;
  ts?: string;
  thread_ts?: string;
  reply_count?: number;
  files?: { name?: string; title?: string; mimetype?: string }[];
}

/**
 * Unified JSON export adapter that dispatches to the correct handler
 * based on the structure of the parsed JSON content.
 *
 * Supported formats:
 *  - Slack workspace export (array of `{ type, text, ts }`)
 *  - GitHub CLI export (array of `{ number, title, state }`)
 *
 * Claims `.json` extension. On process(), parses the JSON, detects
 * the format, and delegates to the matching handler.
 */
export class JsonExportAdapter implements SourceAdapter {
  readonly name = "JsonExportAdapter";

  private static readonly EXTENSIONS = new Set([".json"]);

  canHandle(_mimeType: string, extension: string): boolean {
    return JsonExportAdapter.EXTENSIONS.has(extension.toLowerCase());
  }

  async process(
    input: string | Buffer,
    options?: SourceAdapterOptions,
  ): Promise<StandardizedDocument> {
    const raw = await this.resolveInput(input);
    const parsed: unknown = JSON.parse(raw);

    if (isGitHubExport(parsed)) {
      return processGitHubExport(parsed as unknown[], options);
    }

    if (this.isSlackExport(parsed)) {
      return this.processSlackExport(parsed as SlackMessage[], options);
    }

    return this.processGenericJson(raw, options);
  }

  // ---------------------------------------------------------------------------
  // Generic JSON fallback
  // ---------------------------------------------------------------------------

  private processGenericJson(
    raw: string,
    options?: SourceAdapterOptions,
  ): StandardizedDocument {
    const startTime = Date.now();
    const filename = options?.filename ?? "unknown";
    console.log(
      `[JsonExportAdapter] Unrecognized JSON structure, treating as plain text: file=${filename}`,
    );

    const PAGE_CHAR_LIMIT = 4000;
    const pages: { pageNumber: number; textBlocks: string[]; tables: import("../../ocr/types").ExtractedTable[] }[] = [];
    let cursor = 0;
    let pageNum = 1;
    while (cursor < raw.length) {
      let end = Math.min(cursor + PAGE_CHAR_LIMIT, raw.length);
      if (end < raw.length) {
        const lastNewline = raw.lastIndexOf("\n", end);
        if (lastNewline > cursor + PAGE_CHAR_LIMIT * 0.5) end = lastNewline + 1;
      }
      const chunk = raw.slice(cursor, end).trim();
      if (chunk.length > 0) {
        pages.push({ pageNumber: pageNum++, textBlocks: [chunk], tables: [] });
      }
      cursor = end;
    }

    if (pages.length === 0) {
      pages.push({ pageNumber: 1, textBlocks: [raw || "Empty JSON file."], tables: [] });
    }

    const elapsed = Date.now() - startTime;
    return {
      pages,
      metadata: {
        sourceType: "text",
        totalPages: pages.length,
        provider: "native_text",
        processingTimeMs: elapsed,
        confidenceScore: 70,
        originalFilename: filename,
        mimeType: options?.mimeType,
      },
    };
  }

  // ---------------------------------------------------------------------------
  // Slack handling
  // ---------------------------------------------------------------------------

  private processSlackExport(
    messages: SlackMessage[],
    options?: SourceAdapterOptions,
  ): StandardizedDocument {
    const startTime = Date.now();
    console.log(
      `[JsonExportAdapter/Slack] Processing: file=${options?.filename ?? "unknown"}`,
    );

    const filtered = messages.filter(
      (m) =>
        m.type === "message" &&
        !m.subtype?.startsWith("channel_") &&
        m.subtype !== "bot_message" &&
        typeof m.text === "string" &&
        m.text.trim().length > 0,
    );

    console.log(
      `[JsonExportAdapter/Slack] ${messages.length} total messages, ${filtered.length} after filtering`,
    );

    const channelName = this.inferChannelName(options?.filename);
    const grouped = this.groupByDate(filtered);
    const dateKeys = Object.keys(grouped).sort();

    const pages = dateKeys.map((date, idx) => {
      const dayMessages = grouped[date]!;
      const lines = dayMessages.map((m) => this.formatMessage(m));
      const header = `# ${channelName} — ${date}\n\n`;
      return {
        pageNumber: idx + 1,
        textBlocks: [header + lines.join("\n\n")],
        tables: [] as import("../../ocr/types").ExtractedTable[],
      };
    });

    if (pages.length === 0) {
      pages.push({
        pageNumber: 1,
        textBlocks: [`No user messages found in ${channelName}.`],
        tables: [],
      });
    }

    const elapsed = Date.now() - startTime;
    console.log(
      `[JsonExportAdapter/Slack] Done: ${pages.length} pages across ${dateKeys.length} days (${elapsed}ms)`,
    );

    return {
      pages,
      metadata: {
        sourceType: "text",
        totalPages: pages.length,
        provider: "native_text",
        processingTimeMs: elapsed,
        confidenceScore: 95,
        originalFilename: options?.filename,
        mimeType: options?.mimeType,
      },
    };
  }

  // ---------------------------------------------------------------------------
  // Slack detection and helpers
  // ---------------------------------------------------------------------------

  private isSlackExport(data: unknown): boolean {
    if (!Array.isArray(data) || data.length === 0) return false;
    const sample = data.slice(0, 5);
    return sample.every(
      (item: unknown) =>
        typeof item === "object" &&
        item !== null &&
        "ts" in item &&
        ("text" in item || "type" in item),
    );
  }

  private async resolveInput(input: string | Buffer): Promise<string> {
    if (Buffer.isBuffer(input)) return input.toString("utf-8");
    if (
      input.startsWith("http://") ||
      input.startsWith("https://") ||
      input.startsWith("/")
    ) {
      const res = await fetch(input);
      if (!res.ok)
        throw new Error(`JsonExportAdapter fetch failed: ${res.status}`);
      return res.text();
    }
    return input;
  }

  private inferChannelName(filename?: string): string {
    if (!filename) return "Slack Channel";
    const parts = filename.replace(/\\/g, "/").split("/");
    if (parts.length >= 2) {
      return `#${parts[parts.length - 2]}`;
    }
    return `#${parts[0]!.replace(/\.json$/, "")}`;
  }

  private groupByDate(
    messages: SlackMessage[],
  ): Record<string, SlackMessage[]> {
    const groups: Record<string, SlackMessage[]> = {};
    for (const msg of messages) {
      const ts = parseFloat(msg.ts ?? "0");
      const date = new Date(ts * 1000).toISOString().slice(0, 10);
      (groups[date] ??= []).push(msg);
    }
    return groups;
  }

  private formatMessage(msg: SlackMessage): string {
    const ts = parseFloat(msg.ts ?? "0");
    const time = new Date(ts * 1000).toLocaleTimeString("en-US", {
      hour: "2-digit",
      minute: "2-digit",
      hour12: false,
    });
    const user = msg.user ?? "unknown";
    const text = this.cleanSlackMarkup(msg.text ?? "");

    let formatted = `[${time}] ${user}: ${text}`;

    if (msg.files && msg.files.length > 0) {
      const fileNames = msg.files
        .map((f) => f.title ?? f.name ?? "attachment")
        .join(", ");
      formatted += ` [Attachments: ${fileNames}]`;
    }

    if (msg.reply_count && msg.reply_count > 0) {
      formatted += ` (${msg.reply_count} ${msg.reply_count === 1 ? "reply" : "replies"} in thread)`;
    }

    return formatted;
  }

  private cleanSlackMarkup(text: string): string {
    return (
      text
        .replace(/<@([A-Z0-9]+)>/g, "@$1")
        .replace(/<#[A-Z0-9]+\|([^>]+)>/g, "#$1")
        .replace(/<(https?:\/\/[^|>]+)\|([^>]+)>/g, "$2 ($1)")
        .replace(/<(https?:\/\/[^>]+)>/g, "$1")
        .replace(/&amp;/g, "&")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
    );
  }
}

/** @deprecated Use JsonExportAdapter instead */
export const SlackExportAdapter = JsonExportAdapter;

import type { ProviderResult } from "../types";
import type { NERProvider, NERResult, ChunkEntities } from "./index";
import { resolveBaseUrl, resolveApiKey, resolveModel } from "../registry";
import OpenAI from "openai";

/**
 * Token cost per NER chunk (~500 tokens of prompt + completion averaged).
 * LLM responses do return usage, but we bill a flat rate per chunk for
 * predictability and to match the historical cost table.
 */
const NER_TOKENS_PER_CHUNK = 500;

const NER_SYSTEM_PROMPT = `You are a named entity recognition (NER) system. Extract entities from the given text.

For each entity found, provide:
- "text": the entity text as it appears
- "label": one of PER, ORG, LOC, DATE, MONEY, EVENT, PRODUCT, LAW, MISC
- "score": your confidence from 0.0 to 1.0

Return a JSON array of entities. If no entities are found, return an empty array.
Only return the JSON array, no other text.`;

const BATCH_SIZE = 5;

/**
 * LLM-based NER provider using OpenAI-compatible chat completions.
 * Works with OpenAI, SiliconFlow (Qwen3.5-4B free), DeepSeek, etc.
 */
export class LLMNERProvider implements NERProvider {
    name: string;
    private client: OpenAI;
    private model: string;

    constructor() {
        // No default: this provider works against any OpenAI-compatible
        // endpoint, so the operator names it.
        const baseURL = resolveBaseUrl(process.env.NER_API_BASE_URL);
        const apiKey = resolveApiKey(
            process.env.NER_API_KEY,
            process.env.OPENAI_API_KEY,
        );
        this.model = resolveModel(
            process.env.NER_MODEL,
            "gpt-4o-mini",
        );
        this.name = `ner:${this.model}`;

        this.client = new OpenAI({ apiKey, baseURL });
    }

    async extract(chunks: string[]): Promise<ProviderResult<NERResult>> {
        const results: ChunkEntities[] = [];
        let totalEntities = 0;

        for (let i = 0; i < chunks.length; i += BATCH_SIZE) {
            const batch = chunks.slice(i, i + BATCH_SIZE);
            const batchResults = await this.extractBatch(batch);
            results.push(...batchResults);
            totalEntities += batchResults.reduce(
                (sum, r) => sum + r.entities.length,
                0
            );
        }

        return {
            data: { results, totalEntities },
            usage: {
                tokensUsed: chunks.length * NER_TOKENS_PER_CHUNK,
                details: { chunks: chunks.length, totalEntities },
            },
        };
    }

    private async extractBatch(chunks: string[]): Promise<ChunkEntities[]> {
        const numberedChunks = chunks
            .map((c, i) => `--- Chunk ${i + 1} ---\n${c.slice(0, 2048)}`)
            .join("\n\n");

        const userPrompt =
            chunks.length === 1
                ? `Extract entities from this text:\n\n${chunks[0]!.slice(0, 2048)}`
                : `Extract entities from each chunk below. Return a JSON array where each element corresponds to a chunk and contains an "entities" array.\n\n${numberedChunks}`;

        const response = await this.client.chat.completions.create({
            model: this.model,
            temperature: 0,
            response_format: { type: "json_object" },
            messages: [
                { role: "system", content: NER_SYSTEM_PROMPT },
                { role: "user", content: userPrompt },
            ],
        });

        const usage = response.usage;
        if (usage) {
            console.log(
                `[NER] ${this.name}: ${chunks.length} chunks, ${usage.prompt_tokens} prompt + ${usage.completion_tokens} completion = ${usage.total_tokens} tokens`
            );
        }

        const content = response.choices[0]?.message?.content ?? "{}";

        try {
            const parsed = JSON.parse(content) as
                | { entities: Array<{ text: string; label: string; score: number }> }
                | { chunks: Array<{ entities: Array<{ text: string; label: string; score: number }> }> }
                | Array<{ text: string; label: string; score: number }>;

            if (chunks.length === 1) {
                const entities = Array.isArray(parsed)
                    ? parsed
                    : "entities" in parsed
                      ? parsed.entities
                      : [];
                return [{ text: chunks[0]!, entities }];
            }

            if ("chunks" in parsed && Array.isArray(parsed.chunks)) {
                return chunks.map((text, i) => ({
                    text,
                    entities: parsed.chunks[i]?.entities ?? [],
                }));
            }

            const allEntities = Array.isArray(parsed)
                ? parsed
                : "entities" in parsed
                  ? parsed.entities
                  : [];
            return chunks.map((text, i) => ({
                text,
                entities: i === 0 ? allEntities : [],
            }));
        } catch {
            console.warn("[LLM-NER] Failed to parse response, returning empty entities");
            return chunks.map((text) => ({ text, entities: [] }));
        }
    }
}

import type { ProviderResult } from "../types";
import type { NERProvider, NERResult, ChunkEntities } from "./index";

const SIDECAR_URL = process.env.SIDECAR_URL ?? "http://localhost:8000";

export class SidecarNERProvider implements NERProvider {
    name = "sidecar";

    async extract(chunks: string[]): Promise<ProviderResult<NERResult>> {
        const resp = await fetch(`${SIDECAR_URL}/extract-entities`, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify({ chunks }),
        });

        if (!resp.ok) {
            throw new Error(`Sidecar NER failed (${resp.status})`);
        }

        const data = (await resp.json()) as {
            results: ChunkEntities[];
            total_entities: number;
        };

        return {
            data: {
                results: data.results,
                totalEntities: data.total_entities,
            },
            usage: {
                tokensUsed: 0, // Self-hosted = free
                details: { chunks: chunks.length, totalEntities: data.total_entities },
            },
        };
    }
}

import type { ProviderResult } from "../types";
import type { RerankProvider, RerankResult } from "./index";
import { resolveBaseUrl, resolveApiKey, resolveModel } from "../registry";

/**
 * Token cost per rerank query. This is the provider's billing rate (rerank
 * APIs don't return token counts in their responses), so the value is baked
 * in here rather than computed from the request shape. Apps that want a
 * different cost ratio can patch this file when bundling or wrap the
 * provider with their own accounting layer.
 */
const RERANK_TOKENS_PER_QUERY = 200;

/**
 * OpenAI-compatible reranking provider.
 * Works with Jina AI, SiliconFlow, and any provider that supports
 * POST /v1/rerank with {model, query, documents, top_n}.
 *
 * Resolution: RERANK_API_* → AI_BASE_URL/AI_API_KEY → JINA_API_KEY → defaults
 */
export class OpenAICompatibleRerankProvider implements RerankProvider {
    name: string;
    private baseUrl: string;
    private apiKey: string;
    private model: string;

    constructor() {
        this.baseUrl = resolveBaseUrl(
            process.env.RERANK_API_BASE_URL,
            "https://api.jina.ai/v1",
        );
        this.apiKey = resolveApiKey(
            process.env.RERANK_API_KEY,
            process.env.JINA_API_KEY,
        );
        this.model = resolveModel(
            process.env.RERANK_MODEL,
            "jina-reranker-v2-base-multilingual",
        );
        this.name = `rerank:${this.model}`;

        if (!this.apiKey) {
            console.warn("[Rerank] No API key found (RERANK_API_KEY / AI_API_KEY / JINA_API_KEY)");
        }
    }

    async rerank(
        query: string,
        documents: string[]
    ): Promise<ProviderResult<RerankResult>> {
        const resp = await fetch(`${this.baseUrl}/rerank`, {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                Authorization: `Bearer ${this.apiKey}`,
            },
            body: JSON.stringify({
                model: this.model,
                query,
                documents,
                top_n: documents.length,
            }),
        });

        if (!resp.ok) {
            const text = await resp.text();
            throw new Error(`Rerank failed (${resp.status}): ${text}`);
        }

        const data = (await resp.json()) as {
            results: Array<{ index: number; relevance_score: number }>;
        };

        const scores = new Array<number>(documents.length).fill(0);
        for (const result of data.results) {
            scores[result.index] = result.relevance_score;
        }

        return {
            data: { scores },
            usage: {
                tokensUsed: RERANK_TOKENS_PER_QUERY,
                details: { documents: documents.length },
            },
        };
    }
}

