/**
 * Whisper.js — Local speech-to-text using sherpa-onnx-node
 *
 * Runs the Whisper ONNX model via native bindings (no Python needed).
 * Same model quality as the Python sidecar, with prebuilt binaries
 * for Mac, Linux, and Windows — no C++ compiler required.
 *
 * Model files must be downloaded to /models/sherpa-onnx-whisper-base.en/
 * Run: scripts/ops/download-whisper-model.sh
 */

import { execFile } from "node:child_process";
import { writeFile, unlink, access } from "node:fs/promises";
import { tmpdir } from "node:os";
import { join, resolve } from "node:path";
import { randomUUID } from "node:crypto";
import type { TranscriptSegment, TranscriptionResult } from "./transcription";

const MODEL_DIR = resolve(process.cwd(), "models", "sherpa-onnx-whisper-base.en");

let recognizerInstance: unknown | null = null;

async function getRecognizer() {
  if (recognizerInstance) return recognizerInstance;

  // Check model files exist
  const encoderPath = join(MODEL_DIR, "base.en-encoder.int8.onnx");
  const decoderPath = join(MODEL_DIR, "base.en-decoder.int8.onnx");
  const tokensPath = join(MODEL_DIR, "base.en-tokens.txt");

  try {
    await access(encoderPath);
    await access(decoderPath);
    await access(tokensPath);
  } catch {
    throw new Error(
      `Whisper model not found at ${MODEL_DIR}. ` +
      `Download it: cd models && curl -L -o model.tar.bz2 "https://github.com/k2-fsa/sherpa-onnx/releases/download/asr-models/sherpa-onnx-whisper-base.en.tar.bz2" && tar -xjf model.tar.bz2 && rm model.tar.bz2`
    );
  }

  console.log(`[WhisperJS] Loading sherpa-onnx model from ${MODEL_DIR}...`);
  const startTime = Date.now();

  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const sherpa = require("sherpa-onnx-node") as typeof import("sherpa-onnx-node");

  const recognizer = new sherpa.OfflineRecognizer({
    modelConfig: {
      whisper: {
        encoder: encoderPath,
        decoder: decoderPath,
        language: "en",
        task: "transcribe",
      },
      tokens: tokensPath,
      numThreads: 2,
      provider: "cpu",
    },
  });

  const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
  console.log(`[WhisperJS] Model loaded in ${elapsed}s`);

  recognizerInstance = recognizer;
  return recognizer;
}

/**
 * Decode audio bytes to 16kHz mono Float32Array using ffmpeg.
 */
async function decodeAudioWithFFmpeg(audioBytes: Buffer | Uint8Array): Promise<Float32Array> {
  const id = randomUUID();
  const inputPath = join(tmpdir(), `whisper-input-${id}`);
  const outputPath = join(tmpdir(), `whisper-output-${id}.raw`);

  try {
    await writeFile(inputPath, audioBytes);

    await new Promise<void>((resolve, reject) => {
      execFile(
        "ffmpeg",
        [
          "-i", inputPath,
          "-ar", "16000",
          "-ac", "1",
          "-f", "f32le",
          "-y",
          outputPath,
        ],
        { timeout: 60_000 },
        (error, _stdout, stderr) => {
          if (error) {
            console.error(`[WhisperJS] ffmpeg error: ${stderr}`);
            reject(new Error(`ffmpeg failed: ${error.message}`));
          } else {
            resolve();
          }
        },
      );
    });

    const { readFile } = await import("node:fs/promises");
    const pcmBuffer = await readFile(outputPath);
    const float32 = new Float32Array(pcmBuffer.buffer, pcmBuffer.byteOffset, pcmBuffer.length / 4);

    console.log(`[WhisperJS] Decoded audio: ${float32.length} samples (${(float32.length / 16000).toFixed(1)}s)`);
    return float32;
  } finally {
    await unlink(inputPath).catch(() => {});
    await unlink(outputPath).catch(() => {});
  }
}

/**
 * Transcribe audio using sherpa-onnx (native Whisper, no Python needed).
 */
export async function transcribeWithWhisperJS(
  audioBytes: Buffer | Uint8Array,
  filename: string,
): Promise<TranscriptionResult> {
  console.log(`[WhisperJS] Transcribing: ${filename} (${audioBytes.length} bytes)`);
  const startTime = Date.now();

  const recognizer = await getRecognizer() as {
    createStream: () => {
      acceptWaveform: (opts: { sampleRate: number; samples: Float32Array }) => void;
    };
    decode: (stream: unknown) => void;
    getResult: (stream: unknown) => { text: string; timestamps?: number[]; tokens?: string[] };
  };

  const audioData = await decodeAudioWithFFmpeg(audioBytes);

  // Process in smaller chunks for more frequent timestamps
  const CHUNK_SIZE = 16000 * 5; // 5 seconds of audio
  const segments: TranscriptSegment[] = [];
  let fullText = "";

  for (let offset = 0; offset < audioData.length; offset += CHUNK_SIZE) {
    const end = Math.min(offset + CHUNK_SIZE, audioData.length);
    const chunk = audioData.subarray(offset, end);
    const chunkStartTime = offset / 16000;

    const stream = recognizer.createStream();
    stream.acceptWaveform({ sampleRate: 16000, samples: chunk });
    recognizer.decode(stream);

    const result = recognizer.getResult(stream);
    const text = result.text.trim();

    if (text) {
      fullText += (fullText ? " " : "") + text;
      segments.push({
        start: chunkStartTime,
        end: Math.min(chunkStartTime + (end - offset) / 16000, audioData.length / 16000),
        text,
      });
    }
  }

  const elapsed = ((Date.now() - startTime) / 1000).toFixed(1);
  console.log(
    `[WhisperJS] Complete: ${filename} → ${fullText.length} chars, ${segments.length} segments (${elapsed}s)`,
  );

  return {
    text: fullText,
    language: "en",
    confidence: 0.0,
    filename,
    segments,
  };
}

/**
 * Document complexity analysis and OCR routing.
 * Standalone version for the ocr-router sidecar — no Next.js dependencies.
 *
 * Vision backend priority:
 *   1. OpenAI-compatible API (if OPENAI_API_KEY or AI_API_KEY is set)
 *   2. Local SigLIP via @huggingface/transformers (WASM fallback)
 */

import { PDFDocument } from "pdf-lib";

type OCRProvider =
  | "AZURE"
  | "LANDING_AI"
  | "NATIVE_PDF"
  | "DATALAB"
  | "DOCLING"
  | "MARKER"
  | "INGESTION";

const SAMPLING_CONFIG = {
  MIN_PAGES_TO_SAMPLE: 3,
  MAX_PAGES_TO_SAMPLE: 5,
  VISION_MODEL_ID: "google/siglip-base-patch16-224",
  CONFIDENCE_THRESHOLD: 0.6,
};

const COMPLEX_LABELS = [
  "handwritten notes",
  "messy scanned document",
  "receipt or invoice",
  "complex table structure",
];

const SIMPLE_LABELS = [
  "digital text document",
  "clean screenshot",
  "blank page",
];

const ALL_COMPLEXITY_LABELS = [...COMPLEX_LABELS, ...SIMPLE_LABELS];

interface VisionClassification {
  label: string;
  score: number;
}

export interface RoutingDecision {
  provider: OCRProvider;
  reason: string;
  confidence: number;
  pageCount: number;
  visionResult?: VisionClassification;
}

// ── Helpers ────────────────────────────────────────────────────────────

export function selectSamplePages(totalPages: number): number[] {
  if (totalPages <= SAMPLING_CONFIG.MIN_PAGES_TO_SAMPLE) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }

  const pages = new Set<number>();
  pages.add(1);
  pages.add(Math.ceil(totalPages / 2));
  pages.add(totalPages);

  if (totalPages > 20) {
    const randomPage = Math.floor(Math.random() * (totalPages - 2)) + 2;
    pages.add(randomPage);
  }

  return Array.from(pages)
    .sort((a, b) => a - b)
    .slice(0, SAMPLING_CONFIG.MAX_PAGES_TO_SAMPLE);
}

// ── Vision backends ────────────────────────────────────────────────────

const OPENAI_CLASSIFY_PROMPT = `You are a document classifier. Analyze this image of a document page and classify it into EXACTLY ONE of these categories:

- "handwritten notes" — handwriting, pen/pencil marks
- "messy scanned document" — skewed, blurry, noisy scan
- "receipt or invoice" — receipts, invoices, financial forms
- "complex table structure" — dense tables, spreadsheet-like layouts
- "digital text document" — clean digital text, typed content
- "clean screenshot" — screenshot of a screen or app
- "blank page" — mostly empty

Respond with ONLY a JSON object: {"label": "<category>", "score": <confidence 0-1>}`;

async function runVisionCheckOpenAI(
  images: Uint8Array[]
): Promise<VisionClassification> {
  const apiKey =
    process.env.OPENAI_API_KEY || process.env.AI_API_KEY || "";
  // No default endpoint: any OpenAI-compatible vision endpoint works, so the
  // operator names it rather than the code silently choosing a vendor.
  const baseUrl = process.env.AI_BASE_URL;
  if (!baseUrl) {
    throw new Error(
      "AI_BASE_URL is not set. Point it at an OpenAI-compatible vision " +
        "endpoint — there is no built-in default endpoint.",
    );
  }
  const model = process.env.OCR_VISION_MODEL || "gpt-4o-mini";

  console.log(`[OCR Router] Using vision model ${model} for classification`);

  let maxComplexityScore = 0;
  let dominantLabel = "digital text document";

  // Classify first image only (cost-effective — representative sample)
  const image = images[0];
  if (!image) return { label: dominantLabel, score: 0 };

  const b64 = Buffer.from(image).toString("base64");

  const response = await fetch(`${baseUrl}/chat/completions`, {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${apiKey}`,
    },
    body: JSON.stringify({
      model,
      max_tokens: 100,
      messages: [
        {
          role: "user",
          content: [
            { type: "text", text: OPENAI_CLASSIFY_PROMPT },
            {
              type: "image_url",
              image_url: { url: `data:image/png;base64,${b64}`, detail: "low" },
            },
          ],
        },
      ],
    }),
  });

  if (!response.ok) {
    const err = await response.text();
    throw new Error(`OpenAI vision failed (${response.status}): ${err}`);
  }

  const data = (await response.json()) as {
    choices: Array<{ message: { content: string } }>;
  };
  const content = data.choices[0]?.message?.content ?? "";

  try {
    // Parse JSON from response (handle markdown code blocks)
    const jsonStr = content.replace(/```json?\n?/g, "").replace(/```/g, "").trim();
    const parsed = JSON.parse(jsonStr) as { label: string; score: number };

    if (
      COMPLEX_LABELS.includes(parsed.label) &&
      parsed.score > maxComplexityScore
    ) {
      maxComplexityScore = parsed.score;
      dominantLabel = parsed.label;
    } else if (ALL_COMPLEXITY_LABELS.includes(parsed.label)) {
      dominantLabel = parsed.label;
      maxComplexityScore = parsed.score;
    }
  } catch {
    console.warn("[OCR Router] Failed to parse OpenAI vision response:", content);
  }

  return { label: dominantLabel, score: maxComplexityScore };
}

async function runVisionCheckSigLIP(
  images: Uint8Array[]
): Promise<VisionClassification> {
  console.log(
    "[OCR Router] Using local SigLIP model for classification (WASM)..."
  );
  const { pipeline } = await import("@huggingface/transformers");

  const classifier = await pipeline(
    "zero-shot-image-classification",
    SAMPLING_CONFIG.VISION_MODEL_ID
  );

  let maxComplexityScore = 0;
  let dominantLabel = "digital text document";

  for (const image of images) {

    const result = (await classifier(
      image as any,
      ALL_COMPLEXITY_LABELS
    )) as Array<{ label: string; score: number }>;
    const topMatch = result[0];

    if (topMatch && COMPLEX_LABELS.includes(topMatch.label)) {
      if (topMatch.score > maxComplexityScore) {
        maxComplexityScore = topMatch.score;
        dominantLabel = topMatch.label;
      }
    }
  }

  if (maxComplexityScore === 0 && images.length > 0) {

    const result = (await classifier(
      images[0] as any,
      ALL_COMPLEXITY_LABELS
    )) as Array<{ label: string; score: number }>;
    const firstResult = result[0];
    if (firstResult) {
      return { label: firstResult.label, score: firstResult.score };
    }
  }

  return { label: dominantLabel, score: maxComplexityScore };
}

/**
 * Run vision classification using the best available backend.
 * Prefers OpenAI (fast, accurate) over local SigLIP (free, slower).
 */
async function runVisionCheck(
  images: Uint8Array[]
): Promise<VisionClassification> {
  const hasOpenAI =
    process.env.OPENAI_API_KEY || process.env.AI_API_KEY;

  if (hasOpenAI) {
    try {
      return await runVisionCheckOpenAI(images);
    } catch (err) {
      console.warn(
        "[OCR Router] OpenAI vision failed, falling back to SigLIP:",
        err instanceof Error ? err.message : err
      );
    }
  }

  return runVisionCheckSigLIP(images);
}

// ── PDF rendering ──────────────────────────────────────────────────────

export async function renderPagesToImages(
  buffer: ArrayBuffer,
  pageIndices: number[]
): Promise<Uint8Array[]> {
  try {
    const { fromBuffer } = await import("pdf2pic");

    const converter = fromBuffer(Buffer.from(buffer), {
      density: 200,
      format: "png",
      width: 1024,
      height: 1448,
    });

    const images: Uint8Array[] = [];

    for (const pageIndex of pageIndices) {
      try {
        const result = await converter(pageIndex, { responseType: "buffer" });
        if (result?.buffer) {
          images.push(result.buffer);
        }
      } catch (pageError: unknown) {
        const errorMessage =
          pageError instanceof Error ? pageError.message : String(pageError);
        if (!errorMessage.includes("page number")) {
          console.warn(`Failed to render page ${pageIndex}:`, pageError);
        }
      }
    }

    return images;
  } catch (error: unknown) {
    const errorMessage =
      error instanceof Error ? error.message : "unknown error";
    console.warn(
      `PDF rendering unavailable (${errorMessage}), falling back to OCR`
    );
    return [];
  }
}

// ── Provider selection ─────────────────────────────────────────────────

function getDefaultOCRProvider(): OCRProvider {
  const configured = process.env.OCR_DEFAULT_PROVIDER?.toUpperCase();
  if (
    configured &&
    ["MARKER", "DOCLING", "NATIVE_PDF", "AZURE", "LANDING_AI", "DATALAB"].includes(configured)
  ) {
    return configured as OCRProvider;
  }
  // Default: Docling (self-hosted, zero cost) > cloud providers > NATIVE_PDF
  if (process.env.OCR_WORKER_URL) return "DOCLING";
  if (
    process.env.AZURE_DOC_INTELLIGENCE_KEY &&
    process.env.AZURE_DOC_INTELLIGENCE_ENDPOINT
  )
    return "AZURE";
  if (process.env.LANDING_AI_API_KEY) return "LANDING_AI";
  if (process.env.DATALAB_API_KEY) return "DATALAB";
  return "DOCLING";
}

function getComplexDocProvider(): OCRProvider {
  if (process.env.OCR_WORKER_URL) return "DOCLING";
  if (process.env.LANDING_AI_API_KEY) return "LANDING_AI";
  if (
    process.env.AZURE_DOC_INTELLIGENCE_KEY &&
    process.env.AZURE_DOC_INTELLIGENCE_ENDPOINT
  )
    return "AZURE";
  if (process.env.DATALAB_API_KEY) return "DATALAB";
  return "DOCLING";
}

// ── Main routing logic ─────────────────────────────────────────────────

export async function determineDocumentRouting(
  documentUrl: string
): Promise<RoutingDecision> {
  const response = await fetch(documentUrl);
  const buffer = await response.arrayBuffer();

  let pageCount = 0;
  let hasInteractiveForms = false;

  try {
    const doc = await PDFDocument.load(buffer, { ignoreEncryption: true });
    pageCount = doc.getPageCount();
    hasInteractiveForms = doc.getForm().getFields().length > 0;

    if (hasInteractiveForms) {
      return {
        provider: "NATIVE_PDF",
        reason: "Interactive form fields detected",
        confidence: 0.99,
        pageCount,
      };
    }
  } catch (e) {
    console.warn(
      "PDF Structure load failed, assuming standard processing needed",
      e
    );
    pageCount = 1;
  }

  try {
    const pdfParse = (await import("pdf-parse")).default;
    const data = await pdfParse(new Uint8Array(buffer));
    const sampleText = data.text.substring(0, 200).trim();

    if (sampleText.length > 50) {
      return {
        provider: "NATIVE_PDF",
        reason: `Text layer detected (sampled ~${sampleText.length} chars)`,
        confidence: 0.95,
        pageCount: pageCount || data.numpages,
      };
    }
  } catch (e: unknown) {
    const err = e as { code?: string; path?: string };
    if (err.code !== "ENOENT" || !err.path?.includes("test/data")) {
      console.warn("Text extraction failed, proceeding to vision check.", e);
    }
  }

  try {
    const pagesToSample = selectSamplePages(pageCount);
    const images = await renderPagesToImages(buffer, pagesToSample);

    if (images.length === 0) {
      const fallback = getDefaultOCRProvider();
      return {
        provider: fallback,
        reason: `No text layer detected, using ${fallback}`,
        confidence: 0.5,
        pageCount,
      };
    }

    const visionResult = await runVisionCheck(images);

    if (
      COMPLEX_LABELS.includes(visionResult.label) &&
      visionResult.score > SAMPLING_CONFIG.CONFIDENCE_THRESHOLD
    ) {
      const complexProvider = getComplexDocProvider();
      return {
        provider: complexProvider,
        reason: `Vision detected '${visionResult.label}', using ${complexProvider}`,
        confidence: visionResult.score,
        visionResult,
        pageCount,
      };
    }

    const cleanFallback = getDefaultOCRProvider();
    return {
      provider: cleanFallback,
      reason: `Vision detected clean layout '${visionResult.label}', using ${cleanFallback}`,
      confidence: visionResult.score,
      visionResult,
      pageCount,
    };
  } catch (error: unknown) {
    const errorMessage =
      error instanceof Error ? error.message : String(error);
    const errorFallback = getDefaultOCRProvider();
    if (!errorMessage.includes("ENOENT")) {
      console.warn(
        `Vision routing failed, defaulting to ${errorFallback}:`,
        errorMessage
      );
    }
    return {
      provider: errorFallback,
      reason: `Defaulting to ${errorFallback}`,
      confidence: 0.5,
      pageCount,
    };
  }
}

import express from "express";
import { determineDocumentRouting, renderPagesToImages } from "./complexity.js";

const app = express();

// Accept large PDF buffers
app.use(express.json({ limit: "100mb" }));

app.get("/health", (_req, res) => {
  res.json({ status: "ok" });
});

/**
 * POST /route
 * Accepts a document URL, returns a routing decision (which OCR provider to use).
 * Body: { documentUrl: string, env: { OCR_DEFAULT_PROVIDER?, OCR_WORKER_URL?, AZURE_DOC_INTELLIGENCE_KEY?, ... } }
 */
app.post("/route", async (req, res) => {
  try {
    const { documentUrl, env } = req.body as {
      documentUrl: string;
      env?: Record<string, string>;
    };

    if (!documentUrl) {
      res.status(400).json({ error: "documentUrl is required" });
      return;
    }

    // Inject env vars so the routing logic can check provider availability
    if (env) {
      for (const [key, value] of Object.entries(env)) {
        process.env[key] = value;
      }
    }

    const decision = await determineDocumentRouting(documentUrl);
    res.json(decision);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("Route decision failed:", message);
    res.status(500).json({ error: message });
  }
});

/**
 * POST /render-pages
 * Accepts a PDF buffer + page indices, returns rendered PNG images as base64.
 * Body: { buffer: string (base64), pageIndices: number[] }
 */
app.post("/render-pages", async (req, res) => {
  try {
    const { buffer, pageIndices } = req.body as {
      buffer: string;
      pageIndices: number[];
    };

    if (!buffer || !pageIndices) {
      res.status(400).json({ error: "buffer (base64) and pageIndices are required" });
      return;
    }

    const pdfBuffer = Buffer.from(buffer, "base64");
    const images = await renderPagesToImages(pdfBuffer.buffer, pageIndices);

    // Return images as base64 strings
    const imagesBase64 = images.map((img) => Buffer.from(img).toString("base64"));
    res.json({ images: imagesBase64 });
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error("Page rendering failed:", message);
    res.status(500).json({ error: message });
  }
});

const port = parseInt(process.env.PORT ?? "8002", 10);
app.listen(port, "0.0.0.0", () => {
  console.log(`OCR Router listening on port ${port}`);
});
